(383918,42658,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il m''a dit que son chien ... à côté de lui quand il a marqué.'::text,'courait'::text,'a couru'::text,'a couru'::text,'Écoute, il m''a dit que son chien courait à côté de lui quand il a marqué.'::text),
(383921,42658,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, o bana gol attığında köpeğinin yanında ... söyledi.'::text,'koştuğunu'::text,'koştuğunu'::text,'koşmuş olduğunu'::text,'Dinle, o bana gol attığında köpeğinin yanında koştuğunu söyledi.'::text),
(383922,42658,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, ő azt mondta, hogy a kutyája ... mellette, amikor gólt rúgott.'::text,'futott'::text,'futott'::text,'futott'::text,'Figyelj, ő azt mondta, hogy a kutyája futott mellette, amikor gólt rúgott.'::text),
(384006,42668,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Krass, ich hab gehört, bis Ende des Sommers ... er fünfzig Tore in dem Park.'::text,'schießt'::text,'schießt'::text,'schießt'::text,'Krass, ich hab gehört, bis Ende des Sommers schießt er fünfzig Tore in dem Park.'::text),
(384010,42668,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Та ну, я чув, що до кінця літа він ... п''ятдесят голів у тому парку.'::text,'заб''є'::text,'заб''є'::text,'забиває'::text,'Та ну, я чув, що до кінця літа він заб''є п''ятдесят голів у тому парку.'::text),
(384009,42668,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No puede ser, yo oí que para finales del verano él ... cincuenta goles en ese parque.'::text,'habrá marcado'::text,'marcará'::text,'marca'::text,'No puede ser, yo oí que para finales del verano él habrá marcado cincuenta goles en ese parque.'::text),
(384008,42668,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pas possible, j''ai entendu dire que d''ici la fin de l''été il ... cinquante buts dans ce parc.'::text,'aura marqué'::text,'marquera'::text,'marque'::text,'Pas possible, j''ai entendu dire que d''ici la fin de l''été il aura marqué cinquante buts dans ce parc.'::text),
(384011,42668,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Olamaz, ben duydum ki yaz sonuna kadar o parkta elli gol ...'::text,'atmış olacakmış'::text,'atacakmış'::text,'atıyormuş'::text,'Olamaz, ben duydum ki yaz sonuna kadar o parkta elli gol atmış olacakmış.'::text),
(384012,42668,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez nem lehet, én úgy hallottam, a nyár végére ötven gólt ... abban a parkban.'::text,'fog rúgni'::text,'fog rúgni'::text,'rúg'::text,'Ez nem lehet, én úgy hallottam, a nyár végére ötven gólt fog rúgni abban a parkban.'::text),
(361812,40202,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn Kunden einen Verkäufer in einer Tür ..., sitzt er typischerweise am Ende allein da.'::text,'ignorieren'::text,'ignorierten'::text,'ignorieren werden'::text,'Wenn Kunden einen Verkäufer in einer Tür ignorieren, sitzt er typischerweise am Ende allein da.'::text),
(361816,40202,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо покупці ... продавця у дверях, він зазвичай зрештою сидить сам.'::text,'ігнорують'::text,'ігнорували'::text,'ігноруватимуть'::text,'Якщо покупці ігнорують продавця у дверях, він зазвичай зрештою сидить сам.'::text),
(361815,40202,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si los compradores ... a un vendedor en una puerta, él suele acabar sentado solo.'::text,'ignoran'::text,'ignoraron'::text,'ignorarán'::text,'Si los compradores ignoran a un vendedor en una puerta, él suele acabar sentado solo.'::text),
(361814,40202,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si les clients ... un vendeur sur le pas d''une porte, il finit généralement assis tout seul.'::text,'ignorent'::text,'ignoraient'::text,'ignoreront'::text,'Si les clients ignorent un vendeur sur le pas d''une porte, il finit généralement assis tout seul.'::text),
(361817,40202,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Müşteriler kapı eşiğindeki bir satıcıyı ..., o genellikle sonunda tek başına oturur.'::text,'görmezden gelirlerse'::text,'görmezden geldilerse'::text,'görmezden geleceklerse'::text,'Müşteriler kapı eşiğindeki bir satıcıyı görmezden gelirlerse, o genellikle sonunda tek başına oturur.'::text),
(361818,40202,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a vásárlók ... egy ajtóban álló eladót, ő jellemzően végül egyedül ül.'::text,'figyelmen kívül hagyják'::text,'figyelmen kívül hagyták'::text,'figyelmen kívül fogják hagyni'::text,'Ha a vásárlók figyelmen kívül hagyják egy ajtóban álló eladót, ő jellemzően végül egyedül ül.'::text),
(361875,40209,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, er sollte diese SALE-Plakate ... lassen, weil alle sie ignorieren.'::text,'austauschen'::text,'austauschen'::text,'auszutauschen'::text,'Alter, er sollte diese SALE-Plakate austauschen lassen, weil alle sie ignorieren.'::text),
(361879,40209,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, він мав би дати комусь ... ті плакати SALE, бо всі їх ігнорують.'::text,'замінити'::text,'замінити'::text,'замінити'::text,'Чувак, він мав би дати комусь замінити ті плакати SALE, бо всі їх ігнорують.'::text),
(361878,40209,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, él debería mandar ... esos carteles de SALE, porque todo el mundo los ignora.'::text,'cambiar'::text,'cambiar'::text,'a cambiar'::text,'Tío, él debería mandar cambiar esos carteles de SALE, porque todo el mundo los ignora.'::text),
(361877,40209,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, il devrait faire ... ces affiches SALE, parce que tout le monde les ignore.'::text,'remplacer'::text,'remplacer'::text,'à remplacer'::text,'Mec, il devrait faire remplacer ces affiches SALE, parce que tout le monde les ignore.'::text),
(361880,40209,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o şu SALE afişlerini ..., çünkü herkes onları görmezden geliyor.'::text,'değiştirtmeli'::text,'değiştirmeli'::text,'değiştirmeye'::text,'Kanka, o şu SALE afişlerini değiştirtmeli, çünkü herkes onları görmezden geliyor.'::text),
(361881,40209,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ő jobban tenné, ha ... azokat a SALE-plakátokat, mert mindenki levegőnek nézi őket.'::text,'lecseréltetné'::text,'lecserélné'::text,'lecserélné'::text,'Tesó, ő jobban tenné, ha lecseréltetné azokat a SALE-plakátokat, mert mindenki levegőnek nézi őket.'::text),
(351930,39104,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er noch 2 Bären gewinnt, ... der Jahrmarkt sein Preisbudget für den Tag.'::text,'überschreitet'::text,'überschritte'::text,'überschreitet'::text,'Wenn er noch 2 Bären gewinnt, überschreitet der Jahrmarkt sein Preisbudget für den Tag.'::text),
(351934,39104,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо він виграє ще 2 ведмедики, ярмарок ... свій денний бюджет на призи.'::text,'перевищить'::text,'перевищив би'::text,'перевищує'::text,'Якщо він виграє ще 2 ведмедики, ярмарок перевищить свій денний бюджет на призи.'::text),
(351933,39104,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si él gana 2 osos más, la feria ... su presupuesto de premios del día.'::text,'superará'::text,'superaría'::text,'supera'::text,'Si él gana 2 osos más, la feria superará su presupuesto de premios del día.'::text),
(351932,39104,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il gagne encore 2 ours, la fête foraine ... son budget de lots pour la journée.'::text,'dépassera'::text,'dépasserait'::text,'dépasse'::text,'S''il gagne encore 2 ours, la fête foraine dépassera son budget de lots pour la journée.'::text),
(351935,39104,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O 2 ayı daha kazanırsa, lunapark günlük ödül bütçesini ...'::text,'aşacak'::text,'aşardı'::text,'aşıyor'::text,'O 2 ayı daha kazanırsa, lunapark günlük ödül bütçesini aşacak.'::text),
(351936,39104,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha ő még 2 macit nyer, a vidámpark ... a napi nyereménykeretét.'::text,'túllépi'::text,'túllépné'::text,'túllépi'::text,'Ha ő még 2 macit nyer, a vidámpark túllépi a napi nyereménykeretét.'::text),
(351966,39108,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... der eisigen Kälte gab er ihr seine Jacke, bevor der Jahrmarkt zur totalen Katastrophe wurde!'::text,'Wegen'::text,'Trotz'::text,'Vorausgesetzt'::text,'Wegen der eisigen Kälte gab er ihr seine Jacke, bevor der Jahrmarkt zur totalen Katastrophe wurde!'::text),
(351970,39108,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... лютий холод він віддав їй свою куртку, перш ніж ярмарок перетворився на повну катастрофу!'::text,'Через'::text,'Попри'::text,'За умови'::text,'Через лютий холод він віддав їй свою куртку, перш ніж ярмарок перетворився на повну катастрофу!'::text),
(351969,39108,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... el frío helador, él le dio su chaqueta antes de que la feria se convirtiera en un desastre total!'::text,'Debido a'::text,'A pesar de'::text,'Siempre que'::text,'¡Debido a el frío helador, él le dio su chaqueta antes de que la feria se convirtiera en un desastre total!'::text),
(351968,39108,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... froid glacial, il lui a donné sa veste avant que la fête foraine tourne au désastre total !'::text,'En raison du'::text,'Malgré le'::text,'Pourvu que le'::text,'En raison du froid glacial, il lui a donné sa veste avant que la fête foraine tourne au désastre total !'::text),
(351971,39108,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dondurucu soğuk ..., o lunapark tam bir felakete dönmeden önce ona ceketini verdi!'::text,'yüzünden'::text,'rağmen'::text,'şartıyla'::text,'Dondurucu soğuk yüzünden, o lunapark tam bir felakete dönmeden önce ona ceketini verdi!'::text),
(351972,39108,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fagyos hideg ... ő odaadta neki a dzsekijét, mielőtt a vidámpark totális katasztrófába fulladt volna!'::text,'miatt'::text,'ellenére'::text,'feltéve'::text,'A fagyos hideg miatt ő odaadta neki a dzsekijét, mielőtt a vidámpark totális katasztrófába fulladt volna!'::text),
(351282,39032,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, sie ... schon so zwei Stunden durch diese Gehirn-Ausstellung, echt jetzt.'::text,'läuft'::text,'läuft'::text,'läuft'::text,'Bro, sie läuft schon so zwei Stunden durch diese Gehirn-Ausstellung, echt jetzt.'::text),
(351286,39032,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона вже десь дві години ... по цій виставці мозку, чесно.'::text,'ходить'::text,'ходить'::text,'ходить'::text,'Бро, вона вже десь дві години ходить по цій виставці мозку, чесно.'::text),
(351285,39032,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ella ... como dos horas por esta exposición de cerebros, en serio.'::text,'lleva paseando'::text,'está paseando'::text,'pasea'::text,'Bro, ella lleva paseando como dos horas por esta exposición de cerebros, en serio.'::text),
(351284,39032,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, elle ... dans cette expo sur le cerveau depuis genre deux heures, sérieux.'::text,'se balade'::text,'se balade'::text,'se balade'::text,'Frère, elle se balade dans cette expo sur le cerveau depuis genre deux heures, sérieux.'::text),
(351287,39032,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o yaklaşık iki saattir bu beyin sergisinde ..., cidden.'::text,'dolaşıyor'::text,'dolaşıyor'::text,'dolaşır'::text,'Kanka, o yaklaşık iki saattir bu beyin sergisinde dolaşıyor, cidden.'::text),
(351288,39032,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ő már vagy két órája ... ezen az agykiállításon, komolyan.'::text,'mászkál'::text,'mászkál'::text,'mászkál'::text,'Tesó, ő már vagy két órája mászkál ezen az agykiállításon, komolyan.'::text),
(351354,39040,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade ... sie auf der Ausstellung zu dem riesigen Gehirn hoch.'::text,'schaut'::text,'schaut'::text,'schaute'::text,'Gerade schaut sie auf der Ausstellung zu dem riesigen Gehirn hoch.'::text),
(351358,39040,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зараз вона ... вгору на велетенський мозок на виставці.'::text,'дивиться'::text,'дивиться'::text,'подивилася'::text,'Зараз вона дивиться вгору на велетенський мозок на виставці.'::text),
(351357,39040,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En este momento, ella ... hacia arriba al cerebro gigante de la exposición.'::text,'está mirando'::text,'mira'::text,'ha mirado'::text,'En este momento, ella está mirando hacia arriba al cerebro gigante de la exposición.'::text),
(351356,39040,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, elle ... le cerveau géant de l''exposition.'::text,'est en train de lever les yeux vers'::text,'lève les yeux vers'::text,'a levé les yeux vers'::text,'En ce moment, elle est en train de lever les yeux vers le cerveau géant de l''exposition.'::text),
(351359,39040,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda o, sergideki dev beyne yukarı doğru ...'::text,'bakıyor'::text,'bakar'::text,'baktı'::text,'Şu anda o, sergideki dev beyne yukarı doğru bakıyor.'::text),
(351360,39040,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő éppen ... a kiállításon az óriási agyra.'::text,'felnéz'::text,'felnéz'::text,'felnézett'::text,'Ő éppen felnéz a kiállításon az óriási agyra.'::text),
(339789,37755,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Junge sagte, er ... noch nie so einen lauten Jubel gehört wie diesen.'::text,'habe'::text,'hat'::text,'haben'::text,'Der Junge sagte, er habe noch nie so einen lauten Jubel gehört wie diesen.'::text),
(339793,37755,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хлопець сказав, що він ще ніколи не ... такого гучного вигуку, як цей.'::text,'чув'::text,'чув'::text,'чув'::text,'Хлопець сказав, що він ще ніколи не чув такого гучного вигуку, як цей.'::text),
(339792,37755,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El chico dijo que él nunca ... oído una ovación tan fuerte como esa.'::text,'había'::text,'ha'::text,'han'::text,'El chico dijo que él nunca había oído una ovación tan fuerte como esa.'::text),
(339791,37755,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le garçon a dit qu''il ... jamais entendu d''acclamation aussi forte que celle-là.'::text,'n''avait'::text,'n''a'::text,'n''ont'::text,'Le garçon a dit qu''il n''avait jamais entendu d''acclamation aussi forte que celle-là.'::text),
(339794,37755,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çocuk, o kadar yüksek bir tezahüratı daha önce hiç ... söyledi.'::text,'duymadığını'::text,'duymadığını'::text,'duymadıklarını'::text,'Çocuk, o kadar yüksek bir tezahüratı daha önce hiç duymadığını söyledi.'::text),
(339795,37755,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fiú azt mondta, hogy ő még soha ... ilyen hangos ujjongást, mint az.'::text,'nem hallott'::text,'nem hallott'::text,'nem hallottak'::text,'A fiú azt mondta, hogy ő még soha nem hallott ilyen hangos ujjongást, mint az.'::text),
(372774,41420,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sich die Parade noch schneller bewegen würde, ... die Tänzer die Frau in Grün.'::text,'überholten'::text,'überholen'::text,'überholten'::text,'Wenn sich die Parade noch schneller bewegen würde, überholten die Tänzer die Frau in Grün.'::text),
(372778,41420,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби парад рухався ще швидше, танцюристи ... жінку в зеленому.'::text,'обігнали б'::text,'обженуть'::text,'обігнали'::text,'Якби парад рухався ще швидше, танцюристи обігнали б жінку в зеленому.'::text),
(372777,41420,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el desfile fuera más rápido, los bailarines ... a la mujer de verde.'::text,'adelantarían'::text,'adelantarán'::text,'adelantaron'::text,'Si el desfile fuera más rápido, los bailarines adelantarían a la mujer de verde.'::text),
(372776,41420,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le défilé allait encore plus vite, les danseurs ... la femme en vert.'::text,'dépasseraient'::text,'dépasseront'::text,'ont dépassé'::text,'Si le défilé allait encore plus vite, les danseurs dépasseraient la femme en vert.'::text),
(372779,41420,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Geçit töreni biraz daha hızlı ilerlese, dansçılar yeşilli kadını ...'::text,'geçerdi'::text,'geçecek'::text,'geçti'::text,'Geçit töreni biraz daha hızlı ilerlese, dansçılar yeşilli kadını geçerdi.'::text),
(372780,41420,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a felvonulás még gyorsabban haladna, a táncosok ... a zöld ruhás nőt.'::text,'megelőznék'::text,'megelőzik'::text,'megelőzték'::text,'Ha a felvonulás még gyorsabban haladna, a táncosok megelőznék a zöld ruhás nőt.'::text),
(372810,41424,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Ende des Tages ... die Parade ihre gesamte Route geschafft haben, wie üblich.'::text,'wird'::text,'schafft'::text,'wird gerade'::text,'Bis zum Ende des Tages wird die Parade ihre gesamte Route geschafft haben, wie üblich.'::text),
(372814,41424,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До кінця дня парад ... весь свій маршрут, як це зазвичай буває.'::text,'пройде'::text,'проходить'::text,'проходитиме'::text,'До кінця дня парад пройде весь свій маршрут, як це зазвичай буває.'::text),
(372813,41424,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el final del día, el desfile ... todo su recorrido, como suele hacer.'::text,'habrá completado'::text,'completa'::text,'estará completando'::text,'Para el final del día, el desfile habrá completado todo su recorrido, como suele hacer.'::text),
(372812,41424,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici la fin de la journée, le défilé ... tout son parcours, comme il le fait habituellement.'::text,'aura terminé'::text,'termine'::text,'sera en train de terminer'::text,'D''ici la fin de la journée, le défilé aura terminé tout son parcours, comme il le fait habituellement.'::text),
(372815,41424,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gün sonuna kadar geçit töreni, genelde olduğu gibi, tüm güzergâhını ...'::text,'tamamlamış olacak'::text,'tamamlıyor'::text,'tamamlıyor olacak'::text,'Gün sonuna kadar geçit töreni, genelde olduğu gibi, tüm güzergâhını tamamlamış olacak.'::text),
(372816,41424,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nap végére a felvonulás ... a teljes útvonalát, ahogy általában szokta.'::text,'teljesíteni fogja'::text,'teljesíti'::text,'éppen teljesíteni fogja'::text,'A nap végére a felvonulás teljesíteni fogja a teljes útvonalát, ahogy általában szokta.'::text),
(392916,43658,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt: Wenn du so auf ein Brett ..., bricht es jedes Mal.'::text,'schlägst'::text,'schlugst'::text,'schlagen wirst'::text,'Respekt: Wenn du so auf ein Brett schlägst, bricht es jedes Mal.'::text),
(392920,43658,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Респект: якщо ти ... так по дошці, вона щоразу ламається.'::text,'б''єш'::text,'вдарила'::text,'вдариш'::text,'Респект: якщо ти б''єш так по дошці, вона щоразу ламається.'::text),
(392919,43658,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respeto: si tú ... una tabla así, se parte cada vez.'::text,'golpeas'::text,'golpeaste'::text,'golpearás'::text,'Respeto: si tú golpeas una tabla así, se parte cada vez.'::text),
(392918,43658,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respect : si tu ... une planche comme ça, elle se casse à chaque fois.'::text,'frappes'::text,'frappais'::text,'frapperas'::text,'Respect : si tu frappes une planche comme ça, elle se casse à chaque fois.'::text),
(392921,43658,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saygılar: sen bir tahtaya öyle ..., her seferinde kırılıyor.'::text,'vurursan'::text,'vurduysan'::text,'vuracaksan'::text,'Saygılar: sen bir tahtaya öyle vurursan, her seferinde kırılıyor.'::text),
(392922,43658,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt: ha te így ... egy deszkára, az minden alkalommal kettétörik.'::text,'ütsz'::text,'ütöttél'::text,'ütni fogsz'::text,'Respekt: ha te így ütsz egy deszkára, az minden alkalommal kettétörik.'::text),
(392988,43666,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, angeblich ... sie jahrelang trainiert, bevor sie durch Beton geschlagen hat.'::text,'hatte'::text,'hat'::text,'trainiert'::text,'Bestie, angeblich hatte sie jahrelang trainiert, bevor sie durch Beton geschlagen hat.'::text),
(392992,43666,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, вона ... роками, перш ніж пробила бетон.'::text,'тренувалася'::text,'тренується'::text,'тренується'::text,'Подруго, кажуть, вона тренувалася роками, перш ніж пробила бетон.'::text),
(392991,43666,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, dicen que ella ... durante años antes de atravesar el hormigón de un golpe.'::text,'había estado entrenando'::text,'ha estado entrenando'::text,'está entrenando'::text,'Amiga, dicen que ella había estado entrenando durante años antes de atravesar el hormigón de un golpe.'::text),
(392990,43666,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, il paraît qu''elle ... pendant des années avant de traverser le béton d''un coup.'::text,'s''entraînait'::text,'s''entraîne'::text,'s''entraîne'::text,'Ma belle, il paraît qu''elle s''entraînait pendant des années avant de traverser le béton d''un coup.'::text),
(392993,43666,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, dediklerine göre o betonu kırmadan önce yıllarca ...'::text,'antrenman yapmış'::text,'antrenman yapıyor'::text,'antrenman yapıyor'::text,'Kanka, dediklerine göre o betonu kırmadan önce yıllarca antrenman yapmış.'::text),
(392994,43666,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, a pletyka szerint ő évekig ..., mielőtt átütötte a betont.'::text,'edzett'::text,'edz'::text,'edz'::text,'Csajszi, a pletyka szerint ő évekig edzett, mielőtt átütötte a betont.'::text),
(336378,37376,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, wenn du noch so eine Atemwolke ..., machen es dir die Wanderer wieder nach.'::text,'pustest'::text,'pusten wirst'::text,'pustetest'::text,'Ehrlich, wenn du noch so eine Atemwolke pustest, machen es dir die Wanderer wieder nach.'::text),
(336382,37376,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, якщо ти ... ще одну таку хмарку дихання, туристи знову тебе скопіюють.'::text,'видихнеш'::text,'видихнеш'::text,'видихнула'::text,'Чесно, якщо ти видихнеш ще одну таку хмарку дихання, туристи знову тебе скопіюють.'::text),
(336381,37376,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, si tú ... otra nube de aliento así, los excursionistas te volverán a copiar.'::text,'sueltas'::text,'soltarás'::text,'soltaste'::text,'Sinceramente, si tú sueltas otra nube de aliento así, los excursionistas te volverán a copiar.'::text),
(336380,37376,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Honnêtement, si tu ... encore un nuage de souffle comme ça, les randonneurs vont encore te copier.'::text,'souffles'::text,'souffleras'::text,'soufflais'::text,'Honnêtement, si tu souffles encore un nuage de souffle comme ça, les randonneurs vont encore te copier.'::text),
(336383,37376,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, sen böyle bir nefes bulutu daha ..., yürüyüşçüler seni yine taklit edecek.'::text,'üflersen'::text,'üfleyeceksen'::text,'üflediysen'::text,'Açıkçası, sen böyle bir nefes bulutu daha üflersen, yürüyüşçüler seni yine taklit edecek.'::text),
(336384,37376,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ha te még egy ilyen leheletfelhőt ..., a túrázók megint utánoznak.'::text,'fújsz'::text,'fújni fogsz'::text,'fújtál'::text,'Őszintén, ha te még egy ilyen leheletfelhőt fújsz, a túrázók megint utánoznak.'::text),
(397047,44117,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... gerade den Eimer über dem Tisch, als die Äpfel überall hinrollten, ehrlich ikonisch.'::text,'kipptest'::text,'kipptest'::text,'hast gekippt'::text,'Du kipptest gerade den Eimer über dem Tisch, als die Äpfel überall hinrollten, ehrlich ikonisch.'::text),
(397051,44117,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... відро над столом, коли яблука розкотилися всюди, чесно, культово.'::text,'нахиляла'::text,'нахилила'::text,'нахилила'::text,'Ти нахиляла відро над столом, коли яблука розкотилися всюди, чесно, культово.'::text),
(397050,44117,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tú ... el cubo sobre la mesa cuando las manzanas rodaron por todas partes, sinceramente icónico.'::text,'estabas volcando'::text,'volcaste'::text,'has volcado'::text,'Tú estabas volcando el cubo sobre la mesa cuando las manzanas rodaron por todas partes, sinceramente icónico.'::text),
(397049,44117,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... le seau au-dessus de la table quand les pommes ont roulé partout, franchement iconique.'::text,'renversais'::text,'as renversé'::text,'as renversé'::text,'Tu renversais le seau au-dessus de la table quand les pommes ont roulé partout, franchement iconique.'::text),
(397052,44117,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elmalar her yere yuvarlandığında sen kovayı masanın üstüne ..., açıkçası ikonik.'::text,'devriyordun'::text,'devirdin'::text,'devirdin'::text,'Elmalar her yere yuvarlandığında sen kovayı masanın üstüne devriyordun, açıkçası ikonik.'::text),
(397053,44117,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te éppen ... a vödröt az asztal fölött, amikor az almák mindenfelé gurultak, őszintén ikonikus.'::text,'döntötted'::text,'döntötted'::text,'döntötted'::text,'Te éppen döntötted a vödröt az asztal fölött, amikor az almák mindenfelé gurultak, őszintén ikonikus.'::text),
(397065,44119,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Mittagessen ... sie jeden Eimer Äpfel auf den Tisch gekippt haben.'::text,'wird'::text,'kippt'::text,'wird gerade'::text,'Bis zum Mittagessen wird sie jeden Eimer Äpfel auf den Tisch gekippt haben.'::text),
(397069,44119,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До обіду вона ... кожне відро яблук на стіл.'::text,'висипле'::text,'висипле'::text,'висипає'::text,'До обіду вона висипле кожне відро яблук на стіл.'::text),
(397068,44119,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para la hora de comer, ella ... cada cubo de manzanas sobre la mesa.'::text,'habrá volcado'::text,'volcará'::text,'vuelca'::text,'Para la hora de comer, ella habrá volcado cada cubo de manzanas sobre la mesa.'::text),
(397067,44119,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici le déjeuner, elle ... chaque seau de pommes sur la table.'::text,'aura renversé'::text,'renversera'::text,'renverse'::text,'D''ici le déjeuner, elle aura renversé chaque seau de pommes sur la table.'::text),
(397070,44119,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğle yemeğine kadar o her kova elmayı masaya ...'::text,'boşaltmış olacak'::text,'boşaltacak'::text,'boşaltıyor'::text,'Öğle yemeğine kadar o her kova elmayı masaya boşaltmış olacak.'::text),
(397071,44119,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ebédre ő ... minden vödör almát az asztalra.'::text,'ki fog borítani'::text,'ki fog borítani'::text,'kiborít'::text,'Ebédre ő ki fog borítani minden vödör almát az asztalra.'::text),
(344757,38307,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hockt ein bisschen nah an den Flammen, ...? Könnte schlimmer sein.'::text,'oder'::text,'oder'::text,'oder'::text,'Sie hockt ein bisschen nah an den Flammen, oder? Könnte schlimmer sein.'::text),
(344761,38307,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона присіла трохи близько до вогню, ...? Могло бути й гірше.'::text,'правда'::text,'правда'::text,'правда'::text,'Вона присіла трохи близько до вогню, правда? Могло бути й гірше.'::text),
(344760,38307,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella está agachada un poco cerca de las llamas, ¿...? Podría ser peor.'::text,'verdad'::text,'verdad'::text,'verdad'::text,'Ella está agachada un poco cerca de las llamas, ¿verdad? Podría ser peor.'::text),
(344759,38307,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle est accroupie un peu près des flammes, ... ? Ça pourrait être pire.'::text,'n''est-ce pas'::text,'n''est-ce pas'::text,'n''est-ce pas'::text,'Elle est accroupie un peu près des flammes, n''est-ce pas ? Ça pourrait être pire.'::text),
(344762,38307,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O alevlere biraz yakın çömelmiş, ...? Daha kötüsü de olabilirdi.'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'O alevlere biraz yakın çömelmiş, değil mi? Daha kötüsü de olabilirdi.'::text),
(344763,38307,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő kicsit közel guggol a lángokhoz, ...? Lehetne rosszabb is.'::text,'ugye'::text,'ugye'::text,'ugye'::text,'Ő kicsit közel guggol a lángokhoz, ugye? Lehetne rosszabb is.'::text),
(344775,38309,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... stundenlang über diesem Feuer gehockt, bevor die Flammen endlich den letzten Stock zerstörten!'::text,'hatte'::text,'hat'::text,'war'::text,'Sie hatte stundenlang über diesem Feuer gehockt, bevor die Flammen endlich den letzten Stock zerstörten!'::text),
(344779,38309,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... над тим вогнем годинами, поки полум''я нарешті не знищило останню палицю!'::text,'сиділа навпочіпки'::text,'сидить навпочіпки'::text,'сиділа навпочіпки'::text,'Вона сиділа навпочіпки над тим вогнем годинами, поки полум''я нарешті не знищило останню палицю!'::text),
(344778,38309,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ella ... agachada junto a ese fuego durante horas antes de que las llamas por fin destruyeran el último palo!'::text,'había estado'::text,'ha estado'::text,'estaba'::text,'¡Ella había estado agachada junto a ese fuego durante horas antes de que las llamas por fin destruyeran el último palo!'::text),
(344777,38309,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... accroupie au-dessus de ce feu pendant des heures avant que les flammes détruisent enfin le dernier bâton !'::text,'était restée'::text,'est restée'::text,'était'::text,'Elle était restée accroupie au-dessus de ce feu pendant des heures avant que les flammes détruisent enfin le dernier bâton !'::text),
(344780,38309,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alevler sonunda son çubuğu da yok edene kadar o saatlerce o ateşin başında ...!'::text,'çömelmişti'::text,'çömeliyor'::text,'çömeliyordu'::text,'Alevler sonunda son çubuğu da yok edene kadar o saatlerce o ateşin başında çömelmişti!'::text),
(344781,38309,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő órák óta ... a tűz fölött, mielőtt a lángok végre elpusztították az utolsó botot!'::text,'guggolt'::text,'guggol'::text,'guggolt'::text,'Ő órák óta guggolt a tűz fölött, mielőtt a lángok végre elpusztították az utolsó botot!'::text),
(347961,38663,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Toast ... schon schwarz geworden, bevor er das Desaster im Ofen überhaupt bemerkte.'::text,'war'::text,'ist'::text,'wurde gerade'::text,'Der Toast war schon schwarz geworden, bevor er das Desaster im Ofen überhaupt bemerkte.'::text),
(347965,38663,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Тост ... ще до того, як він узагалі помітив катастрофу в духовці.'::text,'почорнів'::text,'почорнів'::text,'чорнів'::text,'Тост почорнів ще до того, як він узагалі помітив катастрофу в духовці.'::text),
(347964,38663,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La tostada ... negra antes de que él siquiera notara el desastre del horno.'::text,'se había puesto'::text,'se ha puesto'::text,'se estaba poniendo'::text,'La tostada se había puesto negra antes de que él siquiera notara el desastre del horno.'::text),
(347963,38663,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le toast ... noir avant même qu''il remarque le désastre dans le four.'::text,'était devenu'::text,'est devenu'::text,'devenait'::text,'Le toast était devenu noir avant même qu''il remarque le désastre dans le four.'::text),
(347966,38663,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O fırındaki felaketi fark etmeden önce bile tost ...'::text,'kararmıştı'::text,'karardı'::text,'kararıyordu'::text,'O fırındaki felaketi fark etmeden önce bile tost kararmıştı.'::text),
(347967,38663,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A pirítós már ..., mielőtt ő egyáltalán észrevette a katasztrófát a sütőben.'::text,'megfeketedett'::text,'megfeketedett'::text,'feketedett'::text,'A pirítós már megfeketedett, mielőtt ő egyáltalán észrevette a katasztrófát a sütőben.'::text),
(336846,37428,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, angeblich hat sie schon vier Marshmallows ..., und sie liebt das Verbrennen.'::text,'verbrannt'::text,'verbrannt'::text,'verbrennt'::text,'Hör mal, angeblich hat sie schon vier Marshmallows verbrannt, und sie liebt das Verbrennen.'::text),
(336850,37428,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, вона вже ... чотири маршмелоу, і їй подобається палити.'::text,'спалила'::text,'палила'::text,'палить'::text,'Слухай, кажуть, вона вже спалила чотири маршмелоу, і їй подобається палити.'::text),
(336849,37428,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, al parecer ella ya ... cuatro malvaviscos, y le encanta quemarlos.'::text,'ha quemado'::text,'ha estado quemando'::text,'está quemando'::text,'Oye, al parecer ella ya ha quemado cuatro malvaviscos, y le encanta quemarlos.'::text),
(336848,37428,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment elle ... déjà quatre marshmallows, et elle adore les faire brûler.'::text,'a brûlé'::text,'a brûlé'::text,'est en train de brûler'::text,'Écoute, apparemment elle a brûlé déjà quatre marshmallows, et elle adore les faire brûler.'::text),
(336851,37428,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duyduğuma göre o şimdiden dört marshmallow ... ve yakmaya bayılıyor.'::text,'yakmış'::text,'yakıp durmuş'::text,'yakıyor'::text,'Dinle, duyduğuma göre o şimdiden dört marshmallow yakmış ve yakmaya bayılıyor.'::text),
(336852,37428,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag ő már négy mályvacukrot ..., és imádja az égetést.'::text,'elégetett'::text,'égetett'::text,'éget'::text,'Figyelj, állítólag ő már négy mályvacukrot elégetett, és imádja az égetést.'::text),
(336909,37435,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis sie fertig ist, ... das Verbrennen jeden Marshmallow in der Tüte. Toller Snack-Plan.'::text,'ruiniert'::text,'ruiniert'::text,'ruiniert'::text,'Bis sie fertig ist, ruiniert das Verbrennen jeden Marshmallow in der Tüte. Toller Snack-Plan.'::text),
(336913,37435,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки вона закінчить, палання ... кожен маршмелоу в пакеті. Чудовий план перекусу.'::text,'зіпсує'::text,'зіпсує'::text,'псує'::text,'Поки вона закінчить, палання зіпсує кожен маршмелоу в пакеті. Чудовий план перекусу.'::text),
(336912,37435,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando ella termine, la quema ... todos los malvaviscos de la bolsa. Gran plan de merienda.'::text,'habrá arruinado'::text,'arruinará'::text,'arruina'::text,'Para cuando ella termine, la quema habrá arruinado todos los malvaviscos de la bolsa. Gran plan de merienda.'::text),
(336911,37435,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici à ce qu''elle finisse, la cuisson ... tous les marshmallows du sachet. Super plan goûter.'::text,'aura ruiné'::text,'ruinera'::text,'ruine'::text,'D''ici à ce qu''elle finisse, la cuisson aura ruiné tous les marshmallows du sachet. Super plan goûter.'::text),
(336914,37435,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O bitirene kadar yakma işi paketteki her marshmallow''u ...! Harika atıştırmalık planı.'::text,'mahvetmiş olacak'::text,'mahvedecek'::text,'mahvediyor'::text,'O bitirene kadar yakma işi paketteki her marshmallow''u mahvetmiş olacak! Harika atıştırmalık planı.'::text),
(336915,37435,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire ő végez, az égetés ... a zacskóban lévő összes mályvacukrot. Remek nasiterv.'::text,'tönkre fogja tenni'::text,'tönkre fogja tenni'::text,'tönkreteszi'::text,'Mire ő végez, az égetés tönkre fogja tenni a zacskóban lévő összes mályvacukrot. Remek nasiterv.'::text),
(372405,41379,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als Kind ... sie jeden Sommer ihre Handflächen über Strandfeuer zu halten.'::text,'pflegte'::text,'pflegte'::text,'war gewohnt,'::text,'Als Kind pflegte sie jeden Sommer ihre Handflächen über Strandfeuer zu halten.'::text),
(372409,41379,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У дитинстві вона ... тримати долоні над вогнищами на пляжі щоліта.'::text,'мала звичку'::text,'мала звичку'::text,'звикла'::text,'У дитинстві вона мала звичку тримати долоні над вогнищами на пляжі щоліта.'::text),
(372408,41379,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'De niña, ella ... poner las palmas sobre las hogueras de la playa cada verano.'::text,'solía'::text,'solía'::text,'estaba acostumbrada a'::text,'De niña, ella solía poner las palmas sobre las hogueras de la playa cada verano.'::text),
(372407,41379,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Enfant, elle ... tenir ses paumes au-dessus des feux de plage chaque été.'::text,'avait l''habitude de'::text,'avait l''habitude de'::text,'était habituée à'::text,'Enfant, elle avait l''habitude de tenir ses paumes au-dessus des feux de plage chaque été.'::text),
(372410,41379,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çocukken o her yaz avuçlarını plaj ateşlerinin üzerinde ...'::text,'tutardı'::text,'tutardı'::text,'tutmaya alışkındı'::text,'Çocukken o her yaz avuçlarını plaj ateşlerinin üzerinde tutardı.'::text),
(372411,41379,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gyerekként ő minden nyáron a tengerparti tüzek fölé ... a tenyerét.'::text,'tartotta'::text,'tartotta'::text,'szokott volt tartani'::text,'Gyerekként ő minden nyáron a tengerparti tüzek fölé tartotta a tenyerét.'::text),
(372423,41381,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade ... ihre Handflächen über dem einzigen Licht an diesem komplett dunklen Strand!'::text,'schweben'::text,'schweben'::text,'schwebten'::text,'Gerade schweben ihre Handflächen über dem einzigen Licht an diesem komplett dunklen Strand!'::text),
(372427,41381,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Саме зараз її долоні ... над єдиним світлом на цьому зовсім темному пляжі!'::text,'ширяють'::text,'ширяють'::text,'ширяли'::text,'Саме зараз її долоні ширяють над єдиним світлом на цьому зовсім темному пляжі!'::text),
(372426,41381,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ahora mismo sus palmas ... sobre la única luz de esta playa completamente oscura!'::text,'están suspendidas'::text,'se suspenden'::text,'han estado suspendidas'::text,'¡Ahora mismo sus palmas están suspendidas sobre la única luz de esta playa completamente oscura!'::text),
(372425,41381,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment même, ses paumes ... au-dessus de la seule lumière de cette plage complètement noire !'::text,'planent'::text,'planent'::text,'ont plané'::text,'En ce moment même, ses paumes planent au-dessus de la seule lumière de cette plage complètement noire !'::text),
(372428,41381,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda avuçları bu tamamen karanlık plajdaki tek ışığın üzerinde ...!'::text,'süzülüyor'::text,'süzülür'::text,'süzüldü'::text,'Şu anda avuçları bu tamamen karanlık plajdaki tek ışığın üzerinde süzülüyor!'::text),
(372429,41381,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp most a tenyere ... az egyetlen fény fölött ezen a teljesen sötét parton!'::text,'lebeg'::text,'lebeg'::text,'lebegett'::text,'Épp most a tenyere lebeg az egyetlen fény fölött ezen a teljesen sötét parton!'::text),
(347565,38619,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Schlimmster Strandtag ever! Er schwört, dass er nie wieder ein Loch gräbt, und ...'::text,'seine Freunde auch nicht!'::text,'seine Freunde auch!'::text,'seine Freunde tun es auch nicht!'::text,'Schlimmster Strandtag ever! Er schwört, dass er nie wieder ein Loch gräbt, und seine Freunde auch nicht!'::text),
(347569,38619,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Найгірший день на пляжі! Він клянеться, що більше ніколи не копатиме яму, і ...'::text,'його друзі теж ні!'::text,'його друзі теж!'::text,'його друзі теж ні!'::text,'Найгірший день на пляжі! Він клянеться, що більше ніколи не копатиме яму, і його друзі теж ні!'::text),
(347568,38619,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El peor día de playa de la historia! Él jura que nunca volverá a cavar un hoyo, y ...'::text,'¡sus amigos tampoco!'::text,'¡sus amigos también!'::text,'¡sus amigos tampoco!'::text,'¡El peor día de playa de la historia! Él jura que nunca volverá a cavar un hoyo, y ¡sus amigos tampoco!'::text),
(347567,38619,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pire journée de plage de tous les temps ! Il jure qu''il ne creusera plus jamais de trou, et ...'::text,'ses potes non plus !'::text,'ses potes aussi !'::text,'ses potes non plus !'::text,'Pire journée de plage de tous les temps ! Il jure qu''il ne creusera plus jamais de trou, et ses potes non plus !'::text),
(347570,38619,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gelmiş geçmiş en kötü plaj günü! O bir daha asla çukur kazmayacağına yemin ediyor ve ...'::text,'arkadaşları da kazmayacak!'::text,'arkadaşları da kazacak!'::text,'arkadaşları da kazmıyor!'::text,'Gelmiş geçmiş en kötü plaj günü! O bir daha asla çukur kazmayacağına yemin ediyor ve arkadaşları da kazmayacak!'::text),
(347571,38619,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden idők legrosszabb strandnapja! Ő esküszik, hogy soha többé nem ás gödröt, és ...'::text,'a barátai sem!'::text,'a barátai is!'::text,'a barátai sem!'::text,'Minden idők legrosszabb strandnapja! Ő esküszik, hogy soha többé nem ás gödröt, és a barátai sem!'::text),
(347574,38620,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katastrophe! Meine Freunde ... ein riesiges Loch gegraben, und jetzt stecke ich total fest!'::text,'haben'::text,'graben'::text,'graben'::text,'Katastrophe! Meine Freunde haben ein riesiges Loch gegraben, und jetzt stecke ich total fest!'::text),
(347578,38620,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Катастрофа! Мої друзі ... величезну яму, і тепер я зовсім застряг!'::text,'викопали'::text,'копають'::text,'копають'::text,'Катастрофа! Мої друзі викопали величезну яму, і тепер я зовсім застряг!'::text),
(347577,38620,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Desastre! Mis amigos ... un hoyo enorme, ¡y ahora yo estoy completamente atascado!'::text,'han cavado'::text,'están cavando'::text,'cavan'::text,'¡Desastre! Mis amigos han cavado un hoyo enorme, ¡y ahora yo estoy completamente atascado!'::text),
(347576,38620,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Catastrophe ! Mes potes ... un énorme trou, et maintenant je suis complètement coincé !'::text,'ont creusé'::text,'sont en train de creuser'::text,'creusent'::text,'Catastrophe ! Mes potes ont creusé un énorme trou, et maintenant je suis complètement coincé !'::text),
(347579,38620,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felaket! Arkadaşlarım kocaman bir çukur ... ve şimdi ben tamamen sıkıştım!'::text,'kazdı'::text,'kazıyor'::text,'kazar'::text,'Felaket! Arkadaşlarım kocaman bir çukur kazdı ve şimdi ben tamamen sıkıştım!'::text),
(347580,38620,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katasztrófa! A barátaim ... egy hatalmas gödröt, és most én teljesen beszorultam!'::text,'ástak'::text,'ásnak'::text,'ásnak'::text,'Katasztrófa! A barátaim ástak egy hatalmas gödröt, és most én teljesen beszorultam!'::text),
(356889,39655,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Beerdigung endet, ... sie vorbei, denn genau das bedeutet enden.'::text,'ist'::text,'wäre'::text,'war'::text,'Wenn die Beerdigung endet, ist sie vorbei, denn genau das bedeutet enden.'::text),
(356893,39655,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо похорон закінчиться, він ... позаду, бо саме це й означає закінчитися.'::text,'буде'::text,'був би'::text,'був'::text,'Якщо похорон закінчиться, він буде позаду, бо саме це й означає закінчитися.'::text),
(356892,39655,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el funeral termina, ... terminado, porque eso es lo que significa terminar.'::text,'estará'::text,'estaría'::text,'estaba'::text,'Si el funeral termina, estará terminado, porque eso es lo que significa terminar.'::text),
(356891,39655,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si l''enterrement se termine, il ... fini, parce que c''est ça que veut dire se terminer.'::text,'sera'::text,'serait'::text,'était'::text,'Si l''enterrement se termine, il sera fini, parce que c''est ça que veut dire se terminer.'::text),
(356894,39655,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cenaze biterse o ..., çünkü bitmek tam olarak bu demek.'::text,'bitmiş olur'::text,'bitmiş olurdu'::text,'bitmişti'::text,'Cenaze biterse o bitmiş olur, çünkü bitmek tam olarak bu demek.'::text),
(356895,39655,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a temetés véget ér, akkor vége ..., mert pont ezt jelenti véget érni.'::text,'lesz'::text,'lenne'::text,'volt'::text,'Ha a temetés véget ér, akkor vége lesz, mert pont ezt jelenti véget érni.'::text),
(328836,36538,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seit heute Morgen ... er in einen Bus nach dem anderen ein.'::text,'steigt'::text,'steigt gerade'::text,'steigt'::text,'Seit heute Morgen steigt er in einen Bus nach dem anderen ein.'::text),
(328840,36538,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Від ранку він ... в один автобус за іншим.'::text,'сідає'::text,'сідає'::text,'сідає'::text,'Від ранку він сідає в один автобус за іншим.'::text),
(328839,36538,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Desde esta mañana, él ... a un autobús tras otro.'::text,'ha estado subiendo'::text,'está subiendo'::text,'sube'::text,'Desde esta mañana, él ha estado subiendo a un autobús tras otro.'::text),
(328838,36538,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Depuis ce matin, il ... dans un bus après l''autre.'::text,'monte'::text,'est en train de monter'::text,'monte'::text,'Depuis ce matin, il monte dans un bus après l''autre.'::text),
(328841,36538,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu sabahtan beri o bir otobüsten ötekine ...'::text,'biniyor'::text,'biniyor'::text,'biner'::text,'Bu sabahtan beri o bir otobüsten ötekine biniyor.'::text),
(328842,36538,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő reggel óta ... egyik buszra a másik után.'::text,'száll fel'::text,'éppen felszáll'::text,'felszáll'::text,'Ő reggel óta száll fel egyik buszra a másik után.'::text),
(328872,36542,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er stieg mit seiner Tasche ein, also ... er im vollen Minibus etwas Platz gefunden haben.'::text,'muss'::text,'sollte'::text,'kann nicht'::text,'Er stieg mit seiner Tasche ein, also muss er im vollen Minibus etwas Platz gefunden haben.'::text),
(328876,36542,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він сів із сумкою, тож у переповненому мікроавтобусі він ... знайти трохи місця.'::text,'мабуть, зумів'::text,'мав'::text,'не міг'::text,'Він сів із сумкою, тож у переповненому мікроавтобусі він мабуть, зумів знайти трохи місця.'::text),
(328875,36542,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él subió con su bolsa, así que ... encontrado algo de sitio en el minibús abarrotado.'::text,'debió de haber'::text,'debería haber'::text,'no puede haber'::text,'Él subió con su bolsa, así que debió de haber encontrado algo de sitio en el minibús abarrotado.'::text),
(328874,36542,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il est monté avec son sac, donc il ... trouver un peu de place dans le minibus bondé.'::text,'a dû'::text,'aurait dû'::text,'n''a pas pu'::text,'Il est monté avec son sac, donc il a dû trouver un peu de place dans le minibus bondé.'::text),
(328877,36542,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O çantasıyla bindi, yani kalabalık minibüste biraz yer ...'::text,'bulmuş olmalı'::text,'bulmalıydı'::text,'bulmuş olamaz'::text,'O çantasıyla bindi, yani kalabalık minibüste biraz yer bulmuş olmalı.'::text),
(328878,36542,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő a táskájával szállt fel, szóval a zsúfolt kisbuszban ... egy kis helyet.'::text,'biztosan talált'::text,'kellett volna találnia'::text,'nem találhatott'::text,'Ő a táskájával szállt fel, szóval a zsúfolt kisbuszban biztosan talált egy kis helyet.'::text),
(375636,41738,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Träger trägt all diese Teppiche ganz allein, ...?'::text,'oder'::text,'oder'::text,'oder'::text,'Der Träger trägt all diese Teppiche ganz allein, oder?'::text),
(375640,41738,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Носій несе всі ці килими сам, ...?'::text,'правда'::text,'правда'::text,'правда'::text,'Носій несе всі ці килими сам, правда?'::text),
(375639,41738,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El mozo está cargando todas esas alfombras él solo, ¿...?'::text,'verdad'::text,'verdad'::text,'verdad'::text,'El mozo está cargando todas esas alfombras él solo, ¿verdad?'::text),
(375638,41738,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le porteur transporte tous ces tapis tout seul, ... ?'::text,'n''est-ce pas'::text,'n''est-ce pas'::text,'n''est-ce pas'::text,'Le porteur transporte tous ces tapis tout seul, n''est-ce pas ?'::text),
(375641,41738,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hamal bütün o halıları tek başına taşıyor, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Hamal bütün o halıları tek başına taşıyor, değil mi?'::text),
(375642,41738,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hordár egyedül viszi azt a sok szőnyeget, ...?'::text,'ugye'::text,'ugye'::text,'ugye'::text,'A hordár egyedül viszi azt a sok szőnyeget, ugye?'::text),
(375654,41740,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bevor die Kamera ihn beobachtete, ... der Träger den ganzen Vormittag Waren über den Markt getragen.'::text,'hatte'::text,'hat'::text,'trägt'::text,'Bevor die Kamera ihn beobachtete, hatte der Träger den ganzen Vormittag Waren über den Markt getragen.'::text),
(375658,41740,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Перш ніж камера його зафіксувала, носій увесь ранок ... товари через ринок.'::text,'носив'::text,'носить'::text,'несе'::text,'Перш ніж камера його зафіксувала, носій увесь ранок носив товари через ринок.'::text),
(375657,41740,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes de que la cámara lo observara, el mozo ... mercancías por el mercado toda la mañana.'::text,'había estado llevando'::text,'ha estado llevando'::text,'está llevando'::text,'Antes de que la cámara lo observara, el mozo había estado llevando mercancías por el mercado toda la mañana.'::text),
(375656,41740,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant que la caméra ne l''observe, le porteur ... des marchandises à travers le marché toute la matinée.'::text,'transportait'::text,'transporte'::text,'est en train de transporter'::text,'Avant que la caméra ne l''observe, le porteur transportait des marchandises à travers le marché toute la matinée.'::text),
(375659,41740,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kamera onu gözlemlemeden önce hamal bütün sabah pazarda mal ...'::text,'taşıyordu'::text,'taşıyor'::text,'taşıyor'::text,'Kamera onu gözlemlemeden önce hamal bütün sabah pazarda mal taşıyordu.'::text),
(375660,41740,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mielőtt a kamera megfigyelte volna, a hordár egész délelőtt ... az árut a piacon át.'::text,'hordta'::text,'hordja'::text,'viszi'::text,'Mielőtt a kamera megfigyelte volna, a hordár egész délelőtt hordta az árut a piacon át.'::text),
(337197,37467,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seine Oma ... ihre Gläser in diesem Küchenschrank aufzubewahren.'::text,'pflegte'::text,'pflegte'::text,'war gewohnt,'::text,'Seine Oma pflegte ihre Gläser in diesem Küchenschrank aufzubewahren.'::text),
(337201,37467,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Його бабуся ... тримати свої банки в цій кухонній шафці.'::text,'мала звичку'::text,'мала звичку'::text,'звикла'::text,'Його бабуся мала звичку тримати свої банки в цій кухонній шафці.'::text),
(337200,37467,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su abuela ... guardar sus tarros en este armario de la cocina.'::text,'solía'::text,'solía'::text,'estaba acostumbrada a'::text,'Su abuela solía guardar sus tarros en este armario de la cocina.'::text),
(337199,37467,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sa grand-mère ... ranger ses bocaux dans ce placard de cuisine.'::text,'avait l''habitude de'::text,'avait l''habitude de'::text,'était habituée à'::text,'Sa grand-mère avait l''habitude de ranger ses bocaux dans ce placard de cuisine.'::text),
(337202,37467,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Büyükannesi kavanozlarını bu mutfak dolabında ...'::text,'tutardı'::text,'tutardı'::text,'tutmaya alışkındı'::text,'Büyükannesi kavanozlarını bu mutfak dolabında tutardı.'::text),
(337203,37467,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nagymamája ebben a konyhaszekrényben ... az üvegeit.'::text,'tartotta'::text,'tartotta'::text,'szokott volt tartani'::text,'A nagymamája ebben a konyhaszekrényben tartotta az üvegeit.'::text),
(392691,43633,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jeder einzelne Teller ... in diesem Schrank verstaut, und die Arbeitsplatte war komplett leer!'::text,'wurde'::text,'verstaute'::text,'verstaut'::text,'Jeder einzelne Teller wurde in diesem Schrank verstaut, und die Arbeitsplatte war komplett leer!'::text),
(392695,43633,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кожну тарілку ... в ту шафку, і стільниця була абсолютно порожня!'::text,'склали'::text,'склала'::text,'складає'::text,'Кожну тарілку склали в ту шафку, і стільниця була абсолютно порожня!'::text),
(392694,43633,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Cada plato ... en ese armario, y la encimera quedó completamente vacía!'::text,'fue guardado'::text,'guardó'::text,'está guardando'::text,'¡Cada plato fue guardado en ese armario, y la encimera quedó completamente vacía!'::text),
(392693,43633,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chaque assiette ... dans ce placard, et le plan de travail était complètement vide !'::text,'a été rangée'::text,'a rangé'::text,'est en train de ranger'::text,'Chaque assiette a été rangée dans ce placard, et le plan de travail était complètement vide !'::text),
(392696,43633,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her bir tabak o dolaba ... ve tezgâh tamamen boştu!'::text,'kaldırıldı'::text,'kaldırdı'::text,'kaldırıyor'::text,'Her bir tabak o dolaba kaldırıldı ve tezgâh tamamen boştu!'::text),
(392697,43633,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden egyes tányért ... abba a szekrénybe, és a pult teljesen üres lett!'::text,'elpakoltak'::text,'elpakolt'::text,'elpakol'::text,'Minden egyes tányért elpakoltak abba a szekrénybe, és a pult teljesen üres lett!'::text),
(360012,40002,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn eine Seilbahn in große Höhe steigt, ... die Luft kälter.'::text,'wird'::text,'wurde'::text,'würde'::text,'Wenn eine Seilbahn in große Höhe steigt, wird die Luft kälter.'::text),
(360016,40002,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли канатна дорога піднімається на велику висоту, повітря ... холоднішим.'::text,'стає'::text,'ставало'::text,'стало б'::text,'Коли канатна дорога піднімається на велику висоту, повітря стає холоднішим.'::text),
(360015,40002,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un teleférico sube a gran altura, el aire se ... más frío.'::text,'vuelve'::text,'volvió'::text,'volvería'::text,'Si un teleférico sube a gran altura, el aire se vuelve más frío.'::text),
(360014,40002,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un téléphérique monte à une grande hauteur, l''air ... plus froid.'::text,'devient'::text,'devenait'::text,'deviendrait'::text,'Si un téléphérique monte à une grande hauteur, l''air devient plus froid.'::text),
(360017,40002,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir teleferik büyük bir yüksekliğe çıkarsa hava ...'::text,'soğur'::text,'soğudu'::text,'soğurdu'::text,'Bir teleferik büyük bir yüksekliğe çıkarsa hava soğur.'::text),
(360018,40002,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy felvonó nagy magasságba emelkedik, a levegő ... hidegebb.'::text,'lesz'::text,'lett'::text,'lenne'::text,'Ha egy felvonó nagy magasságba emelkedik, a levegő lesz hidegebb.'::text),
(330312,36702,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Seilbahn noch höher fährt, ... ihm die Höhe die Ohren zu.'::text,'macht'::text,'machte'::text,'machte'::text,'Wenn die Seilbahn noch höher fährt, macht ihm die Höhe die Ohren zu.'::text),
(330316,36702,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо канатна дорога підніметься ще вище, від висоти йому ... вуха.'::text,'закладе'::text,'заклало б'::text,'заклало'::text,'Якщо канатна дорога підніметься ще вище, від висоти йому закладе вуха.'::text),
(330315,36702,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el teleférico sube más, la altitud le ... los oídos.'::text,'taponará'::text,'taponaría'::text,'taponó'::text,'Si el teleférico sube más, la altitud le taponará los oídos.'::text),
(330314,36702,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le téléphérique monte encore plus haut, l''altitude lui ... les oreilles.'::text,'bouchera'::text,'boucherait'::text,'a bouché'::text,'Si le téléphérique monte encore plus haut, l''altitude lui bouchera les oreilles.'::text),
(330317,36702,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Teleferik biraz daha yükselirse, rakım onun kulaklarını ...'::text,'tıkayacak'::text,'tıkardı'::text,'tıkadı'::text,'Teleferik biraz daha yükselirse, rakım onun kulaklarını tıkayacak.'::text),
(330318,36702,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a felvonó még feljebb megy, a magasság miatt ... a füle.'::text,'be fog dugulni'::text,'bedugulna'::text,'bedugult'::text,'Ha a felvonó még feljebb megy, a magasság miatt be fog dugulni a füle.'::text),
(404094,44900,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die kleine Figur ... laut, als ihr die Kaktusstacheln in die Hand stachen.'::text,'schrie'::text,'wurde geschrien'::text,'schreiend'::text,'Die kleine Figur schrie laut, als ihr die Kaktusstacheln in die Hand stachen.'::text),
(404098,44900,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Маленький персонаж голосно ..., коли колючки кактуса вкололи йому руку.'::text,'закричав'::text,'був закричаний'::text,'кричачи'::text,'Маленький персонаж голосно закричав, коли колючки кактуса вкололи йому руку.'::text),
(404097,44900,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El pequeño personaje ... fuerte cuando las espinas del cactus le pincharon la mano.'::text,'gritó'::text,'fue gritado'::text,'gritando'::text,'El pequeño personaje gritó fuerte cuando las espinas del cactus le pincharon la mano.'::text),
(404096,44900,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le petit personnage ... fort quand les épines du cactus lui ont piqué la main.'::text,'a crié'::text,'a été crié'::text,'criant'::text,'Le petit personnage a crié fort quand les épines du cactus lui ont piqué la main.'::text),
(404099,44900,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kaktüs dikenleri eline battığında küçük karakter yüksek sesle ...'::text,'bağırdı'::text,'bağırıldı'::text,'bağırarak'::text,'Kaktüs dikenleri eline battığında küçük karakter yüksek sesle bağırdı.'::text),
(404100,44900,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kis figura hangosan ..., amikor a kaktusz tüskéi megszúrták a kezét.'::text,'felkiáltott'::text,'fel lett kiáltva'::text,'kiabálva'::text,'A kis figura hangosan felkiáltott, amikor a kaktusz tüskéi megszúrták a kezét.'::text),
(347988,38666,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Barista beschloss, den Biskuitkuchen unter einer Glasglocke ...'::text,'auszustellen'::text,'ausstellend'::text,'ausstellen'::text,'Der Barista beschloss, den Biskuitkuchen unter einer Glasglocke auszustellen.'::text),
(347992,38666,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бариста вирішив ... бісквітний торт під скляним ковпаком.'::text,'виставити'::text,'виставляння'::text,'виставити'::text,'Бариста вирішив виставити бісквітний торт під скляним ковпаком.'::text),
(347991,38666,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El barista decidió ... el bizcocho bajo una campana de cristal.'::text,'exhibir'::text,'exhibiendo'::text,'exhibir'::text,'El barista decidió exhibir el bizcocho bajo una campana de cristal.'::text),
(347990,38666,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le barista a décidé d''... le gâteau éponge sous une cloche en verre.'::text,'exposer'::text,'exposant'::text,'exposer'::text,'Le barista a décidé d''exposer le gâteau éponge sous une cloche en verre.'::text),
(347993,38666,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Barista pandispanyayı cam bir fanusun altında ... karar verdi.'::text,'sergilemeye'::text,'sergileyerek'::text,'sergile'::text,'Barista pandispanyayı cam bir fanusun altında sergilemeye karar verdi.'::text),
(347994,38666,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A barista úgy döntött, hogy a piskótatortát egy üvegbura alatt ...'::text,'kiállítja'::text,'kiállítva'::text,'kiállít'::text,'A barista úgy döntött, hogy a piskótatortát egy üvegbura alatt kiállítja.'::text),
(345549,38395,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Düne bildet eine lange Kurve quer durch das Bild, ...?'::text,'oder'::text,'oder'::text,'oder'::text,'Die Düne bildet eine lange Kurve quer durch das Bild, oder?'::text),
(345553,38395,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дюна утворює один довгий вигин через усю картину, ...?'::text,'правда'::text,'правда'::text,'правда'::text,'Дюна утворює один довгий вигин через усю картину, правда?'::text),
(345552,38395,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La duna forma una larga curva a lo largo de la imagen, ¿...?'::text,'verdad'::text,'verdad'::text,'verdad'::text,'La duna forma una larga curva a lo largo de la imagen, ¿verdad?'::text),
(345551,38395,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La dune dessine une longue courbe à travers l''image, ... ?'::text,'n''est-ce pas'::text,'n''est-ce pas'::text,'n''est-ce pas'::text,'La dune dessine une longue courbe à travers l''image, n''est-ce pas ?'::text),
(345554,38395,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kum tepesi resim boyunca uzun bir kıvrım çiziyor, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Kum tepesi resim boyunca uzun bir kıvrım çiziyor, değil mi?'::text),
(345555,38395,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A dűne egyetlen hosszú ívet rajzol a képen át, ...?'::text,'ugye'::text,'ugye'::text,'ugye'::text,'A dűne egyetlen hosszú ívet rajzol a képen át, ugye?'::text),
(386247,42917,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Probandin ... gerade die Kopfsteinpflasterstraße mit ihrer Spiegelreflexkamera, als sie die Dachterrasse bemerkte.'::text,'fotografierte'::text,'fotografierte'::text,'hat fotografiert'::text,'Die Probandin fotografierte gerade die Kopfsteinpflasterstraße mit ihrer Spiegelreflexkamera, als sie die Dachterrasse bemerkte.'::text),
(386251,42917,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Піддосліджувана ... бруківку своєю дзеркалкою, коли помітила терасу на даху.'::text,'фотографувала'::text,'сфотографувала'::text,'сфотографувала'::text,'Піддосліджувана фотографувала бруківку своєю дзеркалкою, коли помітила терасу на даху.'::text),
(386250,42917,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La sujeto ... la calle empedrada con su réflex cuando observó la terraza de la azotea.'::text,'estaba fotografiando'::text,'fotografió'::text,'ha fotografiado'::text,'La sujeto estaba fotografiando la calle empedrada con su réflex cuando observó la terraza de la azotea.'::text),
(386249,42917,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le sujet ... la rue pavée avec son reflex quand elle a remarqué la terrasse sur le toit.'::text,'photographiait'::text,'a photographié'::text,'a photographié'::text,'Le sujet photographiait la rue pavée avec son reflex quand elle a remarqué la terrasse sur le toit.'::text),
(386252,42917,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Denek çatı terasını fark ettiğinde Arnavut kaldırımlı sokağı DSLR''ıyla ...'::text,'fotoğraflıyordu'::text,'fotoğrafladı'::text,'fotoğraflamış'::text,'Denek çatı terasını fark ettiğinde Arnavut kaldırımlı sokağı DSLR''ıyla fotoğraflıyordu.'::text),
(386253,42917,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az alany éppen ... a macskaköves utcát a tükörreflexes gépével, amikor észrevette a tetőteraszt.'::text,'fotózta'::text,'lefotózta'::text,'lefotózta'::text,'Az alany éppen fotózta a macskaköves utcát a tükörreflexes gépével, amikor észrevette a tetőteraszt.'::text),
(386337,42927,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als sie auf das Dach kletterte, ... sie schon drei Stunden lang fotografiert.'::text,'hatte'::text,'war'::text,'hat'::text,'Als sie auf das Dach kletterte, hatte sie schon drei Stunden lang fotografiert.'::text),
(386341,42927,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли вона вилізла на дах, вона вже три години ... фото.'::text,'робила'::text,'робила'::text,'робить'::text,'Коли вона вилізла на дах, вона вже три години робила фото.'::text),
(386340,42927,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando subió a la azotea, ella ya ... fotos durante tres horas.'::text,'llevaba haciendo'::text,'estaba haciendo'::text,'ha estado haciendo'::text,'Cuando subió a la azotea, ella ya llevaba haciendo fotos durante tres horas.'::text),
(386339,42927,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand elle est montée sur le toit, elle ... des photos depuis déjà trois heures.'::text,'prenait'::text,'prenait'::text,'prend'::text,'Quand elle est montée sur le toit, elle prenait des photos depuis déjà trois heures.'::text),
(386342,42927,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çatıya tırmandığında o zaten üç saattir fotoğraf ...'::text,'çekiyordu'::text,'çekiyordu'::text,'çekiyor'::text,'Çatıya tırmandığında o zaten üç saattir fotoğraf çekiyordu.'::text),
(386343,42927,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amikor felmászott a tetőre, ő már három órája ...'::text,'fotózott'::text,'fotózott'::text,'fotózik'::text,'Amikor felmászott a tetőre, ő már három órája fotózott.'::text),
(366294,40700,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie bald zur Blockhütte zurückkommt, ... sie heute Abend warm am Feuer.'::text,'sitzt'::text,'säße'::text,'saß'::text,'Wenn sie bald zur Blockhütte zurückkommt, sitzt sie heute Abend warm am Feuer.'::text),
(366298,40700,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вона скоро повернеться до зрубу, сьогодні ввечері вона ... в теплі біля вогню.'::text,'буде'::text,'була б'::text,'була'::text,'Якщо вона скоро повернеться до зрубу, сьогодні ввечері вона буде в теплі біля вогню.'::text),
(366297,40700,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si ella vuelve pronto a la cabaña de troncos, esta noche ... calentita junto al fuego.'::text,'estará'::text,'estaría'::text,'estaba'::text,'Si ella vuelve pronto a la cabaña de troncos, esta noche estará calentita junto al fuego.'::text),
(366296,40700,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle rentre bientôt à la cabane en rondins, elle ... au chaud près du feu ce soir.'::text,'sera'::text,'serait'::text,'était'::text,'Si elle rentre bientôt à la cabane en rondins, elle sera au chaud près du feu ce soir.'::text),
(366299,40700,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O yakında kütük kulübeye dönerse, bu akşam ateşin başında sıcacık ...'::text,'olacak'::text,'olurdu'::text,'oldu'::text,'O yakında kütük kulübeye dönerse, bu akşam ateşin başında sıcacık olacak.'::text),
(366300,40700,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha ő hamarosan visszaér a gerendaházba, ma este a tűz mellett ... melegben.'::text,'lesz'::text,'lenne'::text,'volt'::text,'Ha ő hamarosan visszaér a gerendaházba, ma este a tűz mellett lesz melegben.'::text),
(345774,38420,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann ist im Morgengrauen draußen auf dem See, und ...'::text,'der Elch auch.'::text,'der Elch auch.'::text,'der Elch war es auch.'::text,'Der Mann ist im Morgengrauen draußen auf dem See, und der Elch auch.'::text),
(345778,38420,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік на світанку на озері, і ...'::text,'лось теж.'::text,'лось теж.'::text,'лось теж був.'::text,'Чоловік на світанку на озері, і лось теж.'::text),
(345777,38420,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre está en el lago al amanecer, y ...'::text,'el alce también.'::text,'el alce también.'::text,'el alce también estaba.'::text,'El hombre está en el lago al amanecer, y el alce también.'::text),
(345776,38420,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme est sur le lac à l''aube, et ...'::text,'l''élan aussi.'::text,'l''élan aussi.'::text,'l''élan y était aussi.'::text,'L''homme est sur le lac à l''aube, et l''élan aussi.'::text),
(345779,38420,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam şafakta gölde ve ...'::text,'geyik de.'::text,'geyik de.'::text,'geyik de oradaydı.'::text,'Adam şafakta gölde ve geyik de.'::text),
(345780,38420,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi hajnalban kint van a tavon, és ...'::text,'a jávorszarvas is.'::text,'a jávorszarvas is.'::text,'a jávorszarvas is ott volt.'::text,'A férfi hajnalban kint van a tavon, és a jávorszarvas is.'::text),
(348303,38701,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ein Dokument einen Fehler ..., stempelt er es mit einem wütenden roten X ab!'::text,'hat'::text,'hatte'::text,'haben wird'::text,'Wenn ein Dokument einen Fehler hat, stempelt er es mit einem wütenden roten X ab!'::text),
(348307,38701,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо документ ... хоч одну помилку, він штампує на ньому люте червоне X!'::text,'має'::text,'мав'::text,'матиме'::text,'Якщо документ має хоч одну помилку, він штампує на ньому люте червоне X!'::text),
(348306,38701,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si un documento ... un error, él lo sella con una X roja furiosa!'::text,'tiene'::text,'tenía'::text,'tendrá'::text,'¡Si un documento tiene un error, él lo sella con una X roja furiosa!'::text),
(348305,38701,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un document ... une seule erreur, il le tamponne d''un X rouge furieux !'::text,'contient'::text,'contenait'::text,'contiendra'::text,'Si un document contient une seule erreur, il le tamponne d''un X rouge furieux !'::text),
(348308,38701,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir belgede tek bir hata ..., o belgeye öfkeyle kırmızı bir X basıyor!'::text,'varsa'::text,'vardıysa'::text,'olacaksa'::text,'Bir belgede tek bir hata varsa, o belgeye öfkeyle kırmızı bir X basıyor!'::text),
(348309,38701,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy dokumentumban ... egy hiba, ő dühösen piros X-et pecsétel rá!'::text,'van'::text,'volt'::text,'lesz'::text,'Ha egy dokumentumban van egy hiba, ő dühösen piros X-et pecsétel rá!'::text),
(348330,38704,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, er ... das Dokument so hart ab, dass die Papiere durch die Luft flogen, echt jetzt.'::text,'stempelte'::text,'stempelte'::text,'stempelte gerade'::text,'Bro, er stempelte das Dokument so hart ab, dass die Papiere durch die Luft flogen, echt jetzt.'::text),
(348334,38704,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, він так сильно ... той документ, що папери розлетілися, чесно.'::text,'проштампував'::text,'проштампував'::text,'штампував'::text,'Бро, він так сильно проштампував той документ, що папери розлетілися, чесно.'::text),
(348333,38704,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, él ... ese documento tan fuerte que los papeles salieron volando, en serio.'::text,'selló'::text,'había sellado'::text,'estaba sellando'::text,'Bro, él selló ese documento tan fuerte que los papeles salieron volando, en serio.'::text),
(348332,38704,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, il ... ce document tellement fort que les papiers se sont envolés, sérieux.'::text,'a tamponné'::text,'avait tamponné'::text,'tamponnait'::text,'Frère, il a tamponné ce document tellement fort que les papiers se sont envolés, sérieux.'::text),
(348335,38704,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o o belgeyi öyle sert ... ki kâğıtlar uçuştu, cidden.'::text,'damgaladı'::text,'damgalamıştı'::text,'damgalıyordu'::text,'Kanka, o o belgeyi öyle sert damgaladı ki kâğıtlar uçuştu, cidden.'::text),
(348336,38704,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ő olyan erősen ... le azt a dokumentumot, hogy a papírok szétrepültek, komolyan.'::text,'pecsételte'::text,'pecsételte'::text,'pecsételte éppen'::text,'Tesó, ő olyan erősen pecsételte le azt a dokumentumot, hogy a papírok szétrepültek, komolyan.'::text),
(402033,44671,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Kerze brennt schon seit Stunden, also ... diese Pfütze auf dem Tisch geschmolzenes Wachs sein.'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Die Kerze brennt schon seit Stunden, also muss diese Pfütze auf dem Tisch geschmolzenes Wachs sein.'::text),
(402037,44671,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Свічка горить уже кілька годин, тож ця калюжка на столі ... бути розтопленим воском.'::text,'мусить'::text,'не може'::text,'мала б'::text,'Свічка горить уже кілька годин, тож ця калюжка на столі мусить бути розтопленим воском.'::text),
(402036,44671,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La vela lleva horas encendida, así que este charco de la mesa ... ser cera derretida.'::text,'debe de'::text,'no puede'::text,'debería'::text,'La vela lleva horas encendida, así que este charco de la mesa debe de ser cera derretida.'::text),
(402035,44671,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La bougie brûle depuis des heures, donc cette flaque sur la table ... être de la cire fondue.'::text,'doit'::text,'ne peut pas'::text,'devrait'::text,'La bougie brûle depuis des heures, donc cette flaque sur la table doit être de la cire fondue.'::text),
(402038,44671,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mum saatlerdir yanıyor, yani masadaki bu birikinti erimiş mum ...'::text,'olmalı'::text,'olamaz'::text,'olması gerekir'::text,'Mum saatlerdir yanıyor, yani masadaki bu birikinti erimiş mum olmalı.'::text),
(402039,44671,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gyertya már órák óta ég, szóval ez a tócsa az asztalon ... olvadt viasz.'::text,'biztosan'::text,'nem lehet'::text,'elvileg'::text,'A gyertya már órák óta ég, szóval ez a tócsa az asztalon biztosan olvadt viasz.'::text),
(361956,40218,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Mann stehen bliebe und sich umdrehte, ... er die beeindruckende goldene Kuppel hinter sich.'::text,'sähe'::text,'sieht'::text,'sah'::text,'Wenn der Mann stehen bliebe und sich umdrehte, sähe er die beeindruckende goldene Kuppel hinter sich.'::text),
(361960,40218,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби чоловік зупинився й озирнувся, він ... позаду себе вражаючий золотий купол.'::text,'побачив би'::text,'побачить'::text,'побачив'::text,'Якби чоловік зупинився й озирнувся, він побачив би позаду себе вражаючий золотий купол.'::text),
(361959,40218,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el hombre se detuviera a mirar atrás, él ... la impresionante cúpula dorada detrás de él.'::text,'vería'::text,'verá'::text,'vio'::text,'Si el hombre se detuviera a mirar atrás, él vería la impresionante cúpula dorada detrás de él.'::text),
(361958,40218,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si l''homme s''arrêtait pour regarder derrière lui, il ... l''impressionnant dôme doré.'::text,'verrait'::text,'verra'::text,'a vu'::text,'Si l''homme s''arrêtait pour regarder derrière lui, il verrait l''impressionnant dôme doré.'::text),
(361961,40218,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam durup arkasına baksa, o arkasındaki etkileyici altın kubbeyi ...'::text,'görürdü'::text,'görecek'::text,'gördü'::text,'Adam durup arkasına baksa, o arkasındaki etkileyici altın kubbeyi görürdü.'::text),
(361962,40218,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a férfi megállna visszanézni, ő ... maga mögött a lenyűgöző aranykupolát.'::text,'látná'::text,'látni fogja'::text,'látta'::text,'Ha a férfi megállna visszanézni, ő látná maga mögött a lenyűgöző aranykupolát.'::text),
(393483,43721,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der alte Seemann, ... mit dem Steuerrad kämpft, hat schon viele Stürme durchsegelt.'::text,'der'::text,'das'::text,'dessen'::text,'Der alte Seemann, der mit dem Steuerrad kämpft, hat schon viele Stürme durchsegelt.'::text),
(393487,43721,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Старий моряк, ... бореться зі штурвалом, пройшов крізь багато штормів.'::text,'який'::text,'яке'::text,'чий'::text,'Старий моряк, який бореться зі штурвалом, пройшов крізь багато штормів.'::text),
(393486,43721,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El viejo marinero ... lucha con el timón ha navegado a través de muchas tormentas.'::text,'que'::text,'el cual'::text,'cuyo'::text,'El viejo marinero que lucha con el timón ha navegado a través de muchas tormentas.'::text),
(393485,43721,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le vieux marin ... lutte avec la barre a traversé de nombreuses tempêtes.'::text,'qui'::text,'lequel'::text,'dont'::text,'Le vieux marin qui lutte avec la barre a traversé de nombreuses tempêtes.'::text),
(393488,43721,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dümenle ... yaşlı denizci birçok fırtınadan geçti.'::text,'boğuşan'::text,'boğuşan'::text,'boğuşanın'::text,'Dümenle boğuşan yaşlı denizci birçok fırtınadan geçti.'::text),
(393489,43721,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az öreg tengerész, ... a kormánykerékkel küzd, már sok viharon átvitorlázott.'::text,'aki'::text,'ami'::text,'akinek'::text,'Az öreg tengerész, aki a kormánykerékkel küzd, már sok viharon átvitorlázott.'::text),
(364710,40524,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... den Teppich mit einem Schubs flach aus und legte sich dann hin. Anstrengende Arbeit, offensichtlich.'::text,'rollte'::text,'rollte gerade'::text,'rollt'::text,'Er rollte den Teppich mit einem Schubs flach aus und legte sich dann hin. Anstrengende Arbeit, offensichtlich.'::text),
(364714,40524,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він одним поштовхом ... килим, а потім ліг. Виснажлива робота, очевидно.'::text,'розстелив'::text,'розстеляв'::text,'розстелив'::text,'Він одним поштовхом розстелив килим, а потім ліг. Виснажлива робота, очевидно.'::text),
(364713,40524,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... la alfombra de un solo empujón y luego se tumbó. Un trabajo agotador, obviamente.'::text,'extendió'::text,'estaba extendiendo'::text,'ha extendido'::text,'Él extendió la alfombra de un solo empujón y luego se tumbó. Un trabajo agotador, obviamente.'::text),
(364712,40524,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... le tapis d''une seule poussée, puis s''est allongé. Travail épuisant, évidemment.'::text,'a étalé'::text,'étalait'::text,'a étalé'::text,'Il a étalé le tapis d''une seule poussée, puis s''est allongé. Travail épuisant, évidemment.'::text),
(364715,40524,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O halıyı tek itişte dümdüz ..., sonra uzandı. Yorucu bir iş, belli ki.'::text,'serdi'::text,'seriyordu'::text,'sermiş'::text,'O halıyı tek itişte dümdüz serdi, sonra uzandı. Yorucu bir iş, belli ki.'::text),
(364716,40524,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő egyetlen lökéssel ... a szőnyeget, aztán lefeküdt. Kimerítő munka, nyilván.'::text,'kiterítette'::text,'éppen terítette ki'::text,'kiterítette'::text,'Ő egyetlen lökéssel kiterítette a szőnyeget, aztán lefeküdt. Kimerítő munka, nyilván.'::text),
(364719,40525,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Statt den neuen Teppich von einem Geschäft ... zu lassen, rollte er ihn selbst aus.'::text,'verlegen'::text,'verlegen'::text,'verlegend'::text,'Statt den neuen Teppich von einem Geschäft verlegen zu lassen, rollte er ihn selbst aus.'::text),
(364723,40525,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Замість того щоб дати магазину ... новий килим, він сам його розгорнув.'::text,'постелити'::text,'постелити'::text,'стелення'::text,'Замість того щоб дати магазину постелити новий килим, він сам його розгорнув.'::text),
(364722,40525,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En vez de mandar ... la alfombra nueva a una tienda, él mismo la desenrolló.'::text,'colocar'::text,'colocar'::text,'colocando'::text,'En vez de mandar colocar la alfombra nueva a una tienda, él mismo la desenrolló.'::text),
(364721,40525,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Au lieu de faire ... le nouveau tapis par un magasin, il l''a déroulé lui-même.'::text,'poser'::text,'poser'::text,'posant'::text,'Au lieu de faire poser le nouveau tapis par un magasin, il l''a déroulé lui-même.'::text),
(364724,40525,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yeni halıyı bir mağazaya ... yerine, o kendisi açtı.'::text,'serdirmek'::text,'sermek'::text,'sererek'::text,'Yeni halıyı bir mağazaya serdirmek yerine, o kendisi açtı.'::text),
(364725,40525,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahelyett, hogy egy bolttal ... volna az új szőnyeget, ő maga terítette ki.'::text,'leteríttette'::text,'leterítette'::text,'leterítve'::text,'Ahelyett, hogy egy bolttal leteríttette volna az új szőnyeget, ő maga terítette ki.'::text),
(387111,43013,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Schon in der Grundschule ... sie jeden Gips zu unterschreiben, und absolut nichts hat sich geändert!'::text,'pflegten'::text,'pflegten'::text,'waren gewohnt,'::text,'Schon in der Grundschule pflegten sie jeden Gips zu unterschreiben, und absolut nichts hat sich geändert!'::text),
(387115,43013,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ще в початковій школі вони ... розписуватися на кожному гіпсі, і абсолютно нічого не змінилося!'::text,'мали звичку'::text,'мали звичку'::text,'звикли'::text,'Ще в початковій школі вони мали звичку розписуватися на кожному гіпсі, і абсолютно нічого не змінилося!'::text),
(387114,43013,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ya en primaria ellos ... firmar todas las escayolas, y no ha cambiado absolutamente nada!'::text,'solían'::text,'solían'::text,'estaban acostumbrados a'::text,'¡Ya en primaria ellos solían firmar todas las escayolas, y no ha cambiado absolutamente nada!'::text),
(387113,43013,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Déjà à l''école primaire, ils ... signer chaque plâtre, et absolument rien n''a changé !'::text,'avaient l''habitude de'::text,'avaient l''habitude de'::text,'étaient habitués à'::text,'Déjà à l''école primaire, ils avaient l''habitude de signer chaque plâtre, et absolument rien n''a changé !'::text),
(387116,43013,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Daha ilkokuldayken onlar her alçıyı ... ve kesinlikle hiçbir şey değişmedi!'::text,'imzalardı'::text,'imzalardı'::text,'imzalamaya alışkındı'::text,'Daha ilkokuldayken onlar her alçıyı imzalardı ve kesinlikle hiçbir şey değişmedi!'::text),
(387117,43013,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már az általános iskolában is ők ... minden gipszet, és abszolút semmi sem változott!'::text,'alá szoktak írni'::text,'alá szoktak írni'::text,'hozzá voltak szokva aláírni'::text,'Már az általános iskolában is ők alá szoktak írni minden gipszet, és abszolút semmi sem változott!'::text),
(387147,43017,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, ich hab gehört, sie ... eine Stunde lang auf seinem Gips unterschrieben, bevor der Lehrer es überhaupt gemerkt hat.'::text,'hatten'::text,'haben'::text,'waren'::text,'Bestie, ich hab gehört, sie hatten eine Stunde lang auf seinem Gips unterschrieben, bevor der Lehrer es überhaupt gemerkt hat.'::text),
(387151,43017,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, я чула, що вони ... на його гіпсі цілу годину, перш ніж учитель узагалі помітив.'::text,'розписувалися'::text,'розписуються'::text,'розписувалися'::text,'Подруго, я чула, що вони розписувалися на його гіпсі цілу годину, перш ніж учитель узагалі помітив.'::text),
(387150,43017,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, yo oí que ellos ... su escayola durante una hora antes de que el profe se diera cuenta.'::text,'habían estado firmando'::text,'han estado firmando'::text,'estaban firmando'::text,'Amiga, yo oí que ellos habían estado firmando su escayola durante una hora antes de que el profe se diera cuenta.'::text),
(387149,43017,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, j''ai entendu dire qu''ils ... son plâtre depuis une heure avant que le prof remarque quoi que ce soit.'::text,'signaient'::text,'signent'::text,'signaient'::text,'Ma belle, j''ai entendu dire qu''ils signaient son plâtre depuis une heure avant que le prof remarque quoi que ce soit.'::text),
(387152,43017,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, ben duydum ki öğretmen fark edene kadar onlar bir saat boyunca onun alçısını ...'::text,'imzalıyorlarmış'::text,'imzalıyorlar'::text,'imzalıyorlardı'::text,'Kanka, ben duydum ki öğretmen fark edene kadar onlar bir saat boyunca onun alçısını imzalıyorlarmış.'::text),
(387153,43017,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, én úgy hallottam, hogy ők egy órán át ... a gipszét, mielőtt a tanár egyáltalán észrevette.'::text,'írták alá'::text,'írják alá'::text,'írták alá'::text,'Csajszi, én úgy hallottam, hogy ők egy órán át írták alá a gipszét, mielőtt a tanár egyáltalán észrevette.'::text),
(338970,37664,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diese Schlafzimmerdecke ... früher sein Lieblingsfernseher. Fesselnd.'::text,'war'::text,'war'::text,'war gewöhnt,'::text,'Diese Schlafzimmerdecke war früher sein Lieblingsfernseher. Fesselnd.'::text),
(338974,37664,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ця стеля в спальні ... його улюбленим телевізором. Захопливо.'::text,'колись була'::text,'колись була'::text,'звикла бути'::text,'Ця стеля в спальні колись була його улюбленим телевізором. Захопливо.'::text),
(338973,37664,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El techo de este dormitorio ... ser su tele favorita. Apasionante.'::text,'solía'::text,'solía'::text,'estaba acostumbrado a'::text,'El techo de este dormitorio solía ser su tele favorita. Apasionante.'::text),
(338972,37664,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce plafond de chambre ... sa télé préférée. Passionnant.'::text,'était autrefois'::text,'était autrefois'::text,'avait l''habitude d''être'::text,'Ce plafond de chambre était autrefois sa télé préférée. Passionnant.'::text),
(338975,37664,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu yatak odası tavanı ... onun en sevdiği televizyondu. Sürükleyici.'::text,'eskiden'::text,'eskiden'::text,'alışkanlıkla'::text,'Bu yatak odası tavanı eskiden onun en sevdiği televizyondu. Sürükleyici.'::text),
(338976,37664,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez a hálószobai plafon ... a kedvenc tévéje. Lebilincselő.'::text,'volt régen'::text,'volt régen'::text,'volt hozzászokva, hogy legyen'::text,'Ez a hálószobai plafon volt régen a kedvenc tévéje. Lebilincselő.'::text),
(338997,37667,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Ende der Führung hat er jede Figur an der bemalten Decke ...'::text,'gesehen'::text,'gesehen'::text,'sehen'::text,'Bis zum Ende der Führung hat er jede Figur an der bemalten Decke gesehen.'::text),
(339001,37667,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До кінця екскурсії він ... кожну фігуру на розписаній стелі.'::text,'побачить'::text,'побачить'::text,'бачитиме'::text,'До кінця екскурсії він побачить кожну фігуру на розписаній стелі.'::text),
(339000,37667,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el final de la visita, él ... cada figura del techo pintado.'::text,'habrá visto'::text,'verá'::text,'estará viendo'::text,'Para el final de la visita, él habrá visto cada figura del techo pintado.'::text),
(338999,37667,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici la fin de la visite, il ... chaque personnage du plafond peint.'::text,'aura vu'::text,'verra'::text,'sera en train de voir'::text,'D''ici la fin de la visite, il aura vu chaque personnage du plafond peint.'::text),
(339002,37667,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Turun sonuna kadar o boyalı tavandaki her figürü ...'::text,'görmüş olacak'::text,'görecek'::text,'görüyor olacak'::text,'Turun sonuna kadar o boyalı tavandaki her figürü görmüş olacak.'::text),
(339003,37667,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A túra végére ő ... a festett mennyezet minden alakját.'::text,'látni fogja'::text,'látni fogja'::text,'éppen nézni fogja'::text,'A túra végére ő látni fogja a festett mennyezet minden alakját.'::text),
(332652,36962,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Junge ... ewig auf seinem Stuhl geschaukelt, bevor er nach hinten umkippte.'::text,'hatte'::text,'hat'::text,'war'::text,'Der Junge hatte ewig auf seinem Stuhl geschaukelt, bevor er nach hinten umkippte.'::text),
(332656,36962,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хлопець ... на стільці цілу вічність, поки той не перекинувся назад.'::text,'гойдався'::text,'гойдається'::text,'гойдався'::text,'Хлопець гойдався на стільці цілу вічність, поки той не перекинувся назад.'::text),
(332655,36962,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El chico ... en su silla durante siglos antes de que se volcara hacia atrás.'::text,'se había estado balanceando'::text,'se ha estado balanceando'::text,'se estaba balanceando'::text,'El chico se había estado balanceando en su silla durante siglos antes de que se volcara hacia atrás.'::text),
(332654,36962,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le garçon ... sur sa chaise depuis une éternité avant qu''elle bascule en arrière.'::text,'se balançait'::text,'se balance'::text,'se balançait'::text,'Le garçon se balançait sur sa chaise depuis une éternité avant qu''elle bascule en arrière.'::text),
(332657,36962,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çocuk sandalye geriye doğru devrilmeden önce uzun süre sandalyesinde ...'::text,'sallanıyordu'::text,'sallanıyor'::text,'sallanıyordu'::text,'Çocuk sandalye geriye doğru devrilmeden önce uzun süre sandalyesinde sallanıyordu.'::text),
(332658,36962,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fiú egy örökkévalóságig ... a székén, mielőtt az hátrabillent.'::text,'hintázott'::text,'hintázik'::text,'hintázott'::text,'A fiú egy örökkévalóságig hintázott a székén, mielőtt az hátrabillent.'::text),
(341004,37890,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, wenn der Typ sich nicht in den Sessel geworfen hätte, ... er nicht so viel Gemütlichkeit gespürt, echt jetzt.'::text,'hätte'::text,'wird'::text,'hat'::text,'Bro, wenn der Typ sich nicht in den Sessel geworfen hätte, hätte er nicht so viel Gemütlichkeit gespürt, echt jetzt.'::text),
(341008,37890,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, якби той чувак не плюхнувся в крісло, він ... такого комфорту, чесно.'::text,'не відчув би'::text,'не відчує'::text,'не відчув'::text,'Бро, якби той чувак не плюхнувся в крісло, він не відчув би такого комфорту, чесно.'::text),
(341007,37890,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, si ese tío no se hubiera tirado en el sillón, él ... tanta comodidad, en serio.'::text,'no habría sentido'::text,'no sentirá'::text,'no sintió'::text,'Bro, si ese tío no se hubiera tirado en el sillón, él no habría sentido tanta comodidad, en serio.'::text),
(341006,37890,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, si ce mec ne s''était pas affalé dans le fauteuil, il ... autant de confort, sérieux.'::text,'n''aurait pas ressenti'::text,'ne ressentira pas'::text,'n''a pas ressenti'::text,'Frère, si ce mec ne s''était pas affalé dans le fauteuil, il n''aurait pas ressenti autant de confort, sérieux.'::text),
(341009,37890,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o adam koltuğa kendini atmasaydı, o kadar rahatlık ..., cidden.'::text,'hissetmezdi'::text,'hissetmeyecek'::text,'hissetmedi'::text,'Kanka, o adam koltuğa kendini atmasaydı, o kadar rahatlık hissetmezdi, cidden.'::text),
(341010,37890,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ha az a srác nem huppan bele a fotelbe, ő ... ennyire kényelmesen magát, komolyan.'::text,'nem érezte volna'::text,'nem fogja érezni'::text,'nem érezte'::text,'Tesó, ha az a srác nem huppan bele a fotelbe, ő nem érezte volna ennyire kényelmesen magát, komolyan.'::text),
(395193,43911,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Mitarbeiterin sagte dem Passagier, dass sie einen zweiten Anhänger an seinen Koffer ...'::text,'gebunden hatte'::text,'gebunden hat'::text,'bindet'::text,'Die Mitarbeiterin sagte dem Passagier, dass sie einen zweiten Anhänger an seinen Koffer gebunden hatte.'::text),
(395197,43911,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Працівниця сказала пасажирові, що вона ... другу бирку до його валізи.'::text,'прив''язала'::text,'прив''язала'::text,'прив''язує'::text,'Працівниця сказала пасажирові, що вона прив''язала другу бирку до його валізи.'::text),
(395196,43911,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La agente le dijo al pasajero que ella ... una segunda etiqueta a su maleta.'::text,'había atado'::text,'ha atado'::text,'ata'::text,'La agente le dijo al pasajero que ella había atado una segunda etiqueta a su maleta.'::text),
(395195,43911,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''agente a dit au passager qu''elle ... une deuxième étiquette à sa valise.'::text,'avait attaché'::text,'a attaché'::text,'attache'::text,'L''agente a dit au passager qu''elle avait attaché une deuxième étiquette à sa valise.'::text),
(395198,43911,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Görevli, yolcuya bavuluna ikinci bir etiket ... söyledi.'::text,'bağladığını'::text,'bağladığını'::text,'bağladığını'::text,'Görevli, yolcuya bavuluna ikinci bir etiket bağladığını söyledi.'::text),
(395199,43911,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az ügyintéző azt mondta az utasnak, hogy ő ... egy második címkét a bőröndjére.'::text,'kötött'::text,'kötött'::text,'köt'::text,'Az ügyintéző azt mondta az utasnak, hogy ő kötött egy második címkét a bőröndjére.'::text),
(365943,40661,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann ... seine Koffer aufs Band, während er seinen Pass im Mund hielt.'::text,'lud'::text,'wurde geladen'::text,'ladend'::text,'Der Mann lud seine Koffer aufs Band, während er seinen Pass im Mund hielt.'::text),
(365947,40661,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік ... валізи на стрічку, поки тримав паспорт у зубах.'::text,'поклав'::text,'був покладений'::text,'кладучи'::text,'Чоловік поклав валізи на стрічку, поки тримав паспорт у зубах.'::text),
(365946,40661,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre ... sus maletas en la cinta mientras sujetaba el pasaporte con la boca.'::text,'cargó'::text,'fue cargado'::text,'cargando'::text,'El hombre cargó sus maletas en la cinta mientras sujetaba el pasaporte con la boca.'::text),
(365945,40661,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme ... ses valises sur le tapis pendant qu''il tenait son passeport dans la bouche.'::text,'a chargé'::text,'a été chargé'::text,'chargeant'::text,'L''homme a chargé ses valises sur le tapis pendant qu''il tenait son passeport dans la bouche.'::text),
(365948,40661,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam pasaportunu ağzında tutarken bavullarını banda ...'::text,'yükledi'::text,'yüklendi'::text,'yükleyerek'::text,'Adam pasaportunu ağzında tutarken bavullarını banda yükledi.'::text),
(365949,40661,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi ... a bőröndjeit a szalagra, miközben az útlevelét a szájában tartotta.'::text,'feltette'::text,'fel lett téve'::text,'feltéve'::text,'A férfi feltette a bőröndjeit a szalagra, miközben az útlevelét a szájában tartotta.'::text),
(365997,40667,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aktuell ... der Reisende seine 23-Kilo-Reisetasche aufs Band, im Zeitplan.'::text,'lädt'::text,'lädt'::text,'lud'::text,'Aktuell lädt der Reisende seine 23-Kilo-Reisetasche aufs Band, im Zeitplan.'::text),
(366001,40667,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Наразі мандрівник ... свою 23-кілограмову сумку на стрічку, за графіком.'::text,'вантажить'::text,'вантажить'::text,'завантажив'::text,'Наразі мандрівник вантажить свою 23-кілограмову сумку на стрічку, за графіком.'::text),
(366000,40667,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Actualmente, el viajero ... su bolsa de 23 kilos en la cinta, según lo previsto.'::text,'está cargando'::text,'carga'::text,'ha cargado'::text,'Actualmente, el viajero está cargando su bolsa de 23 kilos en la cinta, según lo previsto.'::text),
(365999,40667,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Actuellement, le voyageur ... son sac de 23 kilos sur le tapis, dans les temps.'::text,'est en train de charger'::text,'charge'::text,'a chargé'::text,'Actuellement, le voyageur est en train de charger son sac de 23 kilos sur le tapis, dans les temps.'::text),
(366002,40667,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda yolcu 23 kiloluk çantasını plana uygun şekilde banda ...'::text,'yüklüyor'::text,'yükler'::text,'yükledi'::text,'Şu anda yolcu 23 kiloluk çantasını plana uygun şekilde banda yüklüyor.'::text),
(366003,40667,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jelenleg az utazó ... a 23 kilós táskáját a szalagra, az ütemterv szerint.'::text,'felteszi'::text,'felteszi'::text,'feltette'::text,'Jelenleg az utazó felteszi a 23 kilós táskáját a szalagra, az ütemterv szerint.'::text),
(384996,42778,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Was für ein Service! Er hat seine Tasche in zehn Sekunden ... bekommen, ein echtes Wunder!'::text,'etikettiert'::text,'etikettieren'::text,'zu etikettieren'::text,'Was für ein Service! Er hat seine Tasche in zehn Sekunden etikettiert bekommen, ein echtes Wunder!'::text),
(385000,42778,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Оце сервіс! Він отримав свою сумку ... за десять секунд, справжнє диво!'::text,'з биркою'::text,'з биркою'::text,'з биркою'::text,'Оце сервіс! Він отримав свою сумку з биркою за десять секунд, справжнє диво!'::text),
(384999,42778,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Qué servicio! Él consiguió que le ... la bolsa en diez segundos, ¡un milagro total!'::text,'etiquetaran'::text,'etiquetar'::text,'a etiquetar'::text,'¡Qué servicio! Él consiguió que le etiquetaran la bolsa en diez segundos, ¡un milagro total!'::text),
(384998,42778,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quel service ! Il a fait ... son sac en dix secondes, un vrai miracle !'::text,'étiqueter'::text,'étiqueter'::text,'à étiqueter'::text,'Quel service ! Il a fait étiqueter son sac en dix secondes, un vrai miracle !'::text),
(385001,42778,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ne hizmet ama! O çantasını on saniyede ..., tam bir mucize!'::text,'etiketletti'::text,'etiketle'::text,'etiketlemek'::text,'Ne hizmet ama! O çantasını on saniyede etiketletti, tam bir mucize!'::text),
(385002,42778,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Micsoda kiszolgálás! Ő tíz másodperc alatt ... a táskáját, igazi csoda!'::text,'felcímkéztette'::text,'felcímkéz'::text,'felcímkézni'::text,'Micsoda kiszolgálás! Ő tíz másodperc alatt felcímkéztette a táskáját, igazi csoda!'::text),
(359517,39947,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Nest der Henne ... in der Scheune aus trockenem gelbem Heu gebaut.'::text,'wurde'::text,'baute'::text,'baute gerade'::text,'Das Nest der Henne wurde in der Scheune aus trockenem gelbem Heu gebaut.'::text),
(359521,39947,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гніздо курки ... в сараї із сухого жовтого сіна.'::text,'було збудоване'::text,'збудувало'::text,'будувало'::text,'Гніздо курки було збудоване в сараї із сухого жовтого сіна.'::text),
(359520,39947,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El nido de la gallina ... con heno amarillo seco en el granero.'::text,'fue construido'::text,'construyó'::text,'estaba construyendo'::text,'El nido de la gallina fue construido con heno amarillo seco en el granero.'::text),
(359519,39947,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le nid de la poule ... avec du foin jaune séché dans la grange.'::text,'a été construit'::text,'a construit'::text,'construisait'::text,'Le nid de la poule a été construit avec du foin jaune séché dans la grange.'::text),
(359522,39947,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tavuğun yuvası ahırda kuru sarı samandan ...'::text,'yapıldı'::text,'yaptı'::text,'yapıyordu'::text,'Tavuğun yuvası ahırda kuru sarı samandan yapıldı.'::text),
(359523,39947,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tyúk fészkét száraz sárga szénából ... a pajtában.'::text,'építették'::text,'épített'::text,'építette éppen'::text,'A tyúk fészkét száraz sárga szénából építették a pajtában.'::text),
(377391,41933,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mit einem kräftigen Zug am Seil ... der Schornsteinfeger die Bürste den Kamin hinunter.'::text,'zog'::text,'wurde gezogen'::text,'ziehend'::text,'Mit einem kräftigen Zug am Seil zog der Schornsteinfeger die Bürste den Kamin hinunter.'::text),
(377395,41933,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Одним сильним ривком за мотузку сажотрус ... щітку вниз по димарю.'::text,'стягнув'::text,'був стягнутий'::text,'стягуючи'::text,'Одним сильним ривком за мотузку сажотрус стягнув щітку вниз по димарю.'::text),
(377394,41933,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Con un fuerte tirón de la cuerda, el deshollinador ... el cepillo chimenea abajo.'::text,'arrastró'::text,'fue arrastrado'::text,'arrastrando'::text,'Con un fuerte tirón de la cuerda, el deshollinador arrastró el cepillo chimenea abajo.'::text),
(377393,41933,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''un bon coup sur la corde, le ramoneur ... la brosse dans la cheminée.'::text,'a tiré'::text,'a été tiré'::text,'tirant'::text,'D''un bon coup sur la corde, le ramoneur a tiré la brosse dans la cheminée.'::text),
(377396,41933,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İpe tek bir güçlü asılışla baca temizleyicisi fırçayı bacadan aşağı ...'::text,'çekti'::text,'çekildi'::text,'çekerek'::text,'İpe tek bir güçlü asılışla baca temizleyicisi fırçayı bacadan aşağı çekti.'::text),
(377397,41933,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy erős rántással a kötélen a kéményseprő ... a kefét a kéményben.'::text,'lehúzta'::text,'le lett húzva'::text,'lehúzva'::text,'Egy erős rántással a kötélen a kéményseprő lehúzta a kefét a kéményben.'::text),
(331734,36860,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er das Feuer die ganze Nacht am Laufen hält, ... es noch mehr Asche. Herrlich.'::text,'gibt'::text,'gäbe'::text,'gab'::text,'Wenn er das Feuer die ganze Nacht am Laufen hält, gibt es noch mehr Asche. Herrlich.'::text),
(331738,36860,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо він підтримуватиме вогонь усю ніч, ... ще більше попелу. Чудово.'::text,'буде'::text,'було б'::text,'було'::text,'Якщо він підтримуватиме вогонь усю ніч, буде ще більше попелу. Чудово.'::text),
(331737,36860,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si él mantiene el fuego toda la noche, ... todavía más ceniza. Encantador.'::text,'habrá'::text,'habría'::text,'hubo'::text,'Si él mantiene el fuego toda la noche, habrá todavía más ceniza. Encantador.'::text),
(331736,36860,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il entretient le feu toute la nuit, il y ... encore plus de cendres. Délicieux.'::text,'aura'::text,'aurait'::text,'avait'::text,'S''il entretient le feu toute la nuit, il y aura encore plus de cendres. Délicieux.'::text),
(331739,36860,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O ateşi bütün gece yanık tutarsa, daha da fazla kül ...! Harika.'::text,'olacak'::text,'olurdu'::text,'oldu'::text,'O ateşi bütün gece yanık tutarsa, daha da fazla kül olacak! Harika.'::text),
(331740,36860,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha ő egész éjjel égve tartja a tüzet, ... még több hamu. Csodás.'::text,'lesz'::text,'lenne'::text,'volt'::text,'Ha ő egész éjjel égve tartja a tüzet, lesz még több hamu. Csodás.'::text),
(331779,36865,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, er hat mir gesagt, dass diese Holzscheite bis morgen zu Asche ...'::text,'geworden sind'::text,'werden'::text,'gerade werden'::text,'Hör mal, er hat mir gesagt, dass diese Holzscheite bis morgen zu Asche geworden sind.'::text),
(331783,36865,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, він сказав мені, що до завтра ці поліна ... на попіл.'::text,'перетворяться'::text,'перетворяться'::text,'перетворюватимуться'::text,'Слухай, він сказав мені, що до завтра ці поліна перетворяться на попіл.'::text),
(331782,36865,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, él me dijo que para mañana esos troncos se ... en ceniza.'::text,'habrán convertido'::text,'convertirán'::text,'estarán convirtiendo'::text,'Oye, él me dijo que para mañana esos troncos se habrán convertido en ceniza.'::text),
(331781,36865,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il m''a dit que d''ici demain ces bûches ... en cendres.'::text,'se seront transformées'::text,'se transformeront'::text,'seront en train de se transformer'::text,'Écoute, il m''a dit que d''ici demain ces bûches se seront transformées en cendres.'::text),
(331784,36865,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, o bana yarına kadar o kütüklerin küle ... söyledi.'::text,'dönmüş olacağını'::text,'döneceğini'::text,'dönüyor olacağını'::text,'Dinle, o bana yarına kadar o kütüklerin küle dönmüş olacağını söyledi.'::text),
(331785,36865,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, ő azt mondta nekem, hogy holnapra azok a fahasábok hamuvá ...'::text,'válnak'::text,'válnak'::text,'fognak éppen válni'::text,'Figyelj, ő azt mondta nekem, hogy holnapra azok a fahasábok hamuvá válnak.'::text),
(392871,43653,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Mauer ... früher viel weiter, bevor Teile davon einstürzten.'::text,'reichte'::text,'reichte'::text,'war gewohnt zu reichen'::text,'Die Mauer reichte früher viel weiter, bevor Teile davon einstürzten.'::text),
(392875,43653,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Колись мур ... значно далі, перш ніж частини його обвалилися.'::text,'простягався'::text,'простягався'::text,'звик простягатися'::text,'Колись мур простягався значно далі, перш ніж частини його обвалилися.'::text),
(392874,43653,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La muralla ... extenderse mucho más lejos antes de que partes de ella se derrumbaran.'::text,'solía'::text,'solía'::text,'estaba acostumbrada a'::text,'La muralla solía extenderse mucho más lejos antes de que partes de ella se derrumbaran.'::text),
(392873,43653,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La muraille ... beaucoup plus loin avant que certaines parties s''effondrent.'::text,'s''étendait autrefois'::text,'s''étendait autrefois'::text,'avait l''habitude de s''étendre'::text,'La muraille s''étendait autrefois beaucoup plus loin avant que certaines parties s''effondrent.'::text),
(392876,43653,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sur, bazı kısımları çökmeden önce eskiden çok daha uzağa ...'::text,'uzanırdı'::text,'uzanırdı'::text,'uzanmaya alışkındı'::text,'Sur, bazı kısımları çökmeden önce eskiden çok daha uzağa uzanırdı.'::text),
(392877,43653,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fal régen sokkal messzebbre ..., mielőtt egyes részei leomlottak.'::text,'nyúlt'::text,'nyúlt'::text,'volt szokva nyúlni'::text,'A fal régen sokkal messzebbre nyúlt, mielőtt egyes részei leomlottak.'::text),
(348015,38669,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis sie die Kamera erreicht, ... die Türme in der Ferne im Nebel.'::text,'verschwinden'::text,'verschwinden'::text,'verschwinden'::text,'Bis sie die Kamera erreicht, verschwinden die Türme in der Ferne im Nebel.'::text),
(348019,38669,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки вона дійде до камери, вежі вдалині ... в тумані.'::text,'зникнуть'::text,'зникнуть'::text,'зникають'::text,'Поки вона дійде до камери, вежі вдалині зникнуть в тумані.'::text),
(348018,38669,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando ella llegue a la cámara, las torres a lo lejos ... en la niebla.'::text,'habrán desaparecido'::text,'desaparecerán'::text,'desaparecen'::text,'Para cuando ella llegue a la cámara, las torres a lo lejos habrán desaparecido en la niebla.'::text),
(348017,38669,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici à ce qu''elle atteigne la caméra, les tours au loin ... dans la brume.'::text,'auront disparu'::text,'disparaîtront'::text,'disparaissent'::text,'D''ici à ce qu''elle atteigne la caméra, les tours au loin auront disparu dans la brume.'::text),
(348020,38669,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O kameraya ulaştığında uzaktaki kuleler sisin içinde ...'::text,'kaybolmuş olacak'::text,'kaybolacak'::text,'kayboluyor'::text,'O kameraya ulaştığında uzaktaki kuleler sisin içinde kaybolmuş olacak.'::text),
(348021,38669,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire ő a kamerához ér, a távoli tornyok ... a ködben.'::text,'eltűnnek'::text,'el fognak tűnni'::text,'eltűnnek'::text,'Mire ő a kamerához ér, a távoli tornyok eltűnnek a ködben.'::text),
(355314,39480,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oma hat an einem Nachmittag Dutzende Dumplings gefaltet, ...? Absolut unglaublich!'::text,'oder'::text,'oder'::text,'oder'::text,'Oma hat an einem Nachmittag Dutzende Dumplings gefaltet, oder? Absolut unglaublich!'::text),
(355318,39480,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бабуся за одне пообіддя зліпила десятки дамплінгів, ...? Абсолютно неймовірно!'::text,'правда'::text,'правда'::text,'правда'::text,'Бабуся за одне пообіддя зліпила десятки дамплінгів, правда? Абсолютно неймовірно!'::text),
(355317,39480,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La abuela dobló decenas de dumplings en una sola tarde, ¿...? ¡Absolutamente increíble!'::text,'verdad'::text,'verdad'::text,'verdad'::text,'La abuela dobló decenas de dumplings en una sola tarde, ¿verdad? ¡Absolutamente increíble!'::text),
(355316,39480,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mamie a plié des dizaines de dumplings en un seul après-midi, ... ? Absolument incroyable !'::text,'n''est-ce pas'::text,'n''est-ce pas'::text,'n''est-ce pas'::text,'Mamie a plié des dizaines de dumplings en un seul après-midi, n''est-ce pas ? Absolument incroyable !'::text),
