(340482,37832,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Regale sind ausgeräumt, und ...'::text,'der Boden auch.'::text,'der Boden ist es auch.'::text,'der Boden auch.'::text,'Die Regale sind ausgeräumt, und der Boden auch.'::text),
(340486,37832,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Полиці розчищені, і ...'::text,'підлога теж.'::text,'підлога теж є.'::text,'підлога теж.'::text,'Полиці розчищені, і підлога теж.'::text),
(340485,37832,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las estanterías están despejadas, y ...'::text,'el suelo también.'::text,'el suelo también lo está.'::text,'el suelo también.'::text,'Las estanterías están despejadas, y el suelo también.'::text),
(340484,37832,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les étagères ont été vidées, et ...'::text,'le sol aussi.'::text,'le sol l''est aussi.'::text,'le sol aussi.'::text,'Les étagères ont été vidées, et le sol aussi.'::text),
(340487,37832,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Raflar boşaltıldı ve ...'::text,'zemin de.'::text,'zemin de öyle.'::text,'zemin de.'::text,'Raflar boşaltıldı ve zemin de.'::text),
(340488,37832,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A polcokat kipakolták, és ...'::text,'a padlót is.'::text,'a padló is az.'::text,'a padlót is.'::text,'A polcokat kipakolták, és a padlót is.'::text),
(340536,37838,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hat die ganze Wohnung ausgeräumt, ... es sie fast zerstört hat!'::text,'obwohl'::text,'falls'::text,'wegen'::text,'Sie hat die ganze Wohnung ausgeräumt, obwohl es sie fast zerstört hat!'::text),
(340540,37838,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона розчистила всю квартиру, ... це її мало не знищило!'::text,'хоча'::text,'на випадок, якщо'::text,'через те, що'::text,'Вона розчистила всю квартиру, хоча це її мало не знищило!'::text),
(340539,37838,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ella despejó todo el piso ... casi acabó con ella!'::text,'aunque'::text,'por si'::text,'debido a que'::text,'¡Ella despejó todo el piso aunque casi acabó con ella!'::text),
(340538,37838,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a vidé tout l''appart ... ça a failli la détruire !'::text,'même si'::text,'au cas où'::text,'à cause du fait que'::text,'Elle a vidé tout l''appart même si ça a failli la détruire !'::text),
(340541,37838,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O bütün daireyi boşalttı, ... bu neredeyse onu mahvetti!'::text,'gerçi'::text,'olur da'::text,'yüzünden'::text,'O bütün daireyi boşalttı, gerçi bu neredeyse onu mahvetti!'::text),
(340542,37838,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő kipakolta az egész lakást, ... ez majdnem tönkretette!'::text,'pedig'::text,'arra az esetre, ha'::text,'amiatt, hogy'::text,'Ő kipakolta az egész lakást, pedig ez majdnem tönkretette!'::text),
(380424,42270,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... sie wieder auf dem Sofa, ohne Witz, Bro.'::text,'chillt'::text,'chillt'::text,'chillt'::text,'Morgen um diese Zeit chillt sie wieder auf dem Sofa, ohne Witz, Bro.'::text),
(380428,42270,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час вона знову ... на тому дивані, без жартів, бро.'::text,'відпочиватиме'::text,'відпочиває'::text,'відпочиває'::text,'Завтра в цей час вона знову відпочиватиме на тому дивані, без жартів, бро.'::text),
(380427,42270,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora ella ... en ese sofá otra vez, sin mentir, bro.'::text,'estará descansando'::text,'está descansando'::text,'descansa'::text,'Mañana a esta hora ella estará descansando en ese sofá otra vez, sin mentir, bro.'::text),
(380426,42270,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à la même heure, elle ... encore sur ce canapé, sans mentir, frère.'::text,'se reposera'::text,'se repose'::text,'se repose'::text,'Demain à la même heure, elle se reposera encore sur ce canapé, sans mentir, frère.'::text),
(380429,42270,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatte o yine o kanepede ..., yalan yok kanka.'::text,'dinleniyor olacak'::text,'dinleniyor'::text,'dinlenir'::text,'Yarın bu saatte o yine o kanepede dinleniyor olacak, yalan yok kanka.'::text),
(380430,42270,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor ő megint ... azon a kanapén, nem kamu, tesó.'::text,'pihenni fog'::text,'pihen'::text,'pihen'::text,'Holnap ilyenkor ő megint pihenni fog azon a kanapén, nem kamu, tesó.'::text),
(380514,42280,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, sie ... stundenlang geputzt, also war die Pause auf dem Sofa schon irgendwie verdient.'::text,'hatte'::text,'hat'::text,'putzt'::text,'Bro, sie hatte stundenlang geputzt, also war die Pause auf dem Sofa schon irgendwie verdient.'::text),
(380518,42280,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона ... годинами, тож той відпочинок на дивані був цілком заслужений.'::text,'прибирала'::text,'прибирає'::text,'прибирає'::text,'Бро, вона прибирала годинами, тож той відпочинок на дивані був цілком заслужений.'::text),
(380517,42280,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ella ... durante horas, así que ese descanso en el sofá fue bastante merecido.'::text,'había estado limpiando'::text,'ha estado limpiando'::text,'está limpiando'::text,'Bro, ella había estado limpiando durante horas, así que ese descanso en el sofá fue bastante merecido.'::text),
(380516,42280,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, elle ... pendant des heures, donc cette pause sur le canapé était un peu méritée.'::text,'avait fait le ménage'::text,'a fait le ménage'::text,'fait le ménage'::text,'Frère, elle avait fait le ménage pendant des heures, donc cette pause sur le canapé était un peu méritée.'::text),
(380519,42280,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o saatlerce ..., yani kanepedeki o mola baya hak edilmişti.'::text,'temizlik yapmıştı'::text,'temizlik yapıyor'::text,'temizlik yapıyor'::text,'Kanka, o saatlerce temizlik yapmıştı, yani kanepedeki o mola baya hak edilmişti.'::text),
(380520,42280,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ő órák óta ..., szóval az a kanapés pihenő elég megérdemelt volt.'::text,'takarított'::text,'takarít'::text,'takarít'::text,'Tesó, ő órák óta takarított, szóval az a kanapés pihenő elég megérdemelt volt.'::text),
(350706,38968,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Frau bessere Ausrüstung hätte, ... sie die Arbeitsplatte viel schneller.'::text,'putzte'::text,'putzt'::text,'putzt'::text,'Wenn die Frau bessere Ausrüstung hätte, putzte sie die Arbeitsplatte viel schneller.'::text),
(350710,38968,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби жінка мала краще обладнання, вона ... стільницю набагато швидше.'::text,'почистила б'::text,'почистить'::text,'чистить'::text,'Якби жінка мала краще обладнання, вона почистила б стільницю набагато швидше.'::text),
(350709,38968,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la mujer tuviera un mejor equipo, ella ... la encimera mucho más rápido.'::text,'limpiaría'::text,'limpiará'::text,'limpia'::text,'Si la mujer tuviera un mejor equipo, ella limpiaría la encimera mucho más rápido.'::text),
(350708,38968,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la femme avait un meilleur équipement, elle ... le plan de travail beaucoup plus vite.'::text,'nettoierait'::text,'nettoiera'::text,'nettoie'::text,'Si la femme avait un meilleur équipement, elle nettoierait le plan de travail beaucoup plus vite.'::text),
(350711,38968,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kadının daha iyi ekipmanı olsaydı, o tezgâhı çok daha hızlı ...'::text,'temizlerdi'::text,'temizleyecek'::text,'temizliyor'::text,'Kadının daha iyi ekipmanı olsaydı, o tezgâhı çok daha hızlı temizlerdi.'::text),
(350712,38968,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a nőnek jobb felszerelése lenne, ő sokkal gyorsabban ... a munkalapot.'::text,'megtisztítaná'::text,'meg fogja tisztítani'::text,'megtisztítja'::text,'Ha a nőnek jobb felszerelése lenne, ő sokkal gyorsabban megtisztítaná a munkalapot.'::text),
(350751,38973,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'..., die dieser Fensterputzer benutzt, besteht aus einem Gurt, einem Helm und einem Abzieher.'::text,'Die Ausrüstung'::text,'Eine Ausrüstung'::text,'Die Ausrüstungen'::text,'Die Ausrüstung, die dieser Fensterputzer benutzt, besteht aus einem Gurt, einem Helm und einem Abzieher.'::text),
(350755,38973,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'..., яке використовує цей мийник вікон, складається з запобіжного пояса, каски та скребка.'::text,'Спорядження'::text,'Спорядження'::text,'Спорядження'::text,'Спорядження, яке використовує цей мийник вікон, складається з запобіжного пояса, каски та скребка.'::text),
(350754,38973,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... que usa este limpiacristales consiste en un arnés, un casco y una rasqueta.'::text,'El equipo'::text,'Un equipo'::text,'Los equipos'::text,'El equipo que usa este limpiacristales consiste en un arnés, un casco y una rasqueta.'::text),
(350753,38973,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... qu''utilise ce laveur de vitres se compose d''un harnais, d''un casque et d''une raclette.'::text,'L''équipement'::text,'Un équipement'::text,'Les équipements'::text,'L''équipement qu''utilise ce laveur de vitres se compose d''un harnais, d''un casque et d''une raclette.'::text),
(350756,38973,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu cam temizleyicinin kullandığı ... bir emniyet kemeri, bir baret ve bir silecekten oluşuyor.'::text,'ekipman'::text,'bir ekipman'::text,'ekipmanlar'::text,'Bu cam temizleyicinin kullandığı ekipman bir emniyet kemeri, bir baret ve bir silecekten oluşuyor.'::text),
(350757,38973,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'..., amelyet ez az ablaktisztító használ, egy hevederből, egy védősisakból és egy lehúzóból áll.'::text,'A felszerelés'::text,'Egy felszerelés'::text,'A felszerelések'::text,'A felszerelés, amelyet ez az ablaktisztító használ, egy hevederből, egy védősisakból és egy lehúzóból áll.'::text),
(353181,39243,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er spülte gerade den Lappen aus, als er noch mehr Haare auf dem dreckigen Spiegel ...'::text,'bemerkte'::text,'bemerkte gerade'::text,'hat bemerkt'::text,'Er spülte gerade den Lappen aus, als er noch mehr Haare auf dem dreckigen Spiegel bemerkte.'::text),
(353185,39243,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він полоскав ганчірку, коли ... ще більше волосся на брудному дзеркалі.'::text,'помітив'::text,'помічав'::text,'помітив'::text,'Він полоскав ганчірку, коли помітив ще більше волосся на брудному дзеркалі.'::text),
(353184,39243,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él estaba enjuagando el trapo cuando ... más pelos en el espejo asqueroso.'::text,'vio'::text,'estaba viendo'::text,'ha visto'::text,'Él estaba enjuagando el trapo cuando vio más pelos en el espejo asqueroso.'::text),
(353183,39243,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il rinçait le chiffon quand il ... encore des cheveux sur le miroir crasseux.'::text,'a remarqué'::text,'remarquait'::text,'a remarqué'::text,'Il rinçait le chiffon quand il a remarqué encore des cheveux sur le miroir crasseux.'::text),
(353186,39243,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O bezi durularken pis aynada daha fazla saç ...'::text,'fark etti'::text,'fark ediyordu'::text,'fark etmiş'::text,'O bezi durularken pis aynada daha fazla saç fark etti.'::text),
(353187,39243,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő éppen öblítette a rongyot, amikor ... még több hajszálat a koszos tükrön.'::text,'észrevett'::text,'vett észre éppen'::text,'észrevett'::text,'Ő éppen öblítette a rongyot, amikor észrevett még több hajszálat a koszos tükrön.'::text),
(353253,39251,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... diesen dreckigen Spiegel zehn Minuten lang geputzt, bevor er endlich glänzte. Respekt.'::text,'hattest'::text,'hast'::text,'putzt'::text,'Du hattest diesen dreckigen Spiegel zehn Minuten lang geputzt, bevor er endlich glänzte. Respekt.'::text),
(353257,39251,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... те брудне дзеркало десять хвилин, поки воно нарешті не засяяло. Респект.'::text,'тер'::text,'тер'::text,'треш'::text,'Ти тер те брудне дзеркало десять хвилин, поки воно нарешті не засяяло. Респект.'::text),
(353256,39251,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tú ... ese espejo asqueroso durante diez minutos antes de que por fin brillara. Respeto.'::text,'habías estado limpiando'::text,'has estado limpiando'::text,'estás limpiando'::text,'Tú habías estado limpiando ese espejo asqueroso durante diez minutos antes de que por fin brillara. Respeto.'::text),
(353255,39251,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... ce miroir crasseux pendant dix minutes avant qu''il brille enfin. Respect.'::text,'avais frotté'::text,'as frotté'::text,'frottes'::text,'Tu avais frotté ce miroir crasseux pendant dix minutes avant qu''il brille enfin. Respect.'::text),
(353258,39251,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sen o pis aynayı on dakika boyunca ..., sonunda parladı. Saygılar.'::text,'silmiştin'::text,'siliyorsun'::text,'siliyorsun'::text,'Sen o pis aynayı on dakika boyunca silmiştin, sonunda parladı. Saygılar.'::text),
(353259,39251,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te tíz percig ... azt a koszos tükröt, mire végre csillogott. Respekt.'::text,'törölgetted'::text,'törölgeted'::text,'törölgeted'::text,'Te tíz percig törölgetted azt a koszos tükröt, mire végre csillogott. Respekt.'::text),
(329358,36596,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn beide Seiten per Handschlag eine Vereinbarung treffen, ... sie sie, ihre Versprechen zu halten.'::text,'verpflichtet'::text,'verpflichtete'::text,'verpflichtete'::text,'Wenn beide Seiten per Handschlag eine Vereinbarung treffen, verpflichtet sie sie, ihre Versprechen zu halten.'::text),
(329362,36596,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо обидві сторони тиснуть руки на знак угоди, вона ... їх дотримуватися обіцянок.'::text,'зобов''язує'::text,'зобов''язувала'::text,'зобов''язувала б'::text,'Якщо обидві сторони тиснуть руки на знак угоди, вона зобов''язує їх дотримуватися обіцянок.'::text),
(329361,36596,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si ambas partes se dan la mano en un acuerdo, este les ... cumplir sus promesas.'::text,'exige'::text,'exigía'::text,'exigiría'::text,'Si ambas partes se dan la mano en un acuerdo, este les exige cumplir sus promesas.'::text),
(329360,36596,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si les deux parties se serrent la main sur un accord, celui-ci les ... à tenir leurs promesses.'::text,'oblige'::text,'obligeait'::text,'obligerait'::text,'Si les deux parties se serrent la main sur un accord, celui-ci les oblige à tenir leurs promesses.'::text),
(329363,36596,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İki taraf bir anlaşma için el sıkışırsa, anlaşma onların sözlerini tutmasını ...'::text,'gerektirir'::text,'gerektirdi'::text,'gerektirirdi'::text,'İki taraf bir anlaşma için el sıkışırsa, anlaşma onların sözlerini tutmasını gerektirir.'::text),
(329364,36596,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha mindkét fél kezet ráz egy megállapodásra, az ... őket, hogy betartsák az ígéreteiket.'::text,'kötelezi'::text,'kötelezte'::text,'kötelezné'::text,'Ha mindkét fél kezet ráz egy megállapodásra, az kötelezi őket, hogy betartsák az ígéreteiket.'::text),
(381387,42377,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Kletterer nimmt das Risiko in Kauf, auf halber Höhe der Klippe ...'::text,'abzustürzen'::text,'abstürzend'::text,'abstürzen'::text,'Der Kletterer nimmt das Risiko in Kauf, auf halber Höhe der Klippe abzustürzen.'::text),
(381391,42377,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Скелелаз приймає ризик ... посеред скелі.'::text,'падіння'::text,'впасти'::text,'впасти'::text,'Скелелаз приймає ризик падіння посеред скелі.'::text),
(381390,42377,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El escalador acepta el riesgo de ... a mitad del acantilado.'::text,'caerse'::text,'caerse'::text,'caer'::text,'El escalador acepta el riesgo de caerse a mitad del acantilado.'::text),
(381389,42377,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le grimpeur accepte le risque de ... à mi-hauteur de la falaise.'::text,'tomber'::text,'tomber'::text,'tomber'::text,'Le grimpeur accepte le risque de tomber à mi-hauteur de la falaise.'::text),
(381392,42377,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tırmanıcı uçurumun ortasında ... riskini kabul ediyor.'::text,'düşme'::text,'düşmek'::text,'düş'::text,'Tırmanıcı uçurumun ortasında düşme riskini kabul ediyor.'::text),
(381393,42377,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A mászó vállalja a ... kockázatát a szikla felénél.'::text,'zuhanás'::text,'zuhanni'::text,'zuhan'::text,'A mászó vállalja a zuhanás kockázatát a szikla felénél.'::text),
(394464,43830,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Junge ist seit zehn Minuten in der Praxis, ...'::text,'oder?'::text,'oder?'::text,'oder?'::text,'Der Junge ist seit zehn Minuten in der Praxis, oder?'::text),
(394468,43830,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хлопець уже десять хвилин у кабінеті лікаря, ...'::text,'правда?'::text,'правда?'::text,'правда?'::text,'Хлопець уже десять хвилин у кабінеті лікаря, правда?'::text),
(394467,43830,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El chico lleva diez minutos en la consulta, ...'::text,'¿verdad?'::text,'¿verdad?'::text,'¿verdad?'::text,'El chico lleva diez minutos en la consulta, ¿verdad?'::text),
(394466,43830,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le garçon est dans le cabinet depuis dix minutes, ...'::text,'n''est-ce pas ?'::text,'n''est-ce pas ?'::text,'n''est-ce pas ?'::text,'Le garçon est dans le cabinet depuis dix minutes, n''est-ce pas ?'::text),
(394469,43830,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çocuk on dakikadır muayenehanede, ...'::text,'değil mi?'::text,'değil mi?'::text,'değil mi?'::text,'Çocuk on dakikadır muayenehanede, değil mi?'::text),
(394470,43830,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fiú már tíz perce bent van a rendelőben, ...'::text,'ugye?'::text,'ugye?'::text,'ugye?'::text,'A fiú már tíz perce bent van a rendelőben, ugye?'::text),
(401448,44606,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn du in einem Wartezimmer sitzt, ... du, weil das Zimmer genau dafür da ist.'::text,'wartest'::text,'hast gewartet'::text,'wirst warten'::text,'Wenn du in einem Wartezimmer sitzt, wartest du, weil das Zimmer genau dafür da ist.'::text),
(401452,44606,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо ти сидиш у залі очікування, ти ..., бо саме для цього ця кімната.'::text,'чекаєш'::text,'чекав'::text,'чекатимеш'::text,'Якщо ти сидиш у залі очікування, ти чекаєш, бо саме для цього ця кімната.'::text),
(401451,44606,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si tú te sientas en una sala de espera, ..., porque para eso es la sala.'::text,'esperas'::text,'esperaste'::text,'esperarás'::text,'Si tú te sientas en una sala de espera, esperas, porque para eso es la sala.'::text),
(401450,44606,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si tu t''assois dans une salle d''attente, tu ..., parce que c''est à ça que sert la salle.'::text,'attends'::text,'attendais'::text,'attendras'::text,'Si tu t''assois dans une salle d''attente, tu attends, parce que c''est à ça que sert la salle.'::text),
(401453,44606,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sen bir bekleme odasında oturursan ..., çünkü oda bunun için var.'::text,'beklersin'::text,'bekledin'::text,'bekleyeceksin'::text,'Sen bir bekleme odasında oturursan beklersin, çünkü oda bunun için var.'::text),
(401454,44606,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha te egy váróteremben ülsz, akkor ..., mert arra való a terem.'::text,'vársz'::text,'vártál'::text,'várni fogsz'::text,'Ha te egy váróteremben ülsz, akkor vársz, mert arra való a terem.'::text),
(401511,44613,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Junge wünscht sich, das Wartezimmer ... einen Fernseher statt alter Zeitschriften.'::text,'hätte'::text,'hat'::text,'wird haben'::text,'Der Junge wünscht sich, das Wartezimmer hätte einen Fernseher statt alter Zeitschriften.'::text),
(401515,44613,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хлопець хотів би, щоб у залі очікування ... телевізор замість старих журналів.'::text,'був'::text,'є'::text,'буде'::text,'Хлопець хотів би, щоб у залі очікування був телевізор замість старих журналів.'::text),
(401514,44613,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El chico desearía que la sala de espera ... una tele en vez de revistas viejas.'::text,'tuviera'::text,'tiene'::text,'tendrá'::text,'El chico desearía que la sala de espera tuviera una tele en vez de revistas viejas.'::text),
(401513,44613,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le garçon aimerait que la salle d''attente ... une télé au lieu de vieux magazines.'::text,'ait'::text,'a'::text,'aura'::text,'Le garçon aimerait que la salle d''attente ait une télé au lieu de vieux magazines.'::text),
(401516,44613,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çocuk, bekleme odasında eski dergiler yerine bir televizyon ... istiyor.'::text,'olmasını'::text,'var'::text,'olacak'::text,'Çocuk, bekleme odasında eski dergiler yerine bir televizyon olmasını istiyor.'::text),
(401517,44613,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fiú azt szeretné, ha a váróteremben ... tévé a régi magazinok helyett.'::text,'lenne'::text,'van'::text,'lesz'::text,'A fiú azt szeretné, ha a váróteremben lenne tévé a régi magazinok helyett.'::text),
(356844,39650,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die schwarzen Brocken, ... von der Schaufel fallen, sind Brennstoff für einen Ofen.'::text,'die'::text,'die'::text,'deren'::text,'Die schwarzen Brocken, die von der Schaufel fallen, sind Brennstoff für einen Ofen.'::text),
(356848,39650,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чорні грудки, ... падають із лопати, — це паливо для печі.'::text,'які'::text,'хто'::text,'чиї'::text,'Чорні грудки, які падають із лопати, — це паливо для печі.'::text),
(356847,39650,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los trozos negros ... caen de la pala son combustible para una estufa.'::text,'que'::text,'quienes'::text,'cuyos'::text,'Los trozos negros que caen de la pala son combustible para una estufa.'::text),
(356846,39650,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les morceaux noirs ... tombent de la pelle sont du combustible pour un poêle.'::text,'qui'::text,'qui'::text,'dont'::text,'Les morceaux noirs qui tombent de la pelle sont du combustible pour un poêle.'::text),
(356849,39650,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kürekten düşen ... siyah parçalar bir soba için yakıt.'::text,''::text,NULL::text,NULL::text,'Kürekten düşen siyah parçalar bir soba için yakıt.'::text),
(356850,39650,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fekete darabok, ... leesnek a lapátról, egy kályha tüzelőjét adják.'::text,'amelyek'::text,'akik'::text,'amelyeknek a'::text,'A fekete darabok, amelyek leesnek a lapátról, egy kályha tüzelőjét adják.'::text),
(353982,39332,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann ... gerade die Hotdogs um, als eine Flammenwand vom Grill hochschoss.'::text,'drehte'::text,'drehte'::text,'drehte'::text,'Der Mann drehte gerade die Hotdogs um, als eine Flammenwand vom Grill hochschoss.'::text),
(353986,39332,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік ... хот-доги, коли з гриля вирвалася стіна полум''я.'::text,'перевертав'::text,'перевернув'::text,'перевернув'::text,'Чоловік перевертав хот-доги, коли з гриля вирвалася стіна полум''я.'::text),
(353985,39332,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre ... los perritos calientes cuando un muro de llamas saltó de la parrilla.'::text,'estaba girando'::text,'giró'::text,'ha girado'::text,'El hombre estaba girando los perritos calientes cuando un muro de llamas saltó de la parrilla.'::text),
(353984,39332,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme ... les hot-dogs quand un mur de flammes a jailli du gril.'::text,'retournait'::text,'a retourné'::text,'a retourné'::text,'L''homme retournait les hot-dogs quand un mur de flammes a jailli du gril.'::text),
(353987,39332,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Izgaradan bir alev duvarı fışkırdığında adam sosisli sandviçleri ...'::text,'çeviriyordu'::text,'çevirdi'::text,'çevirmiş'::text,'Izgaradan bir alev duvarı fışkırdığında adam sosisli sandviçleri çeviriyordu.'::text),
(353988,39332,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi éppen ... a hot dogokat, amikor egy lángfal csapott fel a grillből.'::text,'forgatta'::text,'megforgatta'::text,'megforgatta'::text,'A férfi éppen forgatta a hot dogokat, amikor egy lángfal csapott fel a grillből.'::text),
(354054,39340,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Flamme stieg fast sofort auf ..., was typischerweise passiert, wenn sich Fett entzündet.'::text,'Hüfthöhe'::text,'die Hüfthöhe'::text,'eine Hüfthöhe'::text,'Die Flamme stieg fast sofort auf Hüfthöhe, was typischerweise passiert, wenn sich Fett entzündet.'::text),
(354058,39340,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Полум''я майже миттєво піднялося до ..., що зазвичай стається, коли займається жир.'::text,'рівня пояса'::text,'рівня пояса'::text,'рівня пояса'::text,'Полум''я майже миттєво піднялося до рівня пояса, що зазвичай стається, коли займається жир.'::text),
(354057,39340,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La llama subió hasta ... casi al instante, lo que suele ocurrir cuando la grasa se inflama.'::text,'la altura de la cintura'::text,'la altura de la cintura'::text,'una altura de la cintura'::text,'La llama subió hasta la altura de la cintura casi al instante, lo que suele ocurrir cuando la grasa se inflama.'::text),
(354056,39340,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La flamme est montée à ... presque instantanément, ce qui arrive généralement quand la graisse s''enflamme.'::text,'hauteur de taille'::text,'la hauteur de taille'::text,'une hauteur de taille'::text,'La flamme est montée à hauteur de taille presque instantanément, ce qui arrive généralement quand la graisse s''enflamme.'::text),
(354059,39340,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alev neredeyse anında ... hizasına çıktı; bu genellikle yağ tutuştuğunda olur.'::text,'bel'::text,'bel'::text,'bir bel'::text,'Alev neredeyse anında bel hizasına çıktı; bu genellikle yağ tutuştuğunda olur.'::text),
(354060,39340,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A láng szinte azonnal ... magasságba csapott, ami jellemzően akkor történik, amikor a zsír meggyullad.'::text,'derék'::text,'a derék'::text,'egy derék'::text,'A láng szinte azonnal derék magasságba csapott, ami jellemzően akkor történik, amikor a zsír meggyullad.'::text),
(374520,41614,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Warte, du ... früher Höhen, und jetzt fährst du wie ein Profi über die Kiefern? Respekt.'::text,'hasstest'::text,'hasstest'::text,'warst gewohnt zu hassen'::text,'Warte, du hasstest früher Höhen, und jetzt fährst du wie ein Profi über die Kiefern? Respekt.'::text),
(374524,41614,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Стривай, ти ... висоту, а тепер катаєшся над соснами як профі? Респект.'::text,'колись ненавидів'::text,'колись ненавидів'::text,'звик ненавидіти'::text,'Стривай, ти колись ненавидів висоту, а тепер катаєшся над соснами як профі? Респект.'::text),
(374523,41614,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Espera, ¿tú ... odiar las alturas y ahora pasas por encima de los pinos como un pro? Respeto.'::text,'solías'::text,'solías'::text,'estabas acostumbrado a'::text,'Espera, ¿tú solías odiar las alturas y ahora pasas por encima de los pinos como un pro? Respeto.'::text),
(374522,41614,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Attends, avant tu ... le vide, et maintenant tu passes au-dessus des pins comme un pro ? Respect.'::text,'détestais'::text,'détestais'::text,'avais l''habitude de détester'::text,'Attends, avant tu détestais le vide, et maintenant tu passes au-dessus des pins comme un pro ? Respect.'::text),
(374525,41614,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dur bir dakika, sen eskiden yükseklikten ... ve şimdi çamların üstünden profesyonel gibi mi geçiyorsun? Saygılar.'::text,'nefret ederdin'::text,'nefret ederdin'::text,'nefret etmeye alışkındın'::text,'Dur bir dakika, sen eskiden yükseklikten nefret ederdin ve şimdi çamların üstünden profesyonel gibi mi geçiyorsun? Saygılar.'::text),
(374526,41614,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Várj, te régen ... a magasságot, most meg profi módjára suhansz a fenyők fölött? Respekt.'::text,'utáltad'::text,'utáltad'::text,'hozzá voltál szokva utálni'::text,'Várj, te régen utáltad a magasságot, most meg profi módjára suhansz a fenyők fölött? Respekt.'::text),
(376230,41804,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, sie hat seine Grafik echt gelobt, und ...'::text,'das ganze Team auch.'::text,'das ganze Team war es auch.'::text,'das ganze Team auch nicht.'::text,'Bro, sie hat seine Grafik echt gelobt, und das ganze Team auch.'::text),
(376234,41804,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона реально похвалила його графік, і ...'::text,'уся команда теж.'::text,'уся команда теж була.'::text,'уся команда теж ні.'::text,'Бро, вона реально похвалила його графік, і уся команда теж.'::text),
(376233,41804,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ella elogió su gráfico en serio, y ...'::text,'todo el equipo también.'::text,'todo el equipo también lo estaba.'::text,'todo el equipo tampoco.'::text,'Bro, ella elogió su gráfico en serio, y todo el equipo también.'::text),
(376232,41804,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, elle a vraiment complimenté son graphique, et ...'::text,'toute l''équipe aussi.'::text,'toute l''équipe l''était aussi.'::text,'toute l''équipe non plus.'::text,'Frère, elle a vraiment complimenté son graphique, et toute l''équipe aussi.'::text),
(376235,41804,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o cidden onun grafiğini övdü ve ...'::text,'bütün ekip de.'::text,'bütün ekip de öyleydi.'::text,'bütün ekip de övmedi.'::text,'Kanka, o cidden onun grafiğini övdü ve bütün ekip de.'::text),
(376236,41804,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ő tényleg megdicsérte a grafikonját, és ...'::text,'az egész csapat is.'::text,'az egész csapat is az volt.'::text,'az egész csapat sem.'::text,'Tesó, ő tényleg megdicsérte a grafikonját, és az egész csapat is.'::text),
(376257,41807,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Am Ende des Tages ... die Kollegen diese Grafik seit ungefähr acht Stunden.'::text,'loben'::text,'loben'::text,'lobten'::text,'Am Ende des Tages loben die Kollegen diese Grafik seit ungefähr acht Stunden.'::text),
(376261,41807,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До кінця дня колеги ... цей графік приблизно вісім годин.'::text,'хвалитимуть'::text,'хвалитимуть'::text,'похвалять'::text,'До кінця дня колеги хвалитимуть цей графік приблизно вісім годин.'::text),
(376260,41807,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el final del día, los colegas ... este gráfico durante aproximadamente ocho horas.'::text,'llevarán elogiando'::text,'estarán elogiando'::text,'habrán elogiado'::text,'Para el final del día, los colegas llevarán elogiando este gráfico durante aproximadamente ocho horas.'::text),
(376259,41807,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici la fin de la journée, cela fera environ huit heures que les collègues ... ce graphique.'::text,'complimentent'::text,'complimentent'::text,'auront complimenté'::text,'D''ici la fin de la journée, cela fera environ huit heures que les collègues complimentent ce graphique.'::text),
(376262,41807,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gün sonuna kadar meslektaşlar bu grafiği yaklaşık sekiz saat boyunca ...'::text,'övüyor olacak'::text,'övüyor olacak'::text,'övmüş olacak'::text,'Gün sonuna kadar meslektaşlar bu grafiği yaklaşık sekiz saat boyunca övüyor olacak.'::text),
(376263,41807,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nap végére a kollégák nagyjából nyolc órája ... ezt a grafikont.'::text,'dicsérik'::text,'dicsérik'::text,'meg fogják dicsérni'::text,'A nap végére a kollégák nagyjából nyolc órája dicsérik ezt a grafikont.'::text),
(364053,40451,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... gerade beim Tee die Tagesordnung für den Abend durch, als ein 30-Kilo-Hund seinen Schoß übernahm.'::text,'ging'::text,'ging'::text,'ging'::text,'Er ging gerade beim Tee die Tagesordnung für den Abend durch, als ein 30-Kilo-Hund seinen Schoß übernahm.'::text),
(364057,40451,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він за чаєм ... план на вечір, коли 30-кілограмовий пес захопив його коліна.'::text,'переглядав'::text,'переглянув'::text,'переглянув'::text,'Він за чаєм переглядав план на вечір, коли 30-кілограмовий пес захопив його коліна.'::text),
(364056,40451,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... la agenda de la tarde con un té cuando un perro de 30 kilos se apoderó de su regazo.'::text,'estaba revisando'::text,'revisó'::text,'ha revisado'::text,'Él estaba revisando la agenda de la tarde con un té cuando un perro de 30 kilos se apoderó de su regazo.'::text),
(364055,40451,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... le programme de la soirée autour d''un thé quand un chien de 30 kilos a pris possession de ses genoux.'::text,'passait en revue'::text,'a passé en revue'::text,'a passé en revue'::text,'Il passait en revue le programme de la soirée autour d''un thé quand un chien de 30 kilos a pris possession de ses genoux.'::text),
(364058,40451,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'30 kiloluk bir köpek kucağını ele geçirdiğinde o çay eşliğinde akşamın gündemini ...'::text,'gözden geçiriyordu'::text,'gözden geçirdi'::text,'gözden geçirmiş'::text,'30 kiloluk bir köpek kucağını ele geçirdiğinde o çay eşliğinde akşamın gündemini gözden geçiriyordu.'::text),
(364059,40451,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő éppen ... az esti napirendet tea mellett, amikor egy 30 kilós kutya elfoglalta az ölét.'::text,'nézte át'::text,'átnézte'::text,'átnézte'::text,'Ő éppen nézte át az esti napirendet tea mellett, amikor egy 30 kilós kutya elfoglalta az ölét.'::text),
(364089,40455,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der alte Mann, ... Schoß komplett unter einem riesigen Hund begraben ist, kann sich nie wieder bewegen!'::text,'dessen'::text,'der'::text,'welcher'::text,'Der alte Mann, dessen Schoß komplett unter einem riesigen Hund begraben ist, kann sich nie wieder bewegen!'::text),
(364093,40455,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Старий, ... коліна повністю завалені величезним псом, більше ніколи не зможе поворухнутися!'::text,'чиї'::text,'який'::text,'що'::text,'Старий, чиї коліна повністю завалені величезним псом, більше ніколи не зможе поворухнутися!'::text),
(364092,40455,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El anciano, ... regazo está completamente sepultado bajo un perro enorme, no podrá volver a moverse jamás!'::text,'cuyo'::text,'que'::text,'el cual'::text,'¡El anciano, cuyo regazo está completamente sepultado bajo un perro enorme, no podrá volver a moverse jamás!'::text),
(364091,40455,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le vieil homme, ... les genoux sont complètement ensevelis sous un énorme chien, ne pourra plus jamais bouger !'::text,'dont'::text,'qui'::text,'lequel'::text,'Le vieil homme, dont les genoux sont complètement ensevelis sous un énorme chien, ne pourra plus jamais bouger !'::text),
(364094,40455,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kucağı kocaman bir köpeğin altında tamamen gömülmüş ... yaşlı adam bir daha asla kıpırdayamayacak!'::text,''::text,NULL::text,NULL::text,'Kucağı kocaman bir köpeğin altında tamamen gömülmüş yaşlı adam bir daha asla kıpırdayamayacak!'::text),
(364095,40455,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az idős férfi, ... ölét teljesen maga alá temeti egy hatalmas kutya, soha többé nem tud megmozdulni!'::text,'akinek az'::text,'aki'::text,'ami'::text,'Az idős férfi, akinek az ölét teljesen maga alá temeti egy hatalmas kutya, soha többé nem tud megmozdulni!'::text),
(394275,43809,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Freunde ... ihm nach seinen schlechten Nachrichten viel Halt.'::text,'gaben'::text,'wurden gegeben'::text,'gebend'::text,'Die Freunde gaben ihm nach seinen schlechten Nachrichten viel Halt.'::text),
(394279,43809,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Друзі ... йому багато підтримки після поганих новин.'::text,'дали'::text,'отримали'::text,'даючи'::text,'Друзі дали йому багато підтримки після поганих новин.'::text),
(394278,43809,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los amigos le ... mucho apoyo después de sus malas noticias.'::text,'dieron'::text,'fueron dados'::text,'dando'::text,'Los amigos le dieron mucho apoyo después de sus malas noticias.'::text),
(394277,43809,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ses amis lui ... beaucoup de soutien après sa mauvaise nouvelle.'::text,'ont apporté'::text,'ont été apportés'::text,'apportant'::text,'Ses amis lui ont apporté beaucoup de soutien après sa mauvaise nouvelle.'::text),
(394280,43809,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arkadaşları kötü haberden sonra ona çok destek ...'::text,'verdi'::text,'verildi'::text,'vererek'::text,'Arkadaşları kötü haberden sonra ona çok destek verdi.'::text),
(394281,43809,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A barátai ... neki sok támogatást a rossz hír után.'::text,'adtak'::text,'kaptak'::text,'adva'::text,'A barátai adtak neki sok támogatást a rossz hír után.'::text),
(394293,43811,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Um Mitternacht ... seine Freunde ihm schon seit fünf Stunden Halt.'::text,'geben'::text,'geben'::text,'geben'::text,'Um Mitternacht geben seine Freunde ihm schon seit fünf Stunden Halt.'::text),
(394297,43811,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Опівночі його друзі ... йому підтримку вже п''ять годин.'::text,'даватимуть'::text,'дадуть'::text,'дають'::text,'Опівночі його друзі даватимуть йому підтримку вже п''ять годин.'::text),
(394296,43811,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A medianoche, sus amigos ... apoyo durante cinco horas.'::text,'le habrán estado dando'::text,'le darán'::text,'le están dando'::text,'A medianoche, sus amigos le habrán estado dando apoyo durante cinco horas.'::text),
(394295,43811,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'À minuit, cela fera cinq heures que ses amis lui ... du soutien.'::text,'apportent'::text,'apporteront'::text,'apportent'::text,'À minuit, cela fera cinq heures que ses amis lui apportent du soutien.'::text),
(394298,43811,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gece yarısına kadar arkadaşları ona beş saattir destek ...'::text,'veriyor olacak'::text,'verecek'::text,'veriyor'::text,'Gece yarısına kadar arkadaşları ona beş saattir destek veriyor olacak.'::text),
(394299,43811,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Éjfélre a barátai már öt órája ... neki támogatást.'::text,'nyújtanak'::text,'nyújtani fognak'::text,'nyújtanak'::text,'Éjfélre a barátai már öt órája nyújtanak neki támogatást.'::text),
(342120,38014,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Schlimmste Nacht aller Zeiten! Sie tröstete ihn auf dem Sofa, und ...'::text,'die anderen auch.'::text,'die anderen waren es auch.'::text,'die anderen auch.'::text,'Schlimmste Nacht aller Zeiten! Sie tröstete ihn auf dem Sofa, und die anderen auch.'::text),
(342124,38014,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Найгірша ніч у житті! Вона втішала його на дивані, і ...'::text,'інші теж.'::text,'інші теж були.'::text,'інші теж.'::text,'Найгірша ніч у житті! Вона втішала його на дивані, і інші теж.'::text),
(342123,38014,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La peor noche de la historia! Ella lo consoló en el sofá, y ...'::text,'los demás también.'::text,'los demás también lo estaban.'::text,'los demás también.'::text,'¡La peor noche de la historia! Ella lo consoló en el sofá, y los demás también.'::text),
(342122,38014,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pire nuit de tous les temps ! Elle l''a consolé sur le canapé, et ...'::text,'les autres aussi.'::text,'les autres l''étaient aussi.'::text,'les autres aussi.'::text,'Pire nuit de tous les temps ! Elle l''a consolé sur le canapé, et les autres aussi.'::text),
(342125,38014,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gelmiş geçmiş en kötü gece! O onu kanepede teselli etti ve ...'::text,'diğerleri de.'::text,'diğerleri de öyleydi.'::text,'diğerleri de.'::text,'Gelmiş geçmiş en kötü gece! O onu kanepede teselli etti ve diğerleri de.'::text),
(342126,38014,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden idők legrosszabb éjszakája! Ő vigasztalta a kanapén, és ...'::text,'a többiek is.'::text,'a többiek is azok voltak.'::text,'a többiek is.'::text,'Minden idők legrosszabb éjszakája! Ő vigasztalta a kanapén, és a többiek is.'::text),
(342174,38020,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seine Freunde ... ihn früher trösten sollen; er hatte stundenlang allein geweint.'::text,'hätten'::text,'müssen'::text,'können nicht'::text,'Seine Freunde hätten ihn früher trösten sollen; er hatte stundenlang allein geweint.'::text),
(342178,38020,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Його друзі ... втішити його раніше; він годинами плакав сам.'::text,'мали'::text,'мусили'::text,'не могли'::text,'Його друзі мали втішити його раніше; він годинами плакав сам.'::text),
(342177,38020,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sus amigos ... consolado antes; él llevaba horas llorando solo.'::text,'deberían haberlo'::text,'debieron de haberlo'::text,'no pueden haberlo'::text,'Sus amigos deberían haberlo consolado antes; él llevaba horas llorando solo.'::text),
(342176,38020,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ses amis ... le consoler plus tôt ; il pleurait seul depuis des heures.'::text,'auraient dû'::text,'ont dû'::text,'n''ont pas pu'::text,'Ses amis auraient dû le consoler plus tôt ; il pleurait seul depuis des heures.'::text),
(342179,38020,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arkadaşları onu daha önce ...; o saatlerdir tek başına ağlıyordu.'::text,'teselli etmeliydi'::text,'teselli etmiş olmalı'::text,'teselli etmiş olamaz'::text,'Arkadaşları onu daha önce teselli etmeliydi; o saatlerdir tek başına ağlıyordu.'::text),
(342180,38020,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A barátainak ... korábban; ő órák óta egyedül sírt.'::text,'meg kellett volna vigasztalniuk'::text,'biztosan megvigasztalták'::text,'nem vigasztalhatták meg'::text,'A barátainak meg kellett volna vigasztalniuk korábban; ő órák óta egyedül sírt.'::text),
(344370,38264,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, ich hab gehört, die Crew fuhr gerade an den Weiden vorbei, als ein Ruderer die Faust in die Luft ...'::text,'reckte'::text,'reckte gerade'::text,'hat gereckt'::text,'Rate mal, ich hab gehört, die Crew fuhr gerade an den Weiden vorbei, als ein Ruderer die Faust in die Luft reckte.'::text),
(344374,38264,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви, я чула, що екіпаж якраз пропливав повз верби, коли один веслувальник ... кулак угору.'::text,'викинув'::text,'викидав'::text,'викинув'::text,'Уяви, я чула, що екіпаж якраз пропливав повз верби, коли один веслувальник викинув кулак угору.'::text),
(344373,38264,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina, yo oí que la tripulación pasaba junto a los sauces cuando un remero ... el puño.'::text,'levantó'::text,'estaba levantando'::text,'ha levantado'::text,'Adivina, yo oí que la tripulación pasaba junto a los sauces cuando un remero levantó el puño.'::text),
(344372,38264,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, j''ai entendu dire que l''équipage passait devant les saules quand un rameur ... le poing en l''air.'::text,'a levé'::text,'levait'::text,'a levé'::text,'Devine quoi, j''ai entendu dire que l''équipage passait devant les saules quand un rameur a levé le poing en l''air.'::text),
(344375,38264,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bil bakalım, ben duydum ki ekip söğütlerin yanından geçerken bir kürekçi yumruğunu havaya ...'::text,'kaldırmış'::text,'kaldırıyormuş'::text,'kaldırmış'::text,'Bil bakalım, ben duydum ki ekip söğütlerin yanından geçerken bir kürekçi yumruğunu havaya kaldırmış.'::text),
(344376,38264,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, én úgy hallottam, hogy a legénység épp a füzek mellett haladt el, amikor egy evezős a levegőbe ... az öklét.'::text,'emelte'::text,'emelte éppen'::text,'emelte'::text,'Képzeld, én úgy hallottam, hogy a legénység épp a füzek mellett haladt el, amikor egy evezős a levegőbe emelte az öklét.'::text),
(344406,38268,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Crew hielt ... des vorbeifahrenden Radfahrers auf dem Treidelpfad den perfekten Takt.'::text,'trotz'::text,'obwohl'::text,'wegen'::text,'Die Crew hielt trotz des vorbeifahrenden Radfahrers auf dem Treidelpfad den perfekten Takt.'::text),
(344410,38268,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Екіпаж тримав ідеальний ритм ... велосипедиста, що проїжджав стежкою вздовж річки.'::text,'попри'::text,'хоча'::text,'через'::text,'Екіпаж тримав ідеальний ритм попри велосипедиста, що проїжджав стежкою вздовж річки.'::text),
(344409,38268,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La tripulación mantuvo el ritmo perfecto ... ciclista que pasaba por el camino de sirga.'::text,'a pesar del'::text,'aunque el'::text,'debido al'::text,'La tripulación mantuvo el ritmo perfecto a pesar del ciclista que pasaba por el camino de sirga.'::text),
(344408,38268,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''équipage a gardé un rythme parfait ... le cycliste qui passait sur le chemin de halage.'::text,'malgré'::text,'bien que'::text,'à cause de'::text,'L''équipage a gardé un rythme parfait malgré le cycliste qui passait sur le chemin de halage.'::text),
(344411,38268,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ekip, çekme yolundan geçen bisikletliye ... mükemmel ritmini korudu.'::text,'rağmen'::text,'gerçi'::text,'yüzünden'::text,'Ekip, çekme yolundan geçen bisikletliye rağmen mükemmel ritmini korudu.'::text),
(344412,38268,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A legénység tökéletes ütemben evezett a vontatóúton elhaladó biciklis ...'::text,'ellenére'::text,'bár'::text,'miatt'::text,'A legénység tökéletes ütemben evezett a vontatóúton elhaladó biciklis ellenére.'::text),
(341130,37904,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn du noch so ein Kommando rufst, ... die Crew noch schneller, ehrlich.'::text,'rudert'::text,'ruderte'::text,'ruderte'::text,'Wenn du noch so ein Kommando rufst, rudert die Crew noch schneller, ehrlich.'::text),
(341134,37904,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо ти крикнеш ще одну таку команду, екіпаж ... ще швидше, чесно.'::text,'веслуватиме'::text,'веслував би'::text,'веслував'::text,'Якщо ти крикнеш ще одну таку команду, екіпаж веслуватиме ще швидше, чесно.'::text),
(341133,37904,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si tú gritas una orden más así, la tripulación ... todavía más rápido, en serio.'::text,'remará'::text,'remaría'::text,'remó'::text,'Si tú gritas una orden más así, la tripulación remará todavía más rápido, en serio.'::text),
(341132,37904,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si tu cries encore un ordre comme ça, l''équipage ... encore plus vite, honnêtement.'::text,'ramera'::text,'ramerait'::text,'a ramé'::text,'Si tu cries encore un ordre comme ça, l''équipage ramera encore plus vite, honnêtement.'::text),
(341135,37904,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sen böyle bir komut daha bağırırsan, ekip daha da hızlı ..., cidden.'::text,'kürek çekecek'::text,'kürek çekerdi'::text,'kürek çekti'::text,'Sen böyle bir komut daha bağırırsan, ekip daha da hızlı kürek çekecek, cidden.'::text),
(341136,37904,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha te még egy ilyen vezényszót kiáltasz, a legénység még gyorsabban ..., komolyan.'::text,'fog evezni'::text,'evezne'::text,'evezett'::text,'Ha te még egy ilyen vezényszót kiáltasz, a legénység még gyorsabban fog evezni, komolyan.'::text),
(341211,37913,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, angeblich ... sie seit 2019 die Kommandos auf diesem Boot.'::text,'gibt'::text,'gibt'::text,'gibt'::text,'Hör mal, angeblich gibt sie seit 2019 die Kommandos auf diesem Boot.'::text),
(341215,37913,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, вона ... команди на цьому човні з 2019 року.'::text,'віддає'::text,'віддає'::text,'віддає'::text,'Слухай, кажуть, вона віддає команди на цьому човні з 2019 року.'::text),
(341214,37913,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, dicen que ella ... las órdenes en este barco desde 2019.'::text,'lleva dando'::text,'está dando'::text,'da'::text,'Oye, dicen que ella lleva dando las órdenes en este barco desde 2019.'::text),
(341213,37913,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il paraît qu''elle ... les ordres sur ce bateau depuis 2019.'::text,'donne'::text,'donne'::text,'donne'::text,'Écoute, il paraît qu''elle donne les ordres sur ce bateau depuis 2019.'::text),
(341216,37913,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, dediklerine göre o 2019''dan beri bu teknede komutları ...'::text,'veriyor'::text,'veriyor'::text,'verir'::text,'Dinle, dediklerine göre o 2019''dan beri bu teknede komutları veriyor.'::text),
(341217,37913,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt beszélik, hogy ő 2019 óta ... a vezényszavakat ezen a hajón.'::text,'adja'::text,'adja'::text,'adja'::text,'Figyelj, azt beszélik, hogy ő 2019 óta adja a vezényszavakat ezen a hajón.'::text),
(364494,40500,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn das Gesetzbuch nicht so schwer wäre, ... sie es mit einer Hand.'::text,'trüge'::text,'trägt'::text,'trug'::text,'Wenn das Gesetzbuch nicht so schwer wäre, trüge sie es mit einer Hand.'::text),
(364498,40500,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби книга законів не була такою важкою, вона ... її однією рукою.'::text,'несла б'::text,'понесе'::text,'несла'::text,'Якби книга законів не була такою важкою, вона несла б її однією рукою.'::text),
(364497,40500,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el libro de leyes no pesara tanto, ella lo ... con una mano.'::text,'llevaría'::text,'llevará'::text,'llevó'::text,'Si el libro de leyes no pesara tanto, ella lo llevaría con una mano.'::text),
(364496,40500,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le livre de lois n''était pas si lourd, elle le ... d''une seule main.'::text,'porterait'::text,'portera'::text,'a porté'::text,'Si le livre de lois n''était pas si lourd, elle le porterait d''une seule main.'::text),
(364499,40500,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanun kitabı bu kadar ağır olmasaydı, o onu tek elle ...'::text,'taşırdı'::text,'taşıyacak'::text,'taşıdı'::text,'Kanun kitabı bu kadar ağır olmasaydı, o onu tek elle taşırdı.'::text),
(364500,40500,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a törvénykönyv nem lenne ilyen nehéz, ő egy kézzel ...'::text,'vinné'::text,'fogja vinni'::text,'vitte'::text,'Ha a törvénykönyv nem lenne ilyen nehéz, ő egy kézzel vinné.'::text),
(342696,38078,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hätten die Dorfbewohner nicht so viel Zusammenarbeit gezeigt, ... das Gerüst jetzt noch im Gras.'::text,'läge'::text,'hätte gelegen'::text,'wird liegen'::text,'Hätten die Dorfbewohner nicht so viel Zusammenarbeit gezeigt, läge das Gerüst jetzt noch im Gras.'::text),
(342700,38078,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби селяни не показали такої співпраці, каркас ... досі на траві.'::text,'лежав би'::text,'лежав би'::text,'лежатиме'::text,'Якби селяни не показали такої співпраці, каркас лежав би досі на траві.'::text),
(342699,38078,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si los aldeanos no hubieran mostrado tanta cooperación, la estructura ... todavía en la hierba ahora.'::text,'estaría'::text,'habría estado'::text,'estará'::text,'Si los aldeanos no hubieran mostrado tanta cooperación, la estructura estaría todavía en la hierba ahora.'::text),
(342698,38078,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si les villageois n''avaient pas fait preuve d''une telle coopération, la charpente ... encore dans l''herbe maintenant.'::text,'serait'::text,'aurait été'::text,'sera'::text,'Si les villageois n''avaient pas fait preuve d''une telle coopération, la charpente serait encore dans l''herbe maintenant.'::text),
(342701,38078,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köylüler böyle bir iş birliği göstermeseydi, çatı iskeleti şu an hâlâ çimlerin üstünde ...'::text,'olurdu'::text,'olmuş olurdu'::text,'olacak'::text,'Köylüler böyle bir iş birliği göstermeseydi, çatı iskeleti şu an hâlâ çimlerin üstünde olurdu.'::text),
(342702,38078,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a falusiak nem mutattak volna ilyen együttműködést, a tetőszerkezet most is a füvön ...'::text,'feküdne'::text,'feküdt volna'::text,'fog feküdni'::text,'Ha a falusiak nem mutattak volna ilyen együttműködést, a tetőszerkezet most is a füvön feküdne.'::text),
(393942,43772,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hat bei Sonnenaufgang den Gipfel erreicht, und ...'::text,'ihre Freundin auch.'::text,'ihre Freundin war es auch.'::text,'ihre Freundin auch.'::text,'Sie hat bei Sonnenaufgang den Gipfel erreicht, und ihre Freundin auch.'::text),
(393946,43772,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона досягла вершини на світанку, і ...'::text,'її подруга теж.'::text,'її подруга теж була.'::text,'її подруга теж.'::text,'Вона досягла вершини на світанку, і її подруга теж.'::text),
(393945,43772,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella llegó a la cumbre al amanecer, y ...'::text,'su amiga también.'::text,'su amiga también estaba.'::text,'su amiga también.'::text,'Ella llegó a la cumbre al amanecer, y su amiga también.'::text),
(393944,43772,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a atteint le sommet au lever du soleil, et ...'::text,'son amie aussi.'::text,'son amie l''était aussi.'::text,'son amie aussi.'::text,'Elle a atteint le sommet au lever du soleil, et son amie aussi.'::text),
(393947,43772,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O zirveye gün doğarken ulaştı ve ...'::text,'arkadaşı da.'::text,'arkadaşı da öyleydi.'::text,'arkadaşı da.'::text,'O zirveye gün doğarken ulaştı ve arkadaşı da.'::text),
(393948,43772,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő napkeltekor ért fel a csúcsra, és ...'::text,'a barátnője is.'::text,'a barátnője is az volt.'::text,'a barátnője is.'::text,'Ő napkeltekor ért fel a csúcsra, és a barátnője is.'::text),
(342957,38107,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... du wieder Klausuren. Dein Einsatz ist ikonisch.'::text,'korrigierst'::text,'korrigierst'::text,'korrigierst'::text,'Morgen um diese Zeit korrigierst du wieder Klausuren. Dein Einsatz ist ikonisch.'::text),
(342961,38107,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час ти знову ... контрольні. Твоя відданість — культова.'::text,'перевірятимеш'::text,'перевіриш'::text,'перевіряєш'::text,'Завтра в цей час ти знову перевірятимеш контрольні. Твоя відданість — культова.'::text),
(342960,38107,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora tú ... exámenes otra vez. Tu dedicación es icónica.'::text,'estarás corrigiendo'::text,'corregirás'::text,'estás corrigiendo'::text,'Mañana a esta hora tú estarás corrigiendo exámenes otra vez. Tu dedicación es icónica.'::text),
(342959,38107,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à la même heure, tu ... encore des copies. Ton dévouement est iconique.'::text,'seras en train de corriger'::text,'corrigeras'::text,'es en train de corriger'::text,'Demain à la même heure, tu seras en train de corriger encore des copies. Ton dévouement est iconique.'::text),
(342962,38107,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatte sen yine sınav kâğıtlarını ...! Bu adanmışlığın efsane.'::text,'okuyor olacaksın'::text,'okuyacaksın'::text,'okuyorsun'::text,'Yarın bu saatte sen yine sınav kâğıtlarını okuyor olacaksın! Bu adanmışlığın efsane.'::text),
(342963,38107,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor te megint ... a dolgozatokat. Az elhivatottságod ikonikus.'::text,'javítani fogod'::text,'kijavítod'::text,'javítod'::text,'Holnap ilyenkor te megint javítani fogod a dolgozatokat. Az elhivatottságod ikonikus.'::text),
(343002,38112,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Mitternacht hat sie jede Klausur im Hörsaal ...'::text,'korrigiert'::text,'korrigiert'::text,'korrigieren'::text,'Bis Mitternacht hat sie jede Klausur im Hörsaal korrigiert.'::text),
(343006,38112,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До півночі вона ... кожну роботу в аудиторії.'::text,'перевірить'::text,'перевірить'::text,'перевірятиме'::text,'До півночі вона перевірить кожну роботу в аудиторії.'::text),
(343005,38112,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para medianoche, ella ... todos los exámenes del aula magna.'::text,'habrá corregido'::text,'corregirá'::text,'estará corrigiendo'::text,'Para medianoche, ella habrá corregido todos los exámenes del aula magna.'::text),
(343004,38112,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici minuit, elle ... toutes les copies de l''amphithéâtre.'::text,'aura corrigé'::text,'corrigera'::text,'sera en train de corriger'::text,'D''ici minuit, elle aura corrigé toutes les copies de l''amphithéâtre.'::text),
(343007,38112,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gece yarısına kadar o amfideki her kâğıdı ...'::text,'okumuş olacak'::text,'okuyacak'::text,'okuyor olacak'::text,'Gece yarısına kadar o amfideki her kâğıdı okumuş olacak.'::text),
(343008,38112,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Éjfélre ő ... az előadóterem összes dolgozatát.'::text,'kijavítja'::text,'ki fogja javítani'::text,'javítani fogja'::text,'Éjfélre ő kijavítja az előadóterem összes dolgozatát.'::text),
(384600,42734,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nächste Woche um diese Zeit ... sie in derselben Nische wieder einen geheimen Deal.'::text,'machen'::text,'machten'::text,'machen'::text,'Nächste Woche um diese Zeit machen sie in derselben Nische wieder einen geheimen Deal.'::text),
(384604,42734,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Наступного тижня в цей час вони ... ще одну таємну угоду в тій самій кабінці.'::text,'укладатимуть'::text,'уклали'::text,'укладають'::text,'Наступного тижня в цей час вони укладатимуть ще одну таємну угоду в тій самій кабінці.'::text),
(384603,42734,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La semana que viene a esta hora, ellos ... otro trato secreto en el mismo reservado.'::text,'estarán cerrando'::text,'cerraron'::text,'cierran'::text,'La semana que viene a esta hora, ellos estarán cerrando otro trato secreto en el mismo reservado.'::text),
(384602,42734,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La semaine prochaine à la même heure, ils ... un autre accord secret dans le même box.'::text,'seront en train de conclure'::text,'ont conclu'::text,'concluent'::text,'La semaine prochaine à la même heure, ils seront en train de conclure un autre accord secret dans le même box.'::text),
(384605,42734,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gelecek hafta bu saatte onlar aynı bölmede başka bir gizli anlaşma ...'::text,'yapıyor olacak'::text,'yaptı'::text,'yapıyor'::text,'Gelecek hafta bu saatte onlar aynı bölmede başka bir gizli anlaşma yapıyor olacak.'::text),
(384606,42734,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jövő héten ilyenkor ők ugyanabban a boxban ... egy újabb titkos üzletet.'::text,'fognak éppen kötni'::text,'kötöttek'::text,'kötnek'::text,'Jövő héten ilyenkor ők ugyanabban a boxban fognak éppen kötni egy újabb titkos üzletet.'::text),
(384645,42739,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... das Geld jahrelang geheim gehalten, bevor diese Tischdecke alles ruiniert hat!'::text,'hatten'::text,'haben'::text,'halten'::text,'Sie hatten das Geld jahrelang geheim gehalten, bevor diese Tischdecke alles ruiniert hat!'::text),
(384649,42739,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ... ці гроші в таємниці роками, поки та скатертина все не зіпсувала!'::text,'тримали'::text,'тримають'::text,'тримають'::text,'Вони тримали ці гроші в таємниці роками, поки та скатертина все не зіпсувала!'::text),
(384648,42739,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ellos ... el dinero en secreto durante años antes de que ese mantel lo arruinara todo!'::text,'habían mantenido'::text,'han mantenido'::text,'mantienen'::text,'¡Ellos habían mantenido el dinero en secreto durante años antes de que ese mantel lo arruinara todo!'::text),
(384647,42739,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ... l''argent secret pendant des années avant que cette nappe gâche tout !'::text,'avaient gardé'::text,'ont gardé'::text,'gardent'::text,'Ils avaient gardé l''argent secret pendant des années avant que cette nappe gâche tout !'::text),
(384650,42739,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O masa örtüsü her şeyi mahvedene kadar onlar parayı yıllarca gizli ...!'::text,'tutmuşlardı'::text,'tuttular'::text,'tutuyorlar'::text,'O masa örtüsü her şeyi mahvedene kadar onlar parayı yıllarca gizli tutmuşlardı!'::text),
(384651,42739,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ők évekig titokban ... a pénzt, mielőtt az az abrosz mindent tönkretett!'::text,'tartották'::text,'tartották'::text,'tartják'::text,'Ők évekig titokban tartották a pénzt, mielőtt az az abrosz mindent tönkretett!'::text),
(344469,38275,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Bauer warnte den Wanderer, nicht durch das grüne Getreide unterhalb des Hügels ...'::text,'zu laufen'::text,'laufend'::text,'lief'::text,'Der Bauer warnte den Wanderer, nicht durch das grüne Getreide unterhalb des Hügels zu laufen.'::text),
(344473,38275,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Фермер попередив туриста не ... через зелений посів під пагорбом.'::text,'ходити'::text,'ходіння'::text,'ходив'::text,'Фермер попередив туриста не ходити через зелений посів під пагорбом.'::text),
(344472,38275,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El granjero advirtió al excursionista que no ... por el cultivo verde bajo la colina.'::text,'caminara'::text,'caminando'::text,'caminó'::text,'El granjero advirtió al excursionista que no caminara por el cultivo verde bajo la colina.'::text),
(344471,38275,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le fermier a averti le randonneur de ne pas ... dans la culture verte au pied de la colline.'::text,'marcher'::text,'marchant'::text,'marché'::text,'Le fermier a averti le randonneur de ne pas marcher dans la culture verte au pied de la colline.'::text),
(344474,38275,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çiftçi yürüyüşçüyü tepenin altındaki yeşil ekinin içinden ... konusunda uyardı.'::text,'yürümemesi'::text,'yürümeyerek'::text,'yürümedi'::text,'Çiftçi yürüyüşçüyü tepenin altındaki yeşil ekinin içinden yürümemesi konusunda uyardı.'::text),
(344475,38275,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gazda figyelmeztette a túrázót, hogy ne ... át a domb alatti zöld vetésen.'::text,'menjen'::text,'menve'::text,'ment'::text,'A gazda figyelmeztette a túrázót, hogy ne menjen át a domb alatti zöld vetésen.'::text),
(345747,38417,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... dieses Date im Voraus geplant haben, denn der Herzballon wartete schon.'::text,'müssen'::text,'können nicht'::text,'sollten'::text,'Sie müssen dieses Date im Voraus geplant haben, denn der Herzballon wartete schon.'::text),
(345751,38417,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ... це побачення заздалегідь, бо кулька-серце вже чекала.'::text,'мабуть, спланували'::text,'не могли спланувати'::text,'мали б спланувати'::text,'Вони мабуть, спланували це побачення заздалегідь, бо кулька-серце вже чекала.'::text),
(345750,38417,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ellos ... planeado esta cita con antelación, porque el globo de corazón ya estaba esperando.'::text,'debieron de haber'::text,'no pueden haber'::text,'deberían haber'::text,'Ellos debieron de haber planeado esta cita con antelación, porque el globo de corazón ya estaba esperando.'::text),
(345749,38417,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ... prévoir ce rendez-vous à l''avance, parce que le ballon en cœur attendait déjà.'::text,'ont dû'::text,'n''ont pas pu'::text,'auraient dû'::text,'Ils ont dû prévoir ce rendez-vous à l''avance, parce que le ballon en cœur attendait déjà.'::text),
(345752,38417,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onlar bu buluşmayı önceden ..., çünkü kalp balon zaten bekliyordu.'::text,'planlamış olmalı'::text,'planlamış olamaz'::text,'planlamalıydı'::text,'Onlar bu buluşmayı önceden planlamış olmalı, çünkü kalp balon zaten bekliyordu.'::text),
(345753,38417,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ők ... ezt a randit előre, mert a szív alakú lufi már várt.'::text,'biztosan megtervezték'::text,'nem tervezhették meg'::text,'meg kellett volna tervezniük'::text,'Ők biztosan megtervezték ezt a randit előre, mert a szív alakú lufi már várt.'::text),
(368256,40918,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn du ein großes Kind misst, ... das Kind groß, weil große Kinder groß sind.'::text,'ist'::text,'war'::text,'wäre'::text,'Wenn du ein großes Kind misst, ist das Kind groß, weil große Kinder groß sind.'::text),
(368260,40918,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо ти міряєш високу дитину, дитина ... високою, бо високі діти високі.'::text,'є'::text,'була'::text,'була б'::text,'Якщо ти міряєш високу дитину, дитина є високою, бо високі діти високі.'::text),
(368259,40918,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si tú mides a un niño alto, el niño ... alto, porque los niños altos son altos.'::text,'es'::text,'era'::text,'sería'::text,'Si tú mides a un niño alto, el niño es alto, porque los niños altos son altos.'::text),
(368258,40918,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si tu mesures un enfant grand, l''enfant ... grand, parce que les enfants grands sont grands.'::text,'est'::text,'était'::text,'serait'::text,'Si tu mesures un enfant grand, l''enfant est grand, parce que les enfants grands sont grands.'::text),
(368261,40918,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sen uzun boylu bir çocuğu ölçersen, çocuk uzun ..., çünkü uzun boylu çocuklar uzundur.'::text,''::text,'idi'::text,'olurdu'::text,'Sen uzun boylu bir çocuğu ölçersen, çocuk uzun, çünkü uzun boylu çocuklar uzundur.'::text),
(368262,40918,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha te megmérsz egy magas gyereket, a gyerek ... magas, mert a magas gyerekek magasak.'::text,''::text,'volt'::text,'lenne'::text,'Ha te megmérsz egy magas gyereket, a gyerek magas, mert a magas gyerekek magasak.'::text),
(368310,40924,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Mädchen bestand darauf, noch einmal ... zu werden. Eine sehr ruhige Konkurrentin, offensichtlich.'::text,'gemessen'::text,'gemessen'::text,'gemessen'::text,'Das Mädchen bestand darauf, noch einmal gemessen zu werden. Eine sehr ruhige Konkurrentin, offensichtlich.'::text),
(368314,40924,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дівчинка наполягла, щоб її ... ще раз. Дуже спокійна суперниця, очевидно.'::text,'поміряли'::text,'поміряли'::text,'поміряли'::text,'Дівчинка наполягла, щоб її поміряли ще раз. Дуже спокійна суперниця, очевидно.'::text),
(368313,40924,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La niña insistió en que la ... otra vez. Una rival muy tranquila, obviamente.'::text,'midieran'::text,'midieran'::text,'midieran'::text,'La niña insistió en que la midieran otra vez. Una rival muy tranquila, obviamente.'::text),
(368312,40924,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La fille a insisté pour ... à nouveau. Une concurrente très calme, évidemment.'::text,'être mesurée'::text,'être mesurée'::text,'être mesurée'::text,'La fille a insisté pour être mesurée à nouveau. Une concurrente très calme, évidemment.'::text),
(368315,40924,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kız yeniden ... konusunda ısrar etti. Çok sakin bir rakip, belli ki.'::text,'ölçülmek'::text,'ölçülmek'::text,'ölçül'::text,'Kız yeniden ölçülmek konusunda ısrar etti. Çok sakin bir rakip, belli ki.'::text),
(368316,40924,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A lány ragaszkodott ahhoz, hogy ... újra. Nagyon nyugodt versenyző, nyilván.'::text,'megmérjék'::text,'megmérjék'::text,'megmérjék'::text,'A lány ragaszkodott ahhoz, hogy megmérjék újra. Nagyon nyugodt versenyző, nyilván.'::text),
(337386,37488,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Trainer seine Wade dehnt, ... der Spieler bald wieder auf dem Platz.'::text,'ist'::text,'wäre'::text,'war'::text,'Wenn der Trainer seine Wade dehnt, ist der Spieler bald wieder auf dem Platz.'::text),
(337390,37488,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо тренер розтягне йому литку, гравець скоро ... знову на полі.'::text,'буде'::text,'був би'::text,'був'::text,'Якщо тренер розтягне йому литку, гравець скоро буде знову на полі.'::text),
(337389,37488,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el entrenador le estira la pantorrilla, el jugador ... de vuelta en el campo pronto.'::text,'estará'::text,'estaría'::text,'estaba'::text,'Si el entrenador le estira la pantorrilla, el jugador estará de vuelta en el campo pronto.'::text),
(337388,37488,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si l''entraîneur lui étire le mollet, le joueur ... bientôt de retour sur le terrain.'::text,'sera'::text,'serait'::text,'était'::text,'Si l''entraîneur lui étire le mollet, le joueur sera bientôt de retour sur le terrain.'::text),
(337391,37488,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antrenör baldırını esnetirse, oyuncu yakında sahaya geri ...'::text,'dönecek'::text,'dönerdi'::text,'döndü'::text,'Antrenör baldırını esnetirse, oyuncu yakında sahaya geri dönecek.'::text),
(337392,37488,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha az edző megnyújtja a vádliját, a játékos hamarosan ... a pályán.'::text,'újra ott lesz'::text,'újra ott lenne'::text,'újra ott volt'::text,'Ha az edző megnyújtja a vádliját, a játékos hamarosan újra ott lesz a pályán.'::text),
(337404,37490,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Spieler, ... Wade mitten im Sprint gestreikt hat, hat offensichtlich einen großartigen Abend.'::text,'dessen'::text,'der'::text,'welche'::text,'Der Spieler, dessen Wade mitten im Sprint gestreikt hat, hat offensichtlich einen großartigen Abend.'::text),
(337408,37490,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гравець, ... литка здалася посеред спринту, явно має чудовий вечір.'::text,'чия'::text,'який'::text,'яка'::text,'Гравець, чия литка здалася посеред спринту, явно має чудовий вечір.'::text),
(337407,37490,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El jugador, ... pantorrilla dijo basta en pleno sprint, está pasando claramente una noche genial.'::text,'cuya'::text,'que'::text,'la cual'::text,'El jugador, cuya pantorrilla dijo basta en pleno sprint, está pasando claramente una noche genial.'::text),
(337406,37490,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le joueur, ... le mollet a lâché en plein sprint, passe clairement une super soirée.'::text,'dont'::text,'qui'::text,'lequel'::text,'Le joueur, dont le mollet a lâché en plein sprint, passe clairement une super soirée.'::text),
(337409,37490,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Baldırı sprintin ortasında pes eden ... oyuncu belli ki harika bir gece geçiriyor.'::text,''::text,NULL::text,NULL::text,'Baldırı sprintin ortasında pes eden oyuncu belli ki harika bir gece geçiriyor.'::text),
(337410,37490,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A játékos, ... vádlija sprint közben felmondta a szolgálatot, nyilvánvalóan remek estét tölt.'::text,'akinek a'::text,'aki'::text,'ami'::text,'A játékos, akinek a vádlija sprint közben felmondta a szolgálatot, nyilvánvalóan remek estét tölt.'::text),
(397938,44216,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Welle noch näher kommt, ... sie ihre kleine Spur komplett!'::text,'zerstört'::text,'zerstörte'::text,'zerstörte'::text,'Wenn die Welle noch näher kommt, zerstört sie ihre kleine Spur komplett!'::text),
(397942,44216,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо ця хвиля підійде ще ближче, вона ... їхній маленький слід повністю!'::text,'знищить'::text,'знищила б'::text,'знищила'::text,'Якщо ця хвиля підійде ще ближче, вона знищить їхній маленький слід повністю!'::text),
(397941,44216,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si se acerca más, esa ola ... su pequeño rastro por completo!'::text,'destruirá'::text,'destruiría'::text,'destruyó'::text,'¡Si se acerca más, esa ola destruirá su pequeño rastro por completo!'::text),
(397940,44216,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si cette vague s''approche encore, elle ... complètement leur petite trace !'::text,'détruira'::text,'détruirait'::text,'a détruit'::text,'Si cette vague s''approche encore, elle détruira complètement leur petite trace !'::text),
(397943,44216,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Biraz daha yaklaşırsa, o dalga onların küçük izini tamamen ...!'::text,'yok edecek'::text,'yok ederdi'::text,'yok etti'::text,'Biraz daha yaklaşırsa, o dalga onların küçük izini tamamen yok edecek!'::text),
(397944,44216,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha még közelebb jön, az a hullám teljesen ... a kis nyomukat!'::text,'el fogja tüntetni'::text,'eltüntetné'::text,'eltüntette'::text,'Ha még közelebb jön, az a hullám teljesen el fogja tüntetni a kis nyomukat!'::text),
(344568,38286,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... einfach weiter, weil ein Überweg zum Überqueren da ist.'::text,'lief'::text,'zu laufen'::text,'laufen'::text,'Sie lief einfach weiter, weil ein Überweg zum Überqueren da ist.'::text),
(344572,38286,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона продовжувала ..., бо перехід для того, щоб переходити.'::text,'йти'::text,'йти'::text,'йти'::text,'Вона продовжувала йти, бо перехід для того, щоб переходити.'::text),
(344571,38286,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella siguió ..., porque un paso de peatones es para pasar.'::text,'caminando'::text,'a caminar'::text,'caminar'::text,'Ella siguió caminando, porque un paso de peatones es para pasar.'::text),
(344570,38286,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a continué à ..., parce qu''un passage, c''est fait pour passer.'::text,'marcher'::text,'marcher'::text,'marcher'::text,'Elle a continué à marcher, parce qu''un passage, c''est fait pour passer.'::text),
(344573,38286,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O ... devam etti, çünkü geçit geçmek içindir.'::text,'yürümeye'::text,'yürümek'::text,'yürü'::text,'O yürümeye devam etti, çünkü geçit geçmek içindir.'::text),
(344574,38286,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő tovább ..., mert az átkelő átkelésre való.'::text,'sétált'::text,'sétálni'::text,'sétál'::text,'Ő tovább sétált, mert az átkelő átkelésre való.'::text),
(344577,38287,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fußgänger ... den Überweg hier typischerweise nur, wenn die Ampel grün ist.'::text,'nutzen'::text,'nutzen gerade'::text,'haben genutzt'::text,'Fußgänger nutzen den Überweg hier typischerweise nur, wenn die Ampel grün ist.'::text),
(344581,38287,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Пішоходи тут зазвичай ... перехід лише тоді, коли горить зелений.'::text,'долають'::text,'долають'::text,'подолали'::text,'Пішоходи тут зазвичай долають перехід лише тоді, коли горить зелений.'::text),
(344580,38287,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los peatones normalmente ... el cruce aquí solo cuando el semáforo está en verde.'::text,'hacen'::text,'están haciendo'::text,'han hecho'::text,'Los peatones normalmente hacen el cruce aquí solo cuando el semáforo está en verde.'::text),
(344579,38287,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les piétons ... généralement la traversée ici uniquement quand le feu est vert.'::text,'effectuent'::text,'sont en train d''effectuer'::text,'ont effectué'::text,'Les piétons effectuent généralement la traversée ici uniquement quand le feu est vert.'::text),
(344582,38287,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yayalar burada karşıya geçişi tipik olarak yalnızca ışık yeşilken ...'::text,'yapar'::text,'yapıyor'::text,'yaptı'::text,'Yayalar burada karşıya geçişi tipik olarak yalnızca ışık yeşilken yapar.'::text),
(344583,38287,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gyalogosok itt jellemzően csak akkor ... az átkelést, amikor zöld a lámpa.'::text,'végzik el'::text,'végzik éppen'::text,'végezték el'::text,'A gyalogosok itt jellemzően csak akkor végzik el az átkelést, amikor zöld a lámpa.'::text),
(344613,38291,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... seit einer Stunde auf diesem Zebrastreifen hin und her. Offensichtlich ein sehr effizienter Einkaufsbummel.'::text,'läuft'::text,'läuft'::text,'läuft'::text,'Sie läuft seit einer Stunde auf diesem Zebrastreifen hin und her. Offensichtlich ein sehr effizienter Einkaufsbummel.'::text),
(344617,38291,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона вже годину ... туди-сюди цим пішохідним переходом. Явно дуже ефективний шопінг.'::text,'ходить'::text,'ходить'::text,'ходить'::text,'Вона вже годину ходить туди-сюди цим пішохідним переходом. Явно дуже ефективний шопінг.'::text),
(344616,38291,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... una hora arriba y abajo por este paso de cebra. Claramente, unas compras muy eficientes.'::text,'lleva caminando'::text,'está caminando'::text,'camina'::text,'Ella lleva caminando una hora arriba y abajo por este paso de cebra. Claramente, unas compras muy eficientes.'::text),
(344615,38291,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... sur ce passage piéton depuis une heure. Visiblement une virée shopping très efficace.'::text,'fait des allers-retours'::text,'fait des allers-retours'::text,'fait des allers-retours'::text,'Elle fait des allers-retours sur ce passage piéton depuis une heure. Visiblement une virée shopping très efficace.'::text),
(344618,38291,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, bu yaya geçidinde bir saattir bir aşağı bir yukarı ..., belli ki çok verimli bir alışveriş gezisi.'::text,'yürüyor'::text,'yürüyor'::text,'yürür'::text,'O, bu yaya geçidinde bir saattir bir aşağı bir yukarı yürüyor, belli ki çok verimli bir alışveriş gezisi.'::text),
(344619,38291,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő egy órája ... fel-alá ezen a zebrán. Nyilván nagyon hatékony bevásárlókörút.'::text,'sétál'::text,'sétál'::text,'sétál'::text,'Ő egy órája sétál fel-alá ezen a zebrán. Nyilván nagyon hatékony bevásárlókörút.'::text),
(373512,41502,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bemerkenswerterweise ... Fußgänger seit dem Ampelwechsel in alle Richtungen über die Kreuzung.'::text,'strömen'::text,'strömen'::text,'strömten'::text,'Bemerkenswerterweise strömen Fußgänger seit dem Ampelwechsel in alle Richtungen über die Kreuzung.'::text),
(373516,41502,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Примітно, що пішоходи ... через перехрестя в усіх напрямках, відколи змінилося світло.'::text,'сунуть'::text,'сунуть'::text,'сунули'::text,'Примітно, що пішоходи сунуть через перехрестя в усіх напрямках, відколи змінилося світло.'::text),
(373515,41502,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sorprendentemente, los peatones ... por el cruce en todas direcciones desde que cambió el semáforo.'::text,'llevan fluyendo'::text,'están fluyendo'::text,'fluyen'::text,'Sorprendentemente, los peatones llevan fluyendo por el cruce en todas direcciones desde que cambió el semáforo.'::text),
(373514,41502,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fait remarquable, les piétons ... à travers le carrefour dans toutes les directions depuis que le feu a changé.'::text,'affluent'::text,'affluent'::text,'affluent'::text,'Fait remarquable, les piétons affluent à travers le carrefour dans toutes les directions depuis que le feu a changé.'::text),
(373517,41502,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dikkat çekici biçimde, ışık değiştiğinden beri yayalar kavşaktan her yöne ...'::text,'akıyor'::text,'akıyor'::text,'akar'::text,'Dikkat çekici biçimde, ışık değiştiğinden beri yayalar kavşaktan her yöne akıyor.'::text),
(373518,41502,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelemre méltó módon a gyalogosok a lámpaváltás óta minden irányban ... át a kereszteződésen.'::text,'özönlenek'::text,'özönlenek'::text,'özönlöttek'::text,'Figyelemre méltó módon a gyalogosok a lámpaváltás óta minden irányban özönlenek át a kereszteződésen.'::text),
(373566,41508,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, angeblich ist die Fußgängerin, ... Anzug korallenrot war, vor allen anderen rübergegangen.'::text,'deren'::text,'die'::text,'welcher'::text,'Rate mal, angeblich ist die Fußgängerin, deren Anzug korallenrot war, vor allen anderen rübergegangen.'::text),
(373570,41508,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви, кажуть, пішохідка, ... костюм був кораловим, перейшла раніше за всіх.'::text,'чий'::text,'яка'::text,'який'::text,'Уяви, кажуть, пішохідка, чий костюм був кораловим, перейшла раніше за всіх.'::text),
(373569,41508,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina, al parecer la peatona, ... traje era coral, cruzó antes que nadie.'::text,'cuyo'::text,'que'::text,'el cual'::text,'Adivina, al parecer la peatona, cuyo traje era coral, cruzó antes que nadie.'::text),
(373568,41508,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, apparemment la piétonne, ... le tailleur était corail, a traversé avant tout le monde.'::text,'dont'::text,'qui'::text,'lequel'::text,'Devine quoi, apparemment la piétonne, dont le tailleur était corail, a traversé avant tout le monde.'::text),
(373571,41508,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bil bakalım, galiba takım elbisesi mercan rengi olan ... yaya herkesten önce karşıya geçmiş.'::text,''::text,NULL::text,NULL::text,'Bil bakalım, galiba takım elbisesi mercan rengi olan yaya herkesten önce karşıya geçmiş.'::text),
(373572,41508,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, állítólag a gyalogos nő, ... kosztümje korallszínű volt, mindenki más előtt átment.'::text,'akinek a'::text,'aki'::text,'ami'::text,'Képzeld, állítólag a gyalogos nő, akinek a kosztümje korallszínű volt, mindenki más előtt átment.'::text),
(355602,39512,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Früher ... die meisten Weingüter keine Maschinen, also machten Füße die Arbeit.'::text,'hatten'::text,'hatten'::text,'waren nicht gewohnt an'::text,'Früher hatten die meisten Weingüter keine Maschinen, also machten Füße die Arbeit.'::text),
(355606,39512,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Раніше більшість виноробень ... машин, тож роботу виконували ноги.'::text,'не мали'::text,'не мали'::text,'не звикли мати'::text,'Раніше більшість виноробень не мали машин, тож роботу виконували ноги.'::text),
(355605,39512,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes, la mayoría de las bodegas no ... máquinas, así que los pies hacían el trabajo.'::text,'solían tener'::text,'tenían'::text,'estaban acostumbradas a tener'::text,'Antes, la mayoría de las bodegas no solían tener máquinas, así que los pies hacían el trabajo.'::text),
(355604,39512,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Autrefois, la plupart des domaines viticoles ... de machines, donc c''étaient les pieds qui faisaient le travail.'::text,'n''avaient pas'::text,'n''avaient pas'::text,'n''étaient pas habitués à avoir'::text,'Autrefois, la plupart des domaines viticoles n''avaient pas de machines, donc c''étaient les pieds qui faisaient le travail.'::text),
(355607,39512,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eskiden şarap üreticilerinin çoğunun makinesi ..., bu yüzden işi ayaklar yapardı.'::text,'yoktu'::text,'olmazdı'::text,'olmaya alışkın değildi'::text,'Eskiden şarap üreticilerinin çoğunun makinesi yoktu, bu yüzden işi ayaklar yapardı.'::text),
(355608,39512,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Régen a legtöbb borászatnak nem ... gépe, ezért a lábak végezték a munkát.'::text,'volt'::text,'volt'::text,'volt megszokva, hogy legyen'::text,'Régen a legtöbb borászatnak nem volt gépe, ezért a lábak végezték a munkát.'::text),
(355620,39514,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, ich hab gehört, sie ... jeden September Trauben mit den Füßen.'::text,'stampfen'::text,'stampfen gerade'::text,'haben gestampft'::text,'Mädel, ich hab gehört, sie stampfen jeden September Trauben mit den Füßen.'::text),
(355624,39514,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, я чула, що вони щовересня ... виноград ногами.'::text,'чавлять'::text,'чавлять'::text,'почавили'::text,'Подруго, я чула, що вони щовересня чавлять виноград ногами.'::text),
(355623,39514,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, yo oí que ellos ... uvas con los pies cada septiembre.'::text,'pisan'::text,'están pisando'::text,'han pisado'::text,'Tía, yo oí que ellos pisan uvas con los pies cada septiembre.'::text),
(355622,39514,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, j''ai entendu dire qu''ils ... le raisin avec les pieds chaque septembre.'::text,'foulent'::text,'sont en train de fouler'::text,'ont foulé'::text,'Ma belle, j''ai entendu dire qu''ils foulent le raisin avec les pieds chaque septembre.'::text),
(355625,39514,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, ben duydum ki onlar her eylülde üzümleri ayaklarıyla ...'::text,'eziyormuş'::text,'eziyormuş'::text,'ezmiş'::text,'Kızım, ben duydum ki onlar her eylülde üzümleri ayaklarıyla eziyormuş.'::text),
(355626,39514,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, én úgy hallottam, hogy ők minden szeptemberben a lábukkal ... a szőlőt.'::text,'taposják'::text,'taposják éppen'::text,'taposták'::text,'Csajszi, én úgy hallottam, hogy ők minden szeptemberben a lábukkal taposják a szőlőt.'::text),
(345081,38343,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, er ... wegen eines traurigen Films weinen, keine Ahnung.'::text,'könnte'::text,'muss'::text,'kann nicht'::text,'Bro, er könnte wegen eines traurigen Films weinen, keine Ahnung.'::text),
(345085,38343,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, він ... плакати через сумний фільм, хз.'::text,'може'::text,'мусить'::text,'не може'::text,'Бро, він може плакати через сумний фільм, хз.'::text),
(345084,38343,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, él ... estar llorando por una peli triste, ni idea.'::text,'podría'::text,'debe de'::text,'no puede'::text,'Bro, él podría estar llorando por una peli triste, ni idea.'::text),
(345083,38343,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, il ... pleurer à cause d''un film triste, j''sais pas.'::text,'pourrait'::text,'doit'::text,'ne peut pas'::text,'Frère, il pourrait pleurer à cause d''un film triste, j''sais pas.'::text),
(345086,38343,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o hüzünlü bir film yüzünden ağlıyor ..., bilmiyorum.'::text,'olabilir'::text,'olmalı'::text,'olamaz'::text,'Kanka, o hüzünlü bir film yüzünden ağlıyor olabilir, bilmiyorum.'::text),
(345087,38343,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ő ... egy szomorú film miatt sír, nem tudom.'::text,'lehet, hogy'::text,'biztos'::text,'nem lehet, hogy'::text,'Tesó, ő lehet, hogy egy szomorú film miatt sír, nem tudom.'::text),
(345153,38351,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Mitternacht hat er mehr Tränen ... als eine ganze Telenovela!'::text,'vergossen'::text,'vergossen'::text,'vergießen'::text,'Bis Mitternacht hat er mehr Tränen vergossen als eine ganze Telenovela!'::text),
(345157,38351,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До півночі він ... більше сліз, ніж ціла теленовела!'::text,'виплаче'::text,'виплаче'::text,'плакатиме'::text,'До півночі він виплаче більше сліз, ніж ціла теленовела!'::text),
(345156,38351,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para medianoche, él ... más lágrimas que una telenovela entera!'::text,'habrá llorado'::text,'llorará'::text,'estará llorando'::text,'¡Para medianoche, él habrá llorado más lágrimas que una telenovela entera!'::text),
(345155,38351,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici minuit, il ... plus de larmes qu''une telenovela entière !'::text,'aura versé'::text,'versera'::text,'sera en train de verser'::text,'D''ici minuit, il aura versé plus de larmes qu''une telenovela entière !'::text),
(345158,38351,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gece yarısına kadar o koca bir telenovelladan daha fazla gözyaşı ...!'::text,'dökmüş olacak'::text,'dökecek'::text,'döküyor olacak'::text,'Gece yarısına kadar o koca bir telenovelladan daha fazla gözyaşı dökmüş olacak!'::text),
(345159,38351,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Éjfélre ő több könnyet ..., mint egy egész telenovella!'::text,'fog hullatni'::text,'fog hullatni'::text,'hullat'::text,'Éjfélre ő több könnyet fog hullatni, mint egy egész telenovella!'::text),
(361515,40169,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wäre der riesige Becher komplett gefüllt, ... sein Anheben erhebliche Anstrengung.'::text,'erforderte'::text,'erfordert'::text,'erforderte'::text,'Wäre der riesige Becher komplett gefüllt, erforderte sein Anheben erhebliche Anstrengung.'::text),
(361519,40169,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби величезний кухоль був повністю наповнений, його підняття ... значних зусиль.'::text,'вимагало б'::text,'вимагатиме'::text,'вимагало'::text,'Якби величезний кухоль був повністю наповнений, його підняття вимагало б значних зусиль.'::text),
(361518,40169,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la enorme taza estuviera llena del todo, levantarla ... un esfuerzo considerable.'::text,'requeriría'::text,'requerirá'::text,'requirió'::text,'Si la enorme taza estuviera llena del todo, levantarla requeriría un esfuerzo considerable.'::text),
(361517,40169,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si l''énorme mug était rempli à ras bord, le soulever ... un effort considérable.'::text,'demanderait'::text,'demandera'::text,'a demandé'::text,'Si l''énorme mug était rempli à ras bord, le soulever demanderait un effort considérable.'::text),
(361520,40169,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dev kupa tamamen dolu olsaydı, onu kaldırmak ciddi bir çaba ...'::text,'gerektirirdi'::text,'gerektirecek'::text,'gerektirdi'::text,'Dev kupa tamamen dolu olsaydı, onu kaldırmak ciddi bir çaba gerektirirdi.'::text),
(361521,40169,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha az óriási bögre teljesen tele lenne, a felemelése jelentős erőfeszítést ...'::text,'igényelne'::text,'fog igényelni'::text,'igényelt'::text,'Ha az óriási bögre teljesen tele lenne, a felemelése jelentős erőfeszítést igényelne.'::text),
(361524,40170,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du ... den riesigen Becher eine Minute lang gehalten, bevor du überhaupt einen Schluck genommen hast. Ikonisch.'::text,'hattest'::text,'hast'::text,'wurdest'::text,'Ehrlich, du hattest den riesigen Becher eine Minute lang gehalten, bevor du überhaupt einen Schluck genommen hast. Ikonisch.'::text),
(361528,40170,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти ... той величезний кухоль цілу хвилину, перш ніж хоч раз ковтнула. Культово.'::text,'тримала'::text,'тримаєш'::text,'була тримана'::text,'Чесно, ти тримала той величезний кухоль цілу хвилину, перш ніж хоч раз ковтнула. Культово.'::text),
(361527,40170,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, tú ... esa taza enorme durante un minuto antes de dar siquiera un sorbo. Icónico.'::text,'habías estado sujetando'::text,'has estado sujetando'::text,'fuiste sujetada'::text,'Sinceramente, tú habías estado sujetando esa taza enorme durante un minuto antes de dar siquiera un sorbo. Icónico.'::text),
(361526,40170,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Honnêtement, tu ... cet énorme mug pendant une minute avant même de boire une gorgée. Iconique.'::text,'avais tenu'::text,'as tenu'::text,'as été tenue'::text,'Honnêtement, tu avais tenu cet énorme mug pendant une minute avant même de boire une gorgée. Iconique.'::text),
(361529,40170,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, sen daha bir yudum bile almadan o dev kupayı bir dakika boyunca ..., ikonik.'::text,'tutmuştun'::text,'tutuyorsun'::text,'tutuldun'::text,'Açıkçası, sen daha bir yudum bile almadan o dev kupayı bir dakika boyunca tutmuştun, ikonik.'::text),
(361530,40170,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, te egy teljes percig ... azt az óriási bögrét, mielőtt egyáltalán belekortyoltál. Ikonikus.'::text,'tartottad'::text,'tartod'::text,'tartva voltál'::text,'Őszintén, te egy teljes percig tartottad azt az óriási bögrét, mielőtt egyáltalán belekortyoltál. Ikonikus.'::text),
(373359,41485,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Standbesitzer sagte, die Zahlung ... komplett in Münzen und Scheinen aus einem Beutel gekommen.'::text,'sei'::text,'ist'::text,'kommt'::text,'Der Standbesitzer sagte, die Zahlung sei komplett in Münzen und Scheinen aus einem Beutel gekommen.'::text),
(373363,41485,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Власник ларька сказав, що оплата ... повністю монетами й купюрами з мішечка.'::text,'надійшла'::text,'надійшла'::text,'надходить'::text,'Власник ларька сказав, що оплата надійшла повністю монетами й купюрами з мішечка.'::text),
(373362,41485,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El dueño del puesto dijo que el pago ... todo en monedas y billetes de una bolsita.'::text,'había llegado'::text,'ha llegado'::text,'llega'::text,'El dueño del puesto dijo que el pago había llegado todo en monedas y billetes de una bolsita.'::text),
(373361,41485,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le propriétaire du stand a dit que le paiement ... entièrement en pièces et en billets sortis d''une bourse.'::text,'était arrivé'::text,'est arrivé'::text,'arrive'::text,'Le propriétaire du stand a dit que le paiement était arrivé entièrement en pièces et en billets sortis d''une bourse.'::text),
(373364,41485,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tezgâh sahibi, ödemenin tamamen bir keseden çıkan bozuk para ve banknotlarla ... söyledi.'::text,'geldiğini'::text,'geldiğini'::text,'geldiğini'::text,'Tezgâh sahibi, ödemenin tamamen bir keseden çıkan bozuk para ve banknotlarla geldiğini söyledi.'::text),
(373365,41485,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A standos azt mondta, hogy a fizetség teljes egészében érmékben és bankjegyekben ... egy erszényből.'::text,'érkezett'::text,'érkezett'::text,'érkezik'::text,'A standos azt mondta, hogy a fizetség teljes egészében érmékben és bankjegyekben érkezett egy erszényből.'::text),
(350922,38992,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während er die Scheine ..., beschloss die Frau, ihr ganzes Geld umzutauschen.'::text,'zählte'::text,'zählte'::text,'gezählt hat'::text,'Während er die Scheine zählte, beschloss die Frau, ihr ganzes Geld umzutauschen.'::text),
(350926,38992,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки він ... купюри, жінка вирішила обміняти всі свої гроші.'::text,'рахував'::text,'порахував'::text,'порахував'::text,'Поки він рахував купюри, жінка вирішила обміняти всі свої гроші.'::text),
(350925,38992,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras él ... los billetes, la mujer decidió cambiar todo su dinero.'::text,'estaba contando'::text,'contó'::text,'ha contado'::text,'Mientras él estaba contando los billetes, la mujer decidió cambiar todo su dinero.'::text),
(350924,38992,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant qu''il ... les billets, la femme a décidé d''échanger tout son argent.'::text,'comptait'::text,'a compté'::text,'a compté'::text,'Pendant qu''il comptait les billets, la femme a décidé d''échanger tout son argent.'::text),
(350927,38992,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O banknotları ..., kadın bütün parasını bozdurmaya karar verdi.'::text,'sayarken'::text,'saydı'::text,'saymış'::text,'O banknotları sayarken, kadın bütün parasını bozdurmaya karar verdi.'::text),
(350928,38992,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben ő ... a bankjegyeket, a nő úgy döntött, hogy az összes pénzét beváltja.'::text,'számolta'::text,'megszámolta'::text,'megszámolta'::text,'Miközben ő számolta a bankjegyeket, a nő úgy döntött, hogy az összes pénzét beváltja.'::text),
(350994,39000,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade ... er ihr Geld um, und sie ist absolut sprachlos!'::text,'tauscht'::text,'tauscht'::text,'tauschte'::text,'Gerade tauscht er ihr Geld um, und sie ist absolut sprachlos!'::text),
(350998,39000,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Саме зараз він ... її гроші, і вона абсолютно втратила дар мови!'::text,'обмінює'::text,'обмінює'::text,'обміняв'::text,'Саме зараз він обмінює її гроші, і вона абсолютно втратила дар мови!'::text),
(350997,39000,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ahora mismo él ... su dinero, y ella se ha quedado completamente sin palabras!'::text,'está cambiando'::text,'cambia'::text,'ha cambiado'::text,'¡Ahora mismo él está cambiando su dinero, y ella se ha quedado completamente sin palabras!'::text),
(350996,39000,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment même, il ... son argent, et elle en reste complètement sans voix !'::text,'est en train d''échanger'::text,'échange'::text,'a échangé'::text,'En ce moment même, il est en train d''échanger son argent, et elle en reste complètement sans voix !'::text),
(350999,39000,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda o onun parasını ... ve kadın tamamen dilini yutmuş durumda!'::text,'bozuyor'::text,'bozar'::text,'bozdu'::text,'Şu anda o onun parasını bozuyor ve kadın tamamen dilini yutmuş durumda!'::text),
(351000,39000,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő épp most ... a pénzét, és a nő teljesen szóhoz sem jut!'::text,'váltja be'::text,'váltja be'::text,'váltotta be'::text,'Ő épp most váltja be a pénzét, és a nő teljesen szóhoz sem jut!'::text),
(331482,36832,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie das letzte Kissen platziert, ... die Reihe ungefähr zwei Meter lang.'::text,'ist'::text,'wäre'::text,'war'::text,'Wenn sie das letzte Kissen platziert, ist die Reihe ungefähr zwei Meter lang.'::text),
(331486,36832,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вона розкладе останню подушку, ряд ... приблизно два метри завдовжки.'::text,'буде'::text,'був би'::text,'був'::text,'Якщо вона розкладе останню подушку, ряд буде приблизно два метри завдовжки.'::text),
(331485,36832,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si ella coloca el último cojín, la fila ... aproximadamente dos metros de largo.'::text,'tendrá'::text,'tendría'::text,'tenía'::text,'Si ella coloca el último cojín, la fila tendrá aproximadamente dos metros de largo.'::text),
(331484,36832,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle dispose le dernier coussin, la rangée ... environ deux mètres de long.'::text,'fera'::text,'ferait'::text,'faisait'::text,'Si elle dispose le dernier coussin, la rangée fera environ deux mètres de long.'::text),
(331487,36832,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O son yastığı da yerleştirirse, sıra yaklaşık iki metre uzunluğunda ...'::text,'olacak'::text,'olurdu'::text,'oldu'::text,'O son yastığı da yerleştirirse, sıra yaklaşık iki metre uzunluğunda olacak.'::text),
(331488,36832,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha ő elrendezi az utolsó párnát, a sor nagyjából két méter hosszú ...'::text,'lesz'::text,'lenne'::text,'volt'::text,'Ha ő elrendezi az utolsó párnát, a sor nagyjából két méter hosszú lesz.'::text),
(384528,42726,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Beamten ... den Koffer zwanzig Minuten lang durchsucht, bevor die Reisende endlich etwas sagte.'::text,'hatten'::text,'haben'::text,'waren'::text,'Die Beamten hatten den Koffer zwanzig Minuten lang durchsucht, bevor die Reisende endlich etwas sagte.'::text),
(384532,42726,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Митники ... валізу двадцять хвилин, поки мандрівниця нарешті не заговорила.'::text,'обшукували'::text,'обшукують'::text,'обшукували'::text,'Митники обшукували валізу двадцять хвилин, поки мандрівниця нарешті не заговорила.'::text),
(384531,42726,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los agentes ... la maleta durante veinte minutos antes de que la viajera por fin hablara.'::text,'habían estado registrando'::text,'han estado registrando'::text,'estaban registrando'::text,'Los agentes habían estado registrando la maleta durante veinte minutos antes de que la viajera por fin hablara.'::text),
(384530,42726,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les douaniers ... la valise depuis vingt minutes quand la voyageuse a enfin parlé.'::text,'fouillaient'::text,'fouillent'::text,'fouillaient'::text,'Les douaniers fouillaient la valise depuis vingt minutes quand la voyageuse a enfin parlé.'::text),
(384533,42726,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yolcu sonunda konuşana kadar memurlar bavulu yirmi dakika boyunca ...'::text,'arıyordu'::text,'arıyor'::text,'arıyordu'::text,'Yolcu sonunda konuşana kadar memurlar bavulu yirmi dakika boyunca arıyordu.'::text),
(384534,42726,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vámtisztek húsz percig ... a bőröndöt, mire az utas végre megszólalt.'::text,'kutatták át'::text,'kutatják át'::text,'kutatták át'::text,'A vámtisztek húsz percig kutatták át a bőröndöt, mire az utas végre megszólalt.'::text),
(403401,44823,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Ende der Fahrt hat der Stromabnehmer der Straßenbahn Hunderte Funken aus dem Draht ...'::text,'geschlagen'::text,'geschlagen'::text,'schlagen'::text,'Bis zum Ende der Fahrt hat der Stromabnehmer der Straßenbahn Hunderte Funken aus dem Draht geschlagen.'::text),
(403405,44823,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До кінця поїздки струмоприймач трамвая ... з дроту сотні іскор.'::text,'виб''є'::text,'виб''є'::text,'вибиватиме'::text,'До кінця поїздки струмоприймач трамвая виб''є з дроту сотні іскор.'::text),
(403404,44823,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el final del trayecto, el brazo del tranvía ... cientos de chispas del cable.'::text,'habrá sacado'::text,'sacará'::text,'estará sacando'::text,'Para el final del trayecto, el brazo del tranvía habrá sacado cientos de chispas del cable.'::text),
(403403,44823,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici la fin du trajet, le bras du tramway ... des centaines d''étincelles du fil.'::text,'aura fait jaillir'::text,'fera jaillir'::text,'sera en train de faire jaillir'::text,'D''ici la fin du trajet, le bras du tramway aura fait jaillir des centaines d''étincelles du fil.'::text),
(403406,44823,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yolculuğun sonuna kadar tramvayın kolu telden yüzlerce kıvılcım ...'::text,'çıkarmış olacak'::text,'çıkaracak'::text,'çıkarıyor olacak'::text,'Yolculuğun sonuna kadar tramvayın kolu telden yüzlerce kıvılcım çıkarmış olacak.'::text),
(403407,44823,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az út végére a villamos áramszedője ... több száz szikrát a vezetékből.'::text,'ki fog csiholni'::text,'ki fog csiholni'::text,'éppen csiholni fog'::text,'Az út végére a villamos áramszedője ki fog csiholni több száz szikrát a vezetékből.'::text),
(342741,38083,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Kupferkessel heiß ..., dehnt sich das Metall aus.'::text,'werden'::text,'werden werden'::text,'wurden'::text,'Wenn die Kupferkessel heiß werden, dehnt sich das Metall aus.'::text),
(342745,38083,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли мідні чани ..., метал розширюється.'::text,'нагріваються'::text,'нагріються'::text,'нагрілися'::text,'Коли мідні чани нагріваються, метал розширюється.'::text),
(342744,38083,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si los tanques de cobre se ..., el metal se dilata.'::text,'calientan'::text,'calentarán'::text,'calentaron'::text,'Si los tanques de cobre se calientan, el metal se dilata.'::text),
(342743,38083,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si les cuves en cuivre ... chaudes, le métal se dilate.'::text,'deviennent'::text,'deviendront'::text,'devenaient'::text,'Si les cuves en cuivre deviennent chaudes, le métal se dilate.'::text),
(342746,38083,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bakır kazanlar ..., metal genleşir.'::text,'ısınırsa'::text,'ısınacaksa'::text,'ısındıysa'::text,'Bakır kazanlar ısınırsa, metal genleşir.'::text),
(342747,38083,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a rézüstök ..., a fém kitágul.'::text,'felmelegszenek'::text,'fel fognak melegedni'::text,'felmelegedtek'::text,'Ha a rézüstök felmelegszenek, a fém kitágul.'::text),
(342804,38090,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du ... schon seit Jahren unter diesen Kupferkesseln, und das sieht man.'::text,'arbeitest'::text,'arbeitest'::text,'arbeitest'::text,'Ehrlich, du arbeitest schon seit Jahren unter diesen Kupferkesseln, und das sieht man.'::text),
(342808,38090,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти ... під цими мідними чанами вже роками, і це помітно.'::text,'працюєш'::text,'працюєш'::text,'працюєш'::text,'Чесно, ти працюєш під цими мідними чанами вже роками, і це помітно.'::text),
(342807,38090,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, tú ... bajo estos tanques de cobre desde hace años, y se nota.'::text,'trabajas'::text,'estás trabajando'::text,'trabajas'::text,'Sinceramente, tú trabajas bajo estos tanques de cobre desde hace años, y se nota.'::text),
(342806,38090,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Honnêtement, tu ... sous ces cuves en cuivre depuis des années, et ça se voit.'::text,'travailles'::text,'travailles'::text,'travailles'::text,'Honnêtement, tu travailles sous ces cuves en cuivre depuis des années, et ça se voit.'::text),
(342809,38090,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, sen yıllardır bu bakır kazanların altında ... ve belli oluyor.'::text,'çalışıyorsun'::text,'çalışıyorsun'::text,'çalışırsın'::text,'Açıkçası, sen yıllardır bu bakır kazanların altında çalışıyorsun ve belli oluyor.'::text),
(342810,38090,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, te évek óta ... ezek alatt a rézüstök alatt, és meg is látszik.'::text,'dolgozol'::text,'dolgozol'::text,'dolgozol'::text,'Őszintén, te évek óta dolgozol ezek alatt a rézüstök alatt, és meg is látszik.'::text),
(359274,39920,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bei all den Luftschlangen in jeder Ecke ... es heute Abend eine Party geben.'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Bei all den Luftschlangen in jeder Ecke muss es heute Abend eine Party geben.'::text),
(359278,39920,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли з кожного кута звисають серпантини, сьогодні ввечері ... бути вечірка.'::text,'мусить'::text,'не може'::text,'мала б'::text,'Коли з кожного кута звисають серпантини, сьогодні ввечері мусить бути вечірка.'::text),
(359277,39920,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Con serpentinas colgando de cada rincón, esta noche ... haber una fiesta.'::text,'debe de'::text,'no puede'::text,'debería'::text,'Con serpentinas colgando de cada rincón, esta noche debe de haber una fiesta.'::text),
(359276,39920,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avec des serpentins qui pendent dans chaque coin, il ... y avoir une fête ce soir.'::text,'doit'::text,'ne peut pas'::text,'devrait'::text,'Avec des serpentins qui pendent dans chaque coin, il doit y avoir une fête ce soir.'::text),
(359279,39920,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her köşeden serpantinler sarkarken bu akşam bir parti ...'::text,'olmalı'::text,'olamaz'::text,'olması gerekir'::text,'Her köşeden serpantinler sarkarken bu akşam bir parti olmalı.'::text),
(359280,39920,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha minden sarokból szerpentinek lógnak, ma este ... buli.'::text,'biztosan lesz'::text,'nem lehet'::text,'elvileg lesz'::text,'Ha minden sarokból szerpentinek lógnak, ma este biztosan lesz buli.'::text),
(359346,39928,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, um Mitternacht ... er schon so sechs Stunden Lichter auf, ziemlich durchgeknallt.'::text,'hängt'::text,'hängt'::text,'hängte'::text,'Bro, um Mitternacht hängt er schon so sechs Stunden Lichter auf, ziemlich durchgeknallt.'::text),
(359350,39928,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, до півночі він ... гірлянди десь шість годин, трохи дичина.'::text,'вішатиме'::text,'вішатиме'::text,'повісив'::text,'Бро, до півночі він вішатиме гірлянди десь шість годин, трохи дичина.'::text),
(359349,39928,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, a medianoche él ... luces unas seis horas, medio desquiciado.'::text,'llevará colgando'::text,'estará colgando'::text,'ha colgado'::text,'Bro, a medianoche él llevará colgando luces unas seis horas, medio desquiciado.'::text),
(359348,39928,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, à minuit, ça fera genre six heures qu''il ... des guirlandes, un peu barré.'::text,'accroche'::text,'accroche'::text,'a accroché'::text,'Frère, à minuit, ça fera genre six heures qu''il accroche des guirlandes, un peu barré.'::text),
(359351,39928,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, gece yarısına kadar o altı saat gibi ışık ..., biraz kafayı yemiş.'::text,'asıyor olacak'::text,'asıyor olacak'::text,'astı'::text,'Kanka, gece yarısına kadar o altı saat gibi ışık asıyor olacak, biraz kafayı yemiş.'::text),
